import { useMemo } from "react";
function useRemoteBreadcrumbs(ancestryChain, rootTitle) {
    return useMemo(()=>{
        const rootItem = {
            assetId: '',
            label: rootTitle
        };
        if (0 === ancestryChain.length) return [
            rootItem
        ];
        return [
            rootItem,
            ...ancestryChain.map((item)=>({
                    assetId: item.id,
                    label: item.displayName
                }))
        ];
    }, [
        ancestryChain,
        rootTitle
    ]);
}
export { useRemoteBreadcrumbs };
