function inferEnvironment({
    version,
    hostname,
    environment = process.env.NODE_ENV, // Sentry's default in node projects
}) {
    if (
        version &&
        (version.includes('.pr') ||
            version.includes('main') ||
            version.includes('dev'))
    ) {
        return 'preview'; // All builds that include ".pr" or "main" or "dev" in version map to the preview envionment e.g. 4.2.15-6931-42.pr, 28.1.0-main-1 and 2.30.0-dev-3
    }

    if (
        (hostname && hostname.includes('aw-ube')) ||
        (hostname && hostname.includes('prenv')) ||
        (hostname && hostname.includes('ace-web-apps'))
    ) {
        return 'preview'; // Hostname includes "aw-ube", "prenv", or "ace-web-apps", assume preview environment e.g. https://aw-ube.ccpd.adobe.com, *.prenv.projectx.corp.adobe.com, Storybook preview hosts
    }

    if (hostname && hostname.includes('stage')) {
        return 'staging'; // Hostname includes "stage", assume staging environment e.g. *.stage.adobe.com, stage.*.corp.adobe.com
    }

    if (
        (hostname && hostname.includes('localhost')) ||
        (hostname && hostname.includes('dev.adobe.com'))
    ) {
        return 'development'; // Hostname includes "localhost" or "dev.aodbe.com", assume localhost environment e.g. localhost, localhost.adobe.com, cclibrariespanel-cdn.dev.adobe.com
    }

    return environment;
}

module.exports = { inferEnvironment };
