const sortDirToAssetOrderDirection = (sortDir)=>'desc' === sortDir ? 'descending' : 'ascending';
const sortByToAssetOrderField = (sortBy)=>{
    switch(sortBy){
        case 'createDate':
            return 'created';
        case 'modifiedDate':
            return 'modified';
        case 'shareDate':
            return 'shared';
        case 'title':
        default:
            return 'name';
    }
};
export { sortByToAssetOrderField, sortDirToAssetOrderDirection };
