import type { Icon } from '@ccx-public/spectrum-web-component-fallbacks/dist/icon';
import type { ReactProps, SpectrumElementProps } from '../utils';

type RS2Size = 'XXS' | 'XS' | 'S' | 'M' | 'L' | 'XL' | 'XXL';
type SWCSize = Icon['size'];

function getSWCSize(size?: RS2Size): SWCSize {
    // The sizing differences between RS2 and SWC are pretty wild. Since we're
    // supporting the RS2 interface, we give the closest approximation to each
    // size in SWC.
    switch (size) {
        case 'XXS': // 10px
            return 'xs'; // 14px
        case 'XS': // 12px
            return 's'; // 16px
        case 'S': // 18px
            return 'm'; // 18px
        case 'M': // 24px
            return 'xl'; // 22px
        case 'L': // 36px
        case 'XL': // 48px
        case 'XXL': // 72px
            return 'xxl'; // 32px
        // RS2 default is 'M'
        default:
            return 'xl'; // SWC equivalent is xl.
    }
}

export type RS2IconProps = {
    alt?: string;
    'aria-label'?: string;
    size?: RS2Size;
};

export function getSWCProps(
    props: ReactProps<Icon, RS2IconProps>
): SpectrumElementProps<Icon> {
    const { alt, className, 'aria-label': ariaLabel, size, ...rest } = props;
    return {
        ...rest,
        class: className,
        label: alt || ariaLabel,
        size: getSWCSize(size),
    };
}
