class CreateSuccessEvent extends CustomEvent {
    static{
        this.EVENT_NAME = 'create-success';
    }
    constructor(detail){
        super(CreateSuccessEvent.EVENT_NAME, {
            bubbles: true,
            composed: true,
            detail
        });
    }
}
