import React from 'react';

// RS2 :: https://react-spectrum.corp.adobe.com/storybook/?path=/story/fieldlabel--default
// SWC :: https://opensource.adobe.com/spectrum-web-components/components/field-label/
import type { FieldLabel as FieldLabelType } from '@ccx-public/spectrum-web-component-fallbacks/dist/field-label';
import { filterBooleanProps, useComponent } from './utils';
import createWrapper from './utils/createWrapper';
import { SWCLoader } from './utils/SWCLoader';
import interopRequireDefault from './utils/interopRequireDefault';

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2FieldLabel: React.ComponentType<unknown> = process.env.INCLUDE_RS2
    ? interopRequireDefault(require('react-spectrum/FieldLabel')).default
    : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

let swcLoader;
if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(['sp-field-label'], async () => {
        const { FieldLabel } = await import(
            /* webpackChunkName: "SpFieldLabel" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/field-label'
        );
        return [FieldLabel];
    });
}

type RS2CompatProps = {
    /**
     * String to display
     */
    label?: string;
    /**
     * Justification of the label text within its container. Setting this property
     * will situate the label container to the left of the form field, regardless
     * of the property value.
     */
    position?: 'left' | 'right';
    /**
     * Like in a form, with what input should the label be associated
     */
    labelFor?: string;
    /**
     * Style for communicating whether the associated input is required or optional.
     */
    necessity?: 'required' | 'optional';
};

export default createWrapper<FieldLabelType, RS2CompatProps>({
    displayName: 'FieldLabel',
    fallback: RS2FieldLabel,
    swcLoader,
    SWCWrapper: function SpFieldLabel(props) {
        const {
            className,
            label,
            necessity,
            position,
            labelFor,
            children,
            ...rest
        } = props;
        // mapping necessity to required and sideAligned to position
        // ReactSpectrum2        | SpectrumWebComponent
        // ---------------------------------------------
        // necessity             | required
        // position              | sideAligned
        // for                   | labelFor
        // label passed as child | label is prop

        const required = necessity === 'required' ? true : false;
        const sideAligned =
            position === 'left'
                ? 'start'
                : position === 'right'
                ? 'end'
                : undefined;

        const compatProps = {
            ...rest,
            ...filterBooleanProps({
                required,
            }),
            'side-aligned': sideAligned,
            children: label,
            class: className,
            for: labelFor,
        };

        const Fieldlabel = useComponent('sp-field-label');
        // label is passed as children and other childrens would be rendered after sp-fieldlabel to comply with the behaviour of swc.
        return (
            <>
                <Fieldlabel {...compatProps} />
                {children}
            </>
        );
    },
    tagName: 'sp-field-label',
});
