// SWC Props Link :: https://opensource.adobe.com/spectrum-web-components/components/search/api/
// RS2 Props Link :: https://react-spectrum.corp.adobe.com/storybook/?path=/story/search
import React, { forwardRef, useEffect, useRef } from 'react';
import type { RS2TextfieldCompatProps } from './Textfield';
import { convertTextfieldPropsToSWC } from './Textfield';
import type { Search as SearchType } from '@ccx-public/spectrum-web-component-fallbacks/dist/search';
import createWrapper from './utils/createWrapper';
import interopRequireDefault from './utils/interopRequireDefault';
import { SWCLoader } from './utils/SWCLoader';
import type { ReactProps } from './utils';
import { useComponent } from './utils';
import mergeRefs from './utils/mergeRefs';

export type RS2SearchCompatProps = RS2TextfieldCompatProps & {
    // Function called when the Enter key is pressed
    onSubmit?: (value: string, event?: Event) => unknown;
};

let swcLoader: SWCLoader | undefined;

if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(['sp-search'], async () => {
        const { Search } = await import(
            /* webpackChunkName: "SpSearch" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/search'
        );
        return [Search];
    });
}

type SearchProps = ReactProps<SearchType, RS2SearchCompatProps>;

export { swcLoader };

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2Search: React.ComponentType<unknown> = process.env.INCLUDE_RS2
    ? interopRequireDefault(require('react-spectrum/Search')).default
    : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

export default createWrapper<SearchType, RS2SearchCompatProps>({
    displayName: 'Search',
    fallback: RS2Search,
    swcLoader,
    SWCWrapper: forwardRef(function SpSearch(props: SearchProps, ref) {
        const searchRef = useRef<SearchType>(null);
        const { onChange, onSubmit, ...rest } = props;

        useEffect(() => {
            const { current } = searchRef;

            const handleInput = (event: Event) => {
                const target = event.target as HTMLInputElement;

                onChange?.(target.value, event);
            };

            if (current && onChange) {
                current.addEventListener('input', handleInput);
            }

            return () => {
                if (current && onChange) {
                    current.removeEventListener('input', handleInput);
                }
            };
        }, [onChange]);

        useEffect(() => {
            const { current } = searchRef;

            const handleSubmit = (event: Event) => {
                event.preventDefault();
                event.stopPropagation();

                const target = event.target as HTMLInputElement;
                onSubmit?.(target.value, event);
            };

            if (current && onSubmit) {
                current.addEventListener('submit', handleSubmit);
            }

            return () => {
                if (current && onSubmit) {
                    current.removeEventListener('submit', handleSubmit);
                }
            };
        }, [onSubmit]);

        const Search = useComponent('sp-search');
        return (
            <Search
                ref={mergeRefs([ref, searchRef])}
                {...convertTextfieldPropsToSWC(rest)}
            />
        );
    }),
    tagName: 'sp-search',
});
