/**
 * @param data a string that may have enclosing quotes
 * @returns the string without enclosing quotes
 */
export function removeEnclosingQuotes(data) {
    return data.replace(/(["'])(.*)\1/, "$2"); // remove a pair of enclosing single or double quotes.
}
