import { SourceType } from "@dunamis-public/types";
import * as constants from "@dunamis-common/constants";
export class MetaEvent {
    static createInitMetaEvent(sourceType, configGuid) {
        return {
            [constants.key_data_event_workflow]: constants.val_workflow_lifecycle,
            [constants.key_data_event_subcategory]: sourceType === SourceType.HOST ? constants.val_sub_category_host : constants.val_sub_category_component,
            [constants.key_data_event_type]: constants.val_type_success,
            [constants.key_data_event_subtype]: constants.val_sub_type_init,
            [constants.key_data_entity_config]: { [constants.key_config_entity_guid]: configGuid },
        };
    }
    static createExitMetaEvent(sourceType, configGuid) {
        return {
            [constants.key_data_event_workflow]: constants.val_workflow_lifecycle,
            [constants.key_data_event_subcategory]: sourceType === SourceType.HOST ? constants.val_sub_category_host : constants.val_sub_category_component,
            [constants.key_data_event_type]: constants.val_type_success,
            [constants.key_data_event_subtype]: constants.val_sub_type_exit,
            [constants.key_data_entity_config]: { [constants.key_config_entity_guid]: configGuid },
        };
    }
    static createHeartBeatMetaEvent() {
        return {
            [constants.key_data_event_workflow]: constants.val_workflow_dunamis,
            [constants.key_data_event_subcategory]: constants.val_sub_category_sdk,
            [constants.key_data_event_type]: constants.val_type_heartbeat,
            [constants.key_data_event_subtype]: constants.val_sub_type_app,
        };
    }
}
