/**
 * Valid Sentry environment values returned by inferEnvironment
 */
type SentryEnvironment = 'production' | 'staging' | 'preview' | 'development';

function isDisabledRoute(sdkInterface?: IRootSDK): boolean {
    if (typeof window === 'undefined' || !window.location) {
        return false;
    }
    // Only disable Sentry for routes containing /id/ when clientId is PSWebApp1 or appId is photoshop_web
    // This scopes the /id/ route exclusion to PS Web specifically
    // Routes can be /id/... or /video/editor/id/... so we use includes()
    const config = sdkInterface?.getConfig();
    // eslint-disable-next-line @typescript-eslint/no-deprecated -- clientId needed for PS Web route exclusion
    const clientId = config?.clientId;
    const appId = config?.appId;
    const isPSWebApp = clientId === 'PSWebApp1' || appId === 'photoshop_web';
    if (!isPSWebApp) {
        return false;
    }
    // Check if pathname contains /id/ anywhere (e.g., /id/asset or /video/editor/id/asset)
    return window.location.pathname.includes('/id/');
}

/**
 * Safely checks if profiling override is enabled via localStorage.
 * Handles SecurityError that can occur in Safari Private Browsing mode.
 */
function isProfilingEnabled(): boolean {
    if (typeof localStorage === 'undefined') {
        return false;
    }
    try {
        return !!localStorage.getItem('__aupsdk_profiling__');
    } catch {
        return false;
    }
}

/**
 * Determine whether Sentry should be enabled.
 *
 * Decision order:
 * - If profiling override is enabled (__aupsdk_profiling__), always enable (dev tool)
 * - If host explicitly disables via `false`, return false
 * - If current route matches /id/* pattern (editor routes), return false
 * - Otherwise enable when either environment flags are present (CI or ENABLE_SENTRY)
 *   or the host provides truthy config (true or BrowserOptions with `enabled` not false)
 *
 * @param sentryConfig Optional host-provided Sentry setting: `false` to disable, `true` to enable with defaults,
 *                     or a `BrowserOptions` object whose `enabled` may override.
 * @returns True when Sentry should be enabled for this runtime.
 */
function isSentryEnabled(sdkInterface?: IRootSDK): boolean {
    if (isProfilingEnabled()) {
        return true;
    }

    const config = sdkInterface?.getConfig();
    const sentryConfig = config?.sentry;

    const envEnabled = !!(process.env.IS_CI || process.env.ENABLE_SENTRY);
    const hostDisabledExplicitly = sentryConfig === false;
    const hostEnabled =
        sentryConfig === true ||
        (typeof sentryConfig === 'object' && sentryConfig.enabled !== false);

    if (hostDisabledExplicitly) {
        return false;
    }

    if (isDisabledRoute(sdkInterface)) {
        return false;
    }

    return envEnabled || hostEnabled;
}

/** Mount points to strip from paths (e.g. /your-stuff, /files) */
const COMMON_MOUNT_POINTS = ['/your-stuff', '/files'];

/** Tab param values mapped to canonical routes */
const TAB_TO_ROUTE: Record<string, string> = {
    'shared-with-you': '/shared',
    projects: '/projects',
    favorites: '/favorites',
    files: '/files',
    libraries: '/libraries',
    'cloud-documents': '/files',
    deleted: '/deleted',
    generationHistory: '/generation-history',
    'generation-history': '/generation-history',
};

/** Query params that represent assetId (aliases) */
const ASSET_ID_PARAMS = [
    'projectId',
    'libraryId',
    'fileId',
    'assetId',
    'documentId',
    'classroomId',
    'cloudid',
];

/** URN pattern for Adobe asset identifiers */
const URN_PATTERN = /^urn:aaid:sc:[^/]+$/i;

/** Checks if a path segment is an asset ID (URN) */
function isAssetIdSegment(segment: string): boolean {
    return URN_PATTERN.test(segment);
}

/**
 * Normalizes routes for Sentry transaction grouping per URL parsing logic.
 *
 * - Maps routes from different host aliases to canonical forms
 * - Normalizes mount points (/your-stuff, /files) to canonical paths
 * - Normalizes UUID/URN identifiers to :assetId placeholder
 * - Maps query param based routes (tab=) to canonical paths
 * - Tag transactions with full original URL before mapping (caller responsibility)
 */
export function normalizeRoute(route: string): { normalized: string; wasNormalized: boolean } {
    const url = new URL(route, 'http://x');
    let path = url.pathname;
    let pathBecameRootFromMountStrip = false;

    let changed = true;
    while (changed) {
        changed = false;
        for (const mount of COMMON_MOUNT_POINTS) {
            if (path === mount || path === `${mount}/`) {
                const next = url.searchParams.get('tab')
                    ? TAB_TO_ROUTE[url.searchParams.get('tab')!] ??
                      `/${url.searchParams.get('tab')}`
                    : '/files';
                if (next !== path) {
                    path = next;
                    changed = true;
                }
                break;
            }
            if (path.startsWith(`${mount}/`)) {
                const next = path.slice(mount.length) || '/';
                if (next.startsWith('/:')) {
                    break;
                }
                if (next !== path) {
                    path = next;
                    pathBecameRootFromMountStrip = path === '/';
                    changed = true;
                }
                break;
            }
        }
    }

    // Handle root path with tab param (e.g. /?tab=cloud-documents → /files)
    const tab = url.searchParams.get('tab');
    if (path === '/' && tab) {
        path = TAB_TO_ROUTE[tab] ?? `/${tab}`;
    }

    const assetIdFromQuery = ASSET_ID_PARAMS.map((p) => url.searchParams.get(p)).find(Boolean);
    if (assetIdFromQuery && (path === '/projects' || path === '/files' || path === '/libraries')) {
        path = `${path}/:assetId`;
    } else if (path && path !== '/') {
        const segments = path.split('/').filter(Boolean);
        const normalizedSegments = segments.map((seg) =>
            isAssetIdSegment(seg) ? ':assetId' : seg,
        );
        path = '/' + normalizedSegments.join('/');
    }

    // Only map / → /files when / came from stripping a mount point (e.g. /files/).
    // Do NOT map the literal root / — that's the web landing page, not the files view.
    if (path === '/' && pathBecameRootFromMountStrip) {
        path = '/files';
    }

    const normalized = path;
    return { normalized, wasNormalized: normalized !== route };
}

const AUP_SDK_DSN =
    'https://fd9c1a6df892638983bc9f229637aca2@o1383653.ingest.us.sentry.io/4509476881498112';

const sharedComponentsPattern = /^(?!.*(shared-components|ims|typekit)).*$/i;

/**
 * Checks if user consented to "Measure performance" cookies
 * by inspecting the OneTrust `OptanonConsent` cookie.
 *
 * The `OptanonConsent` cookie contains a URL-encoded query string
 * with multiple key-value pairs, including a `groups` key:
 *
 * Example encoded cookie value (as it appears in document.cookie):
 * OptanonConsent=groups=C0001%3A1%2CC0002%3A0%2CC0003%3A1%2CC0004%3A1&...
 *
 * Example decoded cookie value:
 * groups=C0001:1,C0002:0,C0003:1,C0004:0&
 * isGpcEnabled=0&
 * datestamp=Wed Sep 24 2025 17:07:48 GMT-0700 (Pacific Daylight Time)&
 * version=202501.1.0&
 * browserGpcFlag=0&
 * geolocation=US;UT&
 * isIABGlobal=false&
 * hosts=&
 * consentId=1b82797c-0b98-4f8e-93ec-00e906168d17&
 * interactionCount=0&
 * isAnonUser=1&
 * landingPath=https://www.adobe.com/privacy/opt-out.html
 *
 * The `groups` value lists consent categories and user choice (1=consent, 0=decline):
 * - C0001: Operate the site and core services (Always active, cannot be disabled)
 * - C0002: Measure performance (Analyze site usage, measure and improve performance)
 * - C0003: Extend functionality (Remember preferences, personalize experience)
 * - C0004: Personalize advertising (Ads relevance)
 *
 * Source & more info: https://www.adobe.com/privacy/opt-out.html
 *
 * Strategy: Allow performance tracking by default, only disable if explicitly declined.
 * - No cookie present (local dev): Allow
 * - Cookie with C0002:1 or C0002%3A1 (consent given): Allow
 * - Cookie with C0002:0 or C0002%3A0 (consent declined): Disallow
 * - localStorage.__aupsdk_profiling__ = 'true': Always allow (for debugging)
 *
 * @returns {boolean} True if performance measurement cookies are allowed, else false.
 */
function isPerformanceAllowed(): boolean {
    if (isProfilingEnabled()) {
        return true;
    }

    // Only disable if consent is explicitly declined
    // Check both encoded (C0002%3A0) and decoded (C0002:0) forms
    return (
        typeof document === 'undefined' ||
        (!document.cookie.includes('C0002:0') && !document.cookie.includes('C0002%3A0'))
    );
}

let sentryInitialized = false;
let loadingPerformanceInstrumentation: LoadingInstrumentation | undefined;
let sentryClient; // Store client for manual span creation
let lastUITransactionName: string | undefined; // If undefined, treat as first (pageload)
let dunamisAbortController: AbortController | undefined;

/**
 * Checks if a route is a canonical route based on the CanonicalRoute type definition.
 */
export function isCanonicalRoute(route: string): boolean {
    const routeWithoutQuery = route.split('?')[0].split('#')[0];

    const canonicalPattern =
        /^(\/recents|\/favorites|\/libraries|\/files|\/cloud-documents|\/links|\/shared|\/deleted|\/open|\/save|\/export|\/projects|\/classrooms|\/generate\/[^/]+|\/generation-history|\/your-stuff)(\/.*)?$/;

    return canonicalPattern.test(routeWithoutQuery);
}

/**
 * Converts boolean values in tags to string representations.
 * Addresses Sentry issue: https://github.com/getsentry/sentry/issues/98611
 */
function convertBooleanTags(tags: Record<string, unknown>): void {
    Object.keys(tags).forEach((key) => {
        const value = tags[key];
        if (typeof value === 'boolean') {
            tags[key] = value ? 'True' : 'False';
        }
    });
}

const REDACTED_TEXT = 'REDACTED';

/**
 * Recursively collects innerText from non-confidential child elements.
 * Skips any elements marked with data-confidential="true" and their children.
 * @param element - The parent element to traverse
 * @returns A string containing the concatenated innerText of non-confidential children
 */
const getFilteredInnerText = (element: HTMLElement): string => {
    // If the element is within a confidential parent OR itself is confidential, return redacted text
    if (element.closest('[data-confidential]')) {
        return REDACTED_TEXT;
    }

    // Store reference so we don't trigger extra reflows (coerce to string for JSDOM/older envs)
    const innerText =
        element.innerText !== null && element.innerText !== undefined
            ? String(element.innerText)
            : '';

    // If the element has no text content then there is nothing to redact, return an empty string
    if (!innerText) {
        return '';
    }

    // Find any confidential children
    const toRedact = element.querySelectorAll('[data-confidential]');

    // If there are no confidential children then return the inner text without any redacted text
    if (toRedact.length === 0) {
        return innerText;
    }

    // Get the text of each confidential child
    const textsToRedact = Array.from(
        new Set(
            Array.from(toRedact)
                .map((x) => {
                    const raw = (x as HTMLElement).innerText;
                    const str = raw !== null && raw !== undefined ? String(raw) : '';
                    return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); // Escape characters that break regex
                })
                .filter(Boolean),
        ),
    ).sort((a, b) => b.length - a.length); // Sort by length (longest first) to ensure longer matches take precedence

    // Replace all instances of the found text (use replace with global regex for replaceAll compatibility in older envs)
    const redactRe = new RegExp(`(${textsToRedact.join('|')})`, 'g');
    return innerText.replace(redactRe, `${REDACTED_TEXT} `).replace(/\s/g, ' ').trim();
};

export function fetchWithRequestId(baseFetch: typeof fetch): typeof fetch {
    return async function (input: RequestInfo | URL, init?: RequestInit): Promise<Response> {
        const headers = new Headers(init?.headers || {});

        if (!headers.has('X-Request-Id')) {
            headers.set('X-Request-Id', uuidv4());
        }

        return await baseFetch(input, { ...init, headers });
    };
}

export function fetchWithTraceParent(baseFetch: typeof fetch): typeof fetch {
    return async function (input: RequestInfo | URL, init?: RequestInit): Promise<Response> {
        const headers = new Headers(init?.headers || {});
        const traceHeaders = getTraceData?.() ?? {};
        const sentryTrace = (traceHeaders as Record<string, string>)['sentry-trace'];

        if (!headers.has('traceparent') && sentryTrace) {
            headers.set('traceparent', sentryTrace);
        }

        return await baseFetch(input, { ...init, headers });
    };
}

/**
 * Environment-agnostic patterns for URLs that should skip telemetry
 * These patterns target endpoints that don't support tracing headers cross-origin
 */
const TELEMETRY_SKIP_PATTERNS = [
    /adobesearch[^/]*\.adobe\.io/i, // USS v1, v2
    /acp-asset-ussv3[^/]*\.adobe\.io/i, // USS v3
];

function shouldSkipTelemetry(url: string): boolean {
    return TELEMETRY_SKIP_PATTERNS.some((pattern) => pattern.test(url));
}

export function fetchWithTelemetry(baseFetch: typeof fetch): typeof fetch {
    return async function (input: RequestInfo | URL, init?: RequestInit): Promise<Response> {
        const url =
            typeof input === 'string' ? input : input instanceof URL ? input.toString() : input.url;

        if (shouldSkipTelemetry(url)) {
            return await baseFetch(input, init);
        }

        return await fetchWithTraceParent(fetchWithRequestId(baseFetch))(input, init);
    };
}

type DynamicDsnRoute = { pattern: RegExp; dsn: string };
const dynamicDsnRoutes: DynamicDsnRoute[] = [];

type ComponentOverrideObject = {
    url?: string;
    version?: string;
    [key: string]: unknown;
};

type ComponentOverridesMap = Record<string, string | ComponentOverrideObject>;

function parseOverride(value: string | ComponentOverrideObject): ComponentOverrideObject {
    return typeof value === 'string' ? { url: value } : value;
}

const telemetrySdk: Telemetry.TelemetrySDK = {
    registerDSN(pattern: RegExp | string, dsn: string) {
        if (!pattern || !dsn) {
            return;
        }
        const compiled = typeof pattern === 'string' ? new RegExp(pattern, 'i') : pattern;
        dynamicDsnRoutes.push({ pattern: compiled, dsn });
    },
    getAdvancedTelemetryContext() {
        return {
            startSpan,
            captureException,
            setTag,
            getTraceData,
            fetchWithRequestId,
            fetchWithTraceParent,
            fetchWithTelemetry,
        };
    },
    startUITransaction(route: string): void {
        const isPageload = !lastUITransactionName;

        // For navigations, reset loading metrics immediately so marks align with
        // the new transaction start. Skip for the initial pageload because the
        // constructor already placed marks at time 0 which aligns with the
        // pageload transaction's start at performance.timeOrigin.
        if (!isPageload) {
            loadingPerformanceInstrumentation?.resetForNavigation(true);
        }

        lastUITransactionName = normalizeRoute(route).normalized;

        if (!sentryClient) {
            return;
        }

        // Pass the raw route — beforeStartSpan handles normalization and
        // setting transaction.original as a span attribute in one place.
        if (isPageload) {
            startBrowserTracingPageLoadSpan(sentryClient, {
                name: route,
            });
        } else {
            startBrowserTracingNavigationSpan(sentryClient, {
                name: route,
            });
        }
    },
    startNestedUITransaction(nestedUIState: Record<string, string>): void {
        const baseName = lastUITransactionName;
        const usp = new URLSearchParams(nestedUIState || {});
        const str = usp.toString();
        const prefixed = str ? `?${str}` : '';
        const transactionName = baseName ? `${baseName}${prefixed}` : prefixed;

        if (!sentryClient) {
            return;
        }
        if (baseName) {
            startBrowserTracingNavigationSpan(sentryClient, {
                op: 'navigation',
                name: transactionName || baseName,
            });
            lastUITransactionName = baseName;
        }
    },
};

export async function getAdvancedTelemetryContext(): Promise<Telemetry.AdvancedTelemetryContext> {
    return telemetrySdk.getAdvancedTelemetryContext();
}

// Dispose method to properly clean up state
export function dispose(): void {
    // Close Sentry client if it exists (before clearing the reference)
    if (sentryClient && typeof sentryClient.close === 'function') {
        sentryClient.close();
    }

    // Abort Dunamis integration to stop ingest instance
    if (dunamisAbortController) {
        dunamisAbortController.abort();
        dunamisAbortController = undefined;
    }

    // Reset all internal state
    sentryInitialized = false;
    sentryClient = undefined;
    lastUITransactionName = undefined;

    // Clear dynamic DSN routes
    dynamicDsnRoutes.length = 0;

    // Stop performance tracker if running
    loadingPerformanceInstrumentation?.dispose();
    loadingPerformanceInstrumentation = undefined;
}

export function initSentry(
    sdkOrConfig?: IRootSDK | AssetBrowser.InitOptions,
): Telemetry.TelemetrySDK {
    if (sentryInitialized) {
        return telemetrySdk;
    }

    if ((globalThis as any).__SENTRY__) {
        console?.warn(
            '[UAB Sentry] Sentry already initialized on document, skipping initialization to avoid duplicate instances',
        );

        sentryInitialized = true;

        return telemetrySdk;
    }

    sentryInitialized = true;

    const profilingEnabled = isProfilingEnabled();

    const sdkInterface: IRootSDK =
        sdkOrConfig && 'getConfig' in sdkOrConfig
            ? sdkOrConfig
            : ({ getConfig: () => sdkOrConfig } as unknown as IRootSDK);

    const initConfig =
        sdkOrConfig && ('getConfig' in sdkOrConfig ? sdkOrConfig.getConfig() : sdkOrConfig);

    // Allow host to control Sentry via `sentry` config:
    // - false: initialize with enabled=false
    // - true: enable with defaults
    // - object: merge as BrowserOptions
    const sentryConfig = (initConfig as { sentry?: unknown } | undefined)?.sentry as
        | boolean
        | BrowserOptions
        | undefined;

    // Calculate environment early so it can be passed to DunamisIntegration
    const environment: SentryEnvironment = inferEnvironment({
        version: process.env.VERSION,
        hostname: window?.location?.hostname,
        environment: process.env.IS_CI ? 'production' : 'development',
    });

    const requiredIntegrations = [
        rewriteFramesIntegration({
            iteratee: (frame) => {
                const originalPath = frame.abs_path || frame.filename || '';
                const filename = frame.filename?.toLowerCase() || '';
                const inlineScript = !filename.match(/.js[x?]?$/);

                // Default to in_app = false to prevent host application errors from flooding component projects
                // Only mark as in_app if frame matches a registered DSN pattern
                let isInApp = false;

                // Use registered DSN patterns for specific routing decisions
                // Only frames matching registered patterns should be considered in_app
                const frameUrl = frame.abs_path || frame.filename || '';
                const matchingRoute = dynamicDsnRoutes.find((route) =>
                    route.pattern.test(String(frameUrl)),
                );

                // Only mark as in_app if there's a matching DSN route and it's not an inline script
                if (matchingRoute && !inlineScript) {
                    isInApp = true;
                }

                frame.in_app = isInApp;
                frame.filename = `/${basename(frame.filename || '')}`;
                if (originalPath) {
                    frame.abs_path = originalPath;
                }

                return frame;
            },
        }),
        featureFlagsIntegration(),
        // forwards telemetry events to Dunamis endpoint asynchronously via Dunamis SDK
        (() => {
            const controller = new AbortController();
            dunamisAbortController = controller;
            return new DunamisIntegration(sdkInterface, {
                project: 'acpc-perf-service',
                environment,
                abortSignal: controller.signal,
            });
        })() as any,
    ];

    if (globalThis.cc_asset_browser || profilingEnabled) {
        const hasHistory = !!globalThis.history;
        const isInWebview = !!globalThis.uxpHost;
        const hasReadyState =
            typeof document !== 'undefined' && typeof document.readyState !== 'undefined';
        const shouldAutoInstrument = hasHistory && !isInWebview && hasReadyState;
        const performanceConsent = isPerformanceAllowed();

        // Only enable auto-instrumentation if we have performance consent AND we're in a proper browser environment
        // Note: document.readyState is required to prevent infinite loop in Sentry's web vitals code
        // https://github.com/getsentry/sentry-javascript/blob/develop/packages/browser-utils/src/metrics/web-vitals/onTTFB.ts#L35
        const enableAutoInstrumentation = shouldAutoInstrument && performanceConsent;

        requiredIntegrations.push(
            browserTracingIntegration({
                instrumentNavigation: enableAutoInstrumentation,
                instrumentPageLoad: enableAutoInstrumentation,
                idleTimeout: 2500, // Some loading states take ~2s before more activity is observed
                beforeStartSpan: (context) => {
                    if (typeof context.name !== 'string') {
                        return context;
                    }
                    // Sentry auto-instrumentation passes only pathname as context.name (no query).
                    // Augment with window.location.search when missing so normalizeRoute can
                    // produce correct canonical routes (e.g. /?tab=cloud-documents&cloudid=... → /files/:assetId).
                    let route = context.name;
                    if (
                        typeof window !== 'undefined' &&
                        window.location?.search &&
                        !context.name.includes('?')
                    ) {
                        route = context.name + window.location.search;
                    }
                    const { normalized } = normalizeRoute(route);
                    return {
                        ...context,
                        name: normalized,
                        attributes: {
                            ...context.attributes,
                            'transaction.original': route,
                            'transaction.preload': route.includes('preload'),
                        },
                    };
                },
            }),
        );
    }

    if (profilingEnabled) {
        requiredIntegrations.push(browserProfilingIntegration());
    }

    if (process.env.NODE_ENV === 'development') {
        requiredIntegrations.push(
            captureConsoleIntegration({
                levels: ['error', 'warn'],
            }),
        );
    }

    const ignoreErrors = [
        /.*\w\.closest\(\/adobe-profile\..*/,
        /adobe-profile\.min.*\w\.closest is not a function/,
    ];

    const enabled = isSentryEnabled(sdkInterface);

    if (enabled) {
        // WORKAROUND: UXP has document.readyState as undefined, which breaks Sentry's web vitals code
        // Sentry checks "complete" !== document.readyState in onTTFB.ts, which is true when undefined
        // This causes infinite recursion in addEventListener("load")
        // Patch document.readyState to "complete" BEFORE any integrations load.
        if (typeof document !== 'undefined' && document.readyState === undefined) {
            Object.defineProperty(document, 'readyState', {
                value: 'complete',
                writable: false,
                configurable: true,
            });
            console?.log('[UAB Sentry] Patched document.readyState to "complete" (UXP workaround)');
        }

        const release = `universal-asset-browser@${process.env.VERSION}`;
        const hostDsn =
            typeof sentryConfig === 'object' && sentryConfig ? sentryConfig.dsn : undefined;

        const initDsn = hostDsn || AUP_SDK_DSN;
        const performanceConsent = isPerformanceAllowed();

        const hostOptions: BrowserOptions | undefined =
            typeof sentryConfig === 'object' && sentryConfig ? sentryConfig : undefined;
        const hostTracesSampler = hostOptions?.tracesSampler;
        const hostProvidesTracesSampleRate = hostOptions && 'tracesSampleRate' in hostOptions;
        const hostTracesSampleRateValue = hostOptions?.tracesSampleRate;

        const SAMPLING_RATES = {
            production: {
                canonical: 0.05, // 5%
                nonCanonical: 0.00001, // 0.001%
            },
            staging: {
                canonical: 0.05, // 5%
                nonCanonical: 0.00001, // 0.001%
            },
            preview: {
                canonical: 0.001, // 0.1%
                nonCanonical: 0.00001, // 0.001%
            },
            development: {
                canonical: 0.001, // 0.1%
                nonCanonical: 0.00001, // 0.001%
            },
        };

        const tracesSampler: BrowserOptions['tracesSampler'] = (
            samplingContext,
        ): number | boolean => {
            // Profiling override, always sample at 100%
            if (isProfilingEnabled()) {
                return 1.0;
            }

            // No consent, never sample
            if (!performanceConsent) {
                return 0.0;
            }

            // Custom route-based sampling (canonical vs non-canonical)
            if (environment in SAMPLING_RATES) {
                const rates = SAMPLING_RATES[environment];
                const transactionName = samplingContext.name;

                // Preload routes are background prefetches, not real navigations
                if (samplingContext.attributes?.['transaction.preload']) {
                    return rates.nonCanonical;
                }

                // Canonical routes always use the canonical rate, regardless of host config
                if (transactionName && isCanonicalRoute(transactionName)) {
                    return rates.canonical;
                }

                // For non-canonical routes, check host-provided sampling options
                if (hostTracesSampler) {
                    // Host sampler takes precedence for non-canonical routes
                    // Sentry handles boolean returns automatically (true = 1.0, false = 0.0)
                    return hostTracesSampler(samplingContext);
                }

                if (hostProvidesTracesSampleRate) {
                    // Host-provided static rate applies to non-canonical routes only
                    return hostTracesSampleRateValue ?? rates.nonCanonical ?? 0.0;
                }

                // For non-canonical routes, use inheritOrSampleWith to respect parent sampling decision
                return samplingContext.inheritOrSampleWith(rates.nonCanonical);
            }

            // Fallback when environment not in SAMPLING_RATES
            if (hostTracesSampler) {
                return hostTracesSampler(samplingContext);
            }

            if (hostProvidesTracesSampleRate) {
                return hostTracesSampleRateValue ?? 0.0;
            }

            return 0.0;
        };

        function mergeIntegrations(base: Integration[], extra: Integration[]): Integration[] {
            const names = new Set(
                base
                    .map((i) => (i as unknown as { name?: string }).name)
                    .filter(Boolean) as string[],
            );
            const additional = extra.filter(
                (i) => !names.has((i as unknown as { name?: string }).name || ''),
            );

            return [...base, ...additional];
        }

        const hostIntegrationsValue =
            typeof sentryConfig === 'object' && sentryConfig
                ? sentryConfig.integrations
                : undefined;

        const integrationsOption: BrowserOptions['integrations'] =
            typeof hostIntegrationsValue === 'function'
                ? (defaults) =>
                      mergeIntegrations(hostIntegrationsValue(defaults), requiredIntegrations)
                : Array.isArray(hostIntegrationsValue)
                  ? mergeIntegrations(hostIntegrationsValue, requiredIntegrations)
                  : requiredIntegrations;

        const defaultOptions: BrowserOptions = {
            dsn: initDsn,
            enabled,
            ignoreErrors,
            environment,
            release,
            profilesSampleRate: 1.0,
            tracePropagationTargets: [],
            integrations: integrationsOption as any,
            ignoreSpans: [
                { op: 'mark' },
                { op: 'measure', name: /^Zone/i },
                { op: 'resource.link' },
                { op: 'resource.beacon' },
                { op: 'resource.script', name: /Icon/i }, // Icons generate a lot of spans
                { op: 'resource.script', name: /\.map(\?|$)/i }, // Ignore source map fetches
                { op: 'resource.script', name: sharedComponentsPattern },
                { op: 'resource.css', name: sharedComponentsPattern },
                { op: 'resource.other', name: sharedComponentsPattern },
                { name: /\.adobe\.(?:io|com)\/ons/i },
                { name: /\.adobe\.(?:io|com)\/ingest/i },
                { name: /\.adobe\.(?:io|com)\/ans\/.*\/notifications/i },
                { name: /\.adobe\.(?:io|com)\/.*\/log/i },
                { name: /\.adobess\.com\/api\/.*\/notifications/i },
                { name: /\.adobedtm\.com/i },
                { name: /sstats\.adobe\.com\/ee\/.*\/.*\/collect/i },
                { name: /\.adobe\.com\/log/i },
                { name: /hz-telemetry(?:-[\w.-]+)?\.adobe\.(?:io|com)/i },
                { name: /idg\.adobe\.com\/v\d+\/api\/bfp_capture/i },
                { name: /\.nr-data\.net/i },
            ],
            transport: makeMultiplexedTransport(
                makeBrowserOfflineTransport(makeFetchTransport),
                ({ getEvent }) => {
                    const event = getEvent(['event', 'transaction']);

                    // Route exception events to all matching registered DSNs; if host DSN is configured,
                    // and there are NO matches, fall back to host DSN only
                    if (event?.type === undefined) {
                        const frames = event?.exception?.values?.[0]?.stacktrace?.frames || [];
                        const candidateUrls: string[] = frames
                            .map((f) => f.abs_path || f.filename || '')
                            .filter(Boolean);

                        const matches = dynamicDsnRoutes
                            .filter((route) =>
                                candidateUrls.some((u) => route.pattern.test(String(u))),
                            )
                            .map((route) => ({ dsn: route.dsn, release }));

                        if (matches.length > 0) {
                            // When matched, send ONLY to matching DSNs (no fallbacks)
                            return matches;
                        }

                        // Only fallback to host DSN if it exists and differs from AUP SDK DSN
                        // This prevents host application errors from going to AUP SDK DSN
                        if (hostDsn && hostDsn !== AUP_SDK_DSN) {
                            return [{ dsn: hostDsn, release }];
                        }

                        const config =
                            sdkOrConfig &&
                            ('getConfig' in sdkOrConfig ? sdkOrConfig.getConfig() : sdkOrConfig);

                        if (config?.logger) {
                            const ex = event?.exception?.values?.[0];
                            const msg =
                                event?.message ||
                                (ex?.type ? `${ex.type}: ${ex.value}` : 'Unrouted exception');

                            config.logger.error('[TelemetrySDK] Dropped unrouted exception', {
                                message: msg,
                                exception: event?.exception,
                                candidateUrls,
                                frames: frames.map((f) => ({
                                    filename: f.filename,
                                    abs_path: f.abs_path,
                                    in_app: f.in_app,
                                })),
                            });
                        }

                        // Return empty array to drop the event completely
                        return [];
                    }

                    // Performance transactions: always send to AUP SDK DSN; if initialized with
                    // a host-provided DSN, also multiplex to that host DSN.
                    const targets = [{ dsn: AUP_SDK_DSN, release }];

                    if (hostDsn && hostDsn !== AUP_SDK_DSN) {
                        targets.push({ dsn: hostDsn, release });
                    }

                    return targets;
                },
            ),
            /**
             * Pre-filter and normalize error events before they are sent.
             *
             * Behavior:
             * - Drops exceptions with no `in_app` frames unless a distinct host DSN is configured
             *   (in which case, allow host to handle it); this prevents host-origin errors from
             *   polluting the SDK project.
             * - Drops generic React prop-type warnings to reduce noise.
             * - Converts boolean tag values to strings as a workaround for Sentry tag typing.
             *
             * @param event Sentry event to process.
             * @returns The event to keep, or `null` to drop.
             */
            beforeSend(event, hint) {
                if (event.exception) {
                    const frames = event.exception.values?.[0]?.stacktrace?.frames || [];
                    const hasInApp = frames.some((frame) => frame.in_app);

                    if (!hasInApp && enabled) {
                        if (hostDsn && hostDsn !== AUP_SDK_DSN) {
                            return event;
                        }

                        return null;
                    }
                }

                const message = event.message?.toLowerCase();
                if (
                    event.level === 'warning' &&
                    !message?.includes('reactjs.org') &&
                    !message?.includes('fb.me') &&
                    !message?.includes('failed prop type')
                ) {
                    return null;
                }

                if (event.tags) {
                    convertBooleanTags(event.tags);
                }

                // Extract SAMError._additionalInfo (including reqId) and add to contexts
                const originalException = hint?.originalException;
                if (isSAMError(originalException)) {
                    const additionalInfo = (originalException as any)._additionalInfo;
                    if (additionalInfo) {
                        event.contexts = event.contexts || {};
                        event.contexts['SAMError'] = additionalInfo;
                    }
                    // Update exception type and value for proper Sentry grouping
                    if (event.exception?.values?.[0] && originalException.code !== undefined) {
                        // Use reverse mapping from numeric enum to get the key name
                        const errorCodeName = SAM.SAMErrorCode[originalException.code];
                        event.exception.values[0].type = `SAMError: [${originalException.code}]`;
                        const baseValue =
                            originalException.description || event.exception.values[0].value;
                        event.exception.values[0].value = errorCodeName
                            ? `[${errorCodeName}] ${baseValue}`
                            : baseValue;
                    }
                }

                return event;
            },
            /**
             * Pre-process performance transactions before they are sent.
             *
             * Behavior:
             * - Converts boolean tag values to strings for consistency with Sentry's tag typing.
             *
             * @param transaction Sentry transaction to process.
             * @returns The transaction to keep, or `null` to drop.
             */
            beforeSendTransaction(transaction) {
                if (transaction.tags) {
                    convertBooleanTags(transaction.tags);
                }

                // Force finalize if loading-total measure is missing (prevents race condition)
                // Sentry's idleTimeout (2500ms) can fire before LoadingInstrumentation's timeout (2000ms)
                // completes due to event loop delays
                if (loadingPerformanceInstrumentation) {
                    loadingPerformanceInstrumentation.finish();
                }

                return transaction;
            },
            /**
             * Mutate individual spans prior to send.
             *
             * Behavior:
             * - Copies scalar tags from the active scope into span `data` if missing.
             * - Coerces boolean values to capitalized string representations for consistency.
             *
             * @param span Span being processed.
             * @returns The span to keep.
             */
            beforeSendSpan(span) {
                const scope = getCurrentScope();
                if (scope) {
                    const scopeTags = scope.getScopeData().tags || {};
                    Object.keys(scopeTags).forEach((key) => {
                        const value = scopeTags[key];
                        if (
                            value !== null &&
                            value !== undefined &&
                            !span.data[key] &&
                            (typeof value === 'string' ||
                                typeof value === 'number' ||
                                typeof value === 'boolean')
                        ) {
                            span.data[key] =
                                typeof value === 'boolean' ? (value ? 'True' : 'False') : value;
                        }
                    });
                }
                return span;
            },
            /**
             * Normalize and enrich breadcrumbs before they are recorded.
             *
             * Behavior:
             * - For `ui.click`, rewrites message to include `data-testid` and inner text.
             * - For `xhr`/`fetch`, attaches `x-request-id` when available.
             *
             * @param breadcrumb The breadcrumb to process.
             * @param hint Optional hint carrying source-specific details.
             * @returns The breadcrumb to record.
             */
            beforeBreadcrumb(breadcrumb, hint) {
                try {
                    if (breadcrumb.category === 'ui.click') {
                        if (hint?.event?.target?.dataset) {
                            const { target } = hint.event;
                            const dataTestId = target.dataset.testId || target.dataset.testid;
                            const tagInnerText = getFilteredInnerText(target);
                            const defaultMessage = breadcrumb.message;
                            breadcrumb.message = '';

                            if (dataTestId) {
                                breadcrumb.message += `${dataTestId} `;
                            }
                            if (tagInnerText) {
                                breadcrumb.message += `>> ${tagInnerText} `;
                            }
                            breadcrumb.message += `[${defaultMessage}]`;
                        }
                    } else if (breadcrumb.category === 'xhr' || breadcrumb.category === 'fetch') {
                        if (hint) {
                            const xhr = hint.xhr;
                            const input = hint.input;
                            const setRequestId = (_requestId: string | null | undefined) => {
                                if (_requestId && breadcrumb.data) {
                                    breadcrumb.data['x-request-id'] = `${_requestId}`;
                                }
                            };

                            if (xhr?._cdtXHR) {
                                setRequestId(xhr._cdtXHR.headers['x-request-id']);
                            } else if (input?.length >= 2 && input[1]?.headers) {
                                const headers = input[1].headers;

                                if (headers instanceof Headers) {
                                    setRequestId(headers.get('X-Request-Id'));
                                } else if (typeof headers === 'object') {
                                    setRequestId(
                                        headers['X-Request-Id'] || headers['x-request-id'],
                                    );
                                }
                            }
                        }
                    }
                } catch (e) {
                    console.error(e);
                }

                return breadcrumb;
            },
        };

        const {
            tracesSampler: _,
            tracesSampleRate: __,
            ...hostOptionsWithoutSampling
        } = hostOptions || {};

        const initOptions: BrowserOptions = {
            ...defaultOptions,
            ...hostOptionsWithoutSampling,
            // Only set tracesSampler when performance consent is granted
            // When consent is denied, leave it undefined to allow Sentry's default behavior
            ...(performanceConsent ? { tracesSampler } : {}),
        };

        sentryClient = init(initOptions);

        const hasHistory = !!globalThis.history;
        const isInWebview = !!globalThis.uxpHost;
        const shouldSetBrowserContext = !hasHistory || isInWebview;

        if (shouldSetBrowserContext && initConfig) {
            if (initConfig.appName || initConfig.appVersion) {
                setContext('browser', {
                    name: initConfig.appName,
                    version: initConfig.appVersion,
                });
            }
        }

        // Add component loader versions as tags
        const componentVersions = (globalThis as unknown as ComponentLoaderGlobal)
            .__component_loader_versions__;
        if (componentVersions) {
            Object.entries(componentVersions).forEach(([component, data]) => {
                setTag(`version.${component}`, data.version);
            });
        }

        // Add component loader overrides as tags
        const loaderOverrides = (globalThis as unknown as ComponentLoaderGlobal)
            .__component_loader_override__;
        // @ts-expect-error - _overrides is internal
        const overrides = loaderOverrides?._overrides as ComponentOverridesMap | undefined;
        if (overrides) {
            Object.entries(overrides).forEach(([component, raw]) => {
                const normalized = parseOverride(raw);
                const overrideValue = normalized.url ?? normalized.version ?? 'unknown';
                setTag(`version_override.${component}`, overrideValue);
            });

            // Add feature flags as tags
            const flagsIntegration =
                getClient()?.getIntegrationByName<FeatureFlagsIntegration>('FeatureFlags');
            if (flagsIntegration && sdkOrConfig) {
                const config = isSDK(sdkOrConfig) ? sdkOrConfig.getConfig() : sdkOrConfig;

                if (config.featureFlags) {
                    Object.entries(config.featureFlags).forEach(([flag, value]) => {
                        flagsIntegration.addFeatureFlag(flag, value);
                        setTag(`feature_flag.${flag}`, value);
                    });
                }
            }
        }
    } else {
        // The problem: Sentry's global client survives our dispose() call and might still
        // capture events. The solution: Replace it with an explicitly disabled client.
        // This mainly happens in tests where we dispose() then re-init with sentry: false.
        // In production this is rare (who disables Sentry mid-session?), but it ensures
        // that Sentry.captureException() calls become true no-ops when disabled.
        init({ enabled: false });
        sentryClient = undefined;
    }

    // Initialize LoadingInstrumentation only when Sentry sampled the current trace
    // const { ['sentry-trace']: sentryTrace } = getTraceData?.() ?? {};
    // const sampled = typeof sentryTrace === 'string' && sentryTrace.split('-')[2] === '1';
    const sampled = true; // Hardcoded to true for now to test instrumentation
    if (sampled && !loadingPerformanceInstrumentation) {
        loadingPerformanceInstrumentation = new LoadingInstrumentation(sdkInterface);
    }

    const sentryInitState =
        getClient()?.getOptions()?.enabled ?? false ? 'initialized...' : 'not enabled';
    const loadingSampleState = sampled ? 'sampled' : 'not sampled';

    console.log(
        `[UAB v${process.env.VERSION}] sentry.io ${sentryInitState} (loading ${loadingSampleState})`,
    );

    // Attach test helpers to __SENTRY__ for CLI debugging (only in non-production)
    const isProduction = environment === 'production';
    if (!isProduction && typeof globalThis !== 'undefined' && (globalThis as any).__SENTRY__) {
        const sentryGlobal = (globalThis as any).__SENTRY__;

        if (!sentryGlobal.test) {
            sentryGlobal.test = {
                /**
                 * Console-only test helper: Creates and captures an exception with a stack trace
                 * that matches registered DSN patterns. Use from browser console for testing exception routing.
                 *
                 * @param patternOrError Either a pattern string to include in stack trace (e.g., '/asset-browser/', 'sam-js')
                 *                          or an existing Error object. If Error, its stack will be used as-is.
                 * @param message Optional error message (only used when patternOrError is a string, defaults to 'Test exception')
                 * @example
                 * ```js
                 * // In browser console:
                 * // After registering: telemetrySdk.registerDSN(/\/asset-browser\//i, 'https://...')
                 * __SENTRY__.test.captureException('/asset-browser/', 'Testing routing');
                 *
                 * // Or pass an existing error:
                 * const err = new Error('Something went wrong');
                 * __SENTRY__.test.captureException(err);
                 * ```
                 */
                captureException(
                    patternOrError: string | Error,
                    message: string = 'Test exception',
                ): void {
                    let error: Error;
                    if (patternOrError instanceof Error) {
                        // Use existing error as-is
                        error = patternOrError;
                    } else {
                        // Create error with pattern in stack trace
                        error = new Error(message);
                        const pattern = patternOrError;
                        // Create a stack trace that includes the pattern so it matches registered DSN routes
                        // Use a realistic-looking URL format that will match common patterns
                        const stackFrame = `    at testFunction (https://shared-components.stage.adobe.com${pattern}dist/test.js:100:15)`;
                        Object.defineProperty(error, 'stack', {
                            value: `Error: ${message}\n${stackFrame}`,
                            configurable: true,
                        });
                    }
                    captureException(error);
                },
                /**
                 * Console-only test helper: Starts a UI transaction. Use from browser console
                 * for testing performance tracking.
                 *
                 * @param route Route name for the transaction (e.g., '/files', '/projects')
                 * @example
                 * ```js
                 * // In browser console:
                 * __SENTRY__.test.startUITransaction('/files');
                 * ```
                 */
                startUITransaction(route: string): void {
                    telemetrySdk.startUITransaction(route);
                },
            };
        }
    }

    return telemetrySdk;
}
