import React from 'react';
import type { ComponentProps } from 'react';
import type {
    Color,
    Scale,
    SystemVariant,
} from '@ccx-public/spectrum-web-component-fallbacks/dist/theme';
import type Provider from '../Provider';

export type ProviderPreloadProps = Pick<
    ComponentProps<typeof Provider>,
    'scale' | 'spectrumTheme' | 'theme' | 'typekitId'
>;

export type ProviderConfig = {
    scale: Scale;
    spectrumTheme: SystemVariant;
    theme: Color;
    typekitId: string;
};

export const getProviderConfig = ({
    scale,
    spectrumTheme,
    theme,
    typekitId,
}: ProviderPreloadProps = {}): ProviderConfig => ({
    scale: scale || 'medium',
    spectrumTheme: spectrumTheme || 'spectrum',
    theme: theme || 'light',
    typekitId: typekitId || 'ruf7eed',
});

export const ThemeContext = React.createContext<ProviderConfig>(
    getProviderConfig()
);
