import React, { forwardRef } from 'react';
import type { ReactProps, SpectrumElementProps } from '.';
import { loadSwcIfNeeded, useSWCLoader } from '.';
import type { SWCLoader } from './SWCLoader';
import { _register } from '../preload';
import type { ProviderConfig } from './ThemeContext';

interface BaseOptions<SWCProps, RS2CompatProps> {
    displayName: string;
    fallback:
        | React.ComponentType<
              Omit<
                  ReactProps<SWCProps, RS2CompatProps>,
                  'fallback' | 'forceFallback'
              >
          >
        | undefined;
    swcLoader: SWCLoader | undefined;
    tagName: string;
    loadSwc?: () => Promise<void>;
}

interface SWCPropsOptions<SWCProps, RS2CompatProps>
    extends BaseOptions<SWCProps, RS2CompatProps> {
    swcProps: (
        props: ReactProps<SWCProps, RS2CompatProps>
    ) => SpectrumElementProps<SWCProps>;
    SWCWrapper?: never;
}

interface SWCWrapperOptions<SWCProps, RS2CompatProps>
    extends BaseOptions<SWCProps, RS2CompatProps> {
    swcProps?: never;
    SWCWrapper: React.ComponentType<ReactProps<SWCProps, RS2CompatProps>>;
}

type Options<SWCProps, RS2CompatProps> =
    | SWCPropsOptions<SWCProps, RS2CompatProps>
    | SWCWrapperOptions<SWCProps, RS2CompatProps>;

export default function createWrapper<SWCProps, RS2CompatProps = object>(
    options: Options<SWCProps, RS2CompatProps>
) {
    // Register for preload
    const loadSwc = (providerConfig: ProviderConfig) =>
        loadSwcIfNeeded(options.tagName, providerConfig, options.swcLoader);

    _register(options.loadSwc || loadSwc);

    const Component: React.ForwardRefRenderFunction<
        unknown,
        ReactProps<SWCProps, RS2CompatProps>
    > = (props, ref) => {
        const { needsFallback, tagName } = useSWCLoader(
            options.tagName,
            options.swcLoader
        );

        const { fallback, forceFallback, ...rest } = props;

        if (needsFallback || forceFallback) {
            const { fallback: FallbackComponent } = options;

            if (fallback) {
                return <>{fallback}</>;
            }

            if (FallbackComponent) {
                return <FallbackComponent {...rest} ref={ref} />;
            }
        }

        if (options.SWCWrapper) {
            return <options.SWCWrapper {...props} ref={ref} />;
        }

        const compatibilityProps = { ...options.swcProps(props), ref };
        const SpComponent = tagName;

        return (
            <SpComponent {...(compatibilityProps as JSX.IntrinsicAttributes)} />
        );
    };
    Component.displayName = options.displayName;
    return forwardRef(Component);
}
