import { AssetBrowser } from "@ccx-public/component-types";
const LOG_LEVEL = new Map([
    [
        'default',
        AssetBrowser.CDOLogLevel.INFO
    ]
]);
const LAST_ID = new Map();
const LOG_METHOD = {
    [AssetBrowser.CDOLogLevel.DEBUG]: 'debug',
    [AssetBrowser.CDOLogLevel.INFO]: 'log',
    [AssetBrowser.CDOLogLevel.WARN]: 'warn',
    [AssetBrowser.CDOLogLevel.ERROR]: 'error'
};
let LOG_LEVEL_ENV = LOG_LEVEL;
if ('test' === process.env.NODE_ENV) LOG_LEVEL_ENV = new Map([
    [
        'default',
        AssetBrowser.CDOLogLevel.DISABLED
    ]
]);
class Logger {
    static setLogLevel(logLevel, className = 'default') {
        LOG_LEVEL_ENV.set(className, logLevel);
    }
    constructor(className){
        this.className = className;
        this.instanceId = (LAST_ID.get(className) || 0) + 1;
        LAST_ID.set(className, this.instanceId);
    }
    out(logLevel, msg, ...args) {
        const currentLevel = LOG_LEVEL_ENV.has(this.className) ? LOG_LEVEL_ENV.get(this.className) : LOG_LEVEL_ENV.get('default');
        if (currentLevel <= logLevel) console[LOG_METHOD[logLevel]](`[${this.className}-${this.instanceId}] ${msg}`, ...args);
    }
    debug(msg, ...args) {
        this.out(AssetBrowser.CDOLogLevel.DEBUG, msg, ...args);
    }
    log(msg, ...args) {
        this.out(AssetBrowser.CDOLogLevel.INFO, msg, ...args);
    }
    warn(msg, ...args) {
        this.out(AssetBrowser.CDOLogLevel.WARN, msg, ...args);
    }
    error(msg, ...args) {
        this.out(AssetBrowser.CDOLogLevel.ERROR, msg, ...args);
    }
}
let internalForTests;
if ('test' === process.env.NODE_ENV) internalForTests = {
    LOG_LEVEL,
    LOG_LEVEL_ENV
};
const LogLevel = AssetBrowser.CDOLogLevel;
export { LogLevel, Logger, internalForTests };
