import type { ReactNode } from 'react';
import { useContext, useEffect, useMemo, useRef, useState } from 'react';
import semverSatisfies from 'semver/functions/satisfies';
import { fallbackTagName } from '@ccx-public/spectrum-web-component-fallbacks/fallbackTagName';
import type { SWCLoader } from './SWCLoader';
import type { ProviderConfig } from './ThemeContext';
import { ThemeContext } from './ThemeContext';
import useForceReactSpectrum from './useForceReactSpectrum';

const CAN_USE_SWC = !process.env.EXCLUDE_SWC && !window.__disable_swc__;

let isUxpEnv = false;
try {
    isUxpEnv = !!window.require('uxp');
} catch (e) {} // eslint-disable-line no-empty

export const isUXP = isUxpEnv;

// Use this to type the props of your wrapper so that they extends the web component you're wrapping.
// This will help with any special cases with mismatching prop signatures where a spectrum web component accepts/requires props
// that the React Spectrum component doesn't.

type Children = { children?: ReactNode };
type HTMLClass = { class?: string };
type ReactClass = { className?: string };
type ReactStyles = { style?: React.CSSProperties };
type FallbackProps = { fallback?: ReactNode; forceFallback?: boolean };
type ReactRef = { ref?: React.Ref<HTMLElement> };
type ModalOverlayProps = { modalTrigger?: boolean; modalContent?: boolean };

// Utility for fixing the types coming from spectrum-web-components so that they
// can be used in React.
//
// 1. The type expected for children is `HTMLCollection` and should be `ReactNode`.
// 2. There is a `className` prop expected for some reason. We want to ignore that.
// 3. We do want to provide a `class` property since that is what the web component expects.
export type SpectrumElementProps<T> = Partial<
    Omit<T, 'children' | 'class' | 'style'> &
        HTMLClass &
        Children &
        ReactStyles &
        ReactRef
>;

// Utility for converting spectrum web component types to React prop-types and
// providing overrides.
//
// Things done here:
// 1. Remove `class` and replace with `className`
// 2. Fix type of `children`
// 3. Allow passing a `fallback` prop for all components
// 4. Override default props. We use `Omit` for this because if you use & it
//    just makes an intersection of all properties, for example `{ a: string } & {
//    a: number } //=> { a: string & number }`, which results in `never`. We avoid
//    this by omitting the overridden props before using `&`.
export type ReactProps<T, Overrides = object> = Partial<
    Omit<SpectrumElementProps<T>, keyof Overrides | 'class'>
> &
    ReactClass &
    FallbackProps &
    ModalOverlayProps &
    Overrides;

type SWCConstructor = CustomElementConstructor & { VERSION?: string };

// UXP does not currently support Spectrum Web Components, but it does support "Spectrum UXP",
// which are supposed to share the same signature as SPW (i.e <sp-button> is used isomorphically on both).
// This does mean that checking the custom element registry (i.e window.customElements.get())
// won't work in UXP as a way to check that the target web component is available.
// As a workaround, in UXP we'll have to create the target element and check the return type
// to determine the element availability. We'll cache the result so that we
// only need to do this once per custom-element.
export const customElementRegistryCache = new Map<
    string,
    SWCConstructor | undefined
>();

function getCustomElementClass(tagName: string): SWCConstructor {
    const cached = customElementRegistryCache.get(tagName);
    if (cached !== undefined) {
        return cached;
    }

    let registered = window.customElements?.get(tagName) as SWCConstructor;
    if (!registered && isUXP && CAN_USE_SWC) {
        // UXP fallback.
        registered = document.createElement(tagName)
            ?.constructor as SWCConstructor;
    }

    customElementRegistryCache.set(tagName, registered);
    return registered;
}

export function isRegisteredCustomElement(tagName: string) {
    const constructor = getCustomElementClass(tagName);
    return !!constructor && constructor !== HTMLElement;
}

const SWC_COMPATIBLE_VERSION = '^1.9.1';

export function doesSWCNeedLoaded(tagName: string) {
    if (!CAN_USE_SWC) {
        return false;
    }

    if (!isRegisteredCustomElement(tagName)) {
        return true;
    }

    const element = getCustomElementClass(tagName);

    if (!element || !element.VERSION) {
        return true;
    }

    return !semverSatisfies(element.VERSION, SWC_COMPATIBLE_VERSION);
}

export const loadSwcIfNeeded = (
    tagName: string,
    providerConfig: ProviderConfig,
    loader?: SWCLoader
) => {
    if (doesSWCNeedLoaded(tagName)) {
        return loader?.load(providerConfig) || Promise.resolve();
    } else {
        return Promise.resolve();
    }
};

function useIsUsingImportedSWC(tagName: string): boolean {
    return useMemo(() => doesSWCNeedLoaded(tagName), [tagName]);
}

export function useComponent<T extends string>(tagName: T): T {
    return useIsUsingImportedSWC(tagName)
        ? (fallbackTagName(tagName) as T)
        : tagName;
}

export function useSWCLoader<T extends string>(
    tagName: T,
    loader?: SWCLoader
): { needsFallback: boolean; tagName: T } {
    const shouldLoadSWC = useIsUsingImportedSWC(tagName);
    const fallbackLoaded = useMemo(
        () => isRegisteredCustomElement(fallbackTagName(tagName)),
        [tagName]
    );

    const [, isLoaded] = useState(false);
    const unmountedRef = useRef(true);
    const theme = useContext(ThemeContext);

    useEffect(() => {
        unmountedRef.current = false;

        if (shouldLoadSWC && !fallbackLoaded) {
            // We need to load the SWC element. Note that it's ok if another component calls
            // loader.load at the same time - it'll only import and register the component once.
            loader?.load(theme).then(
                () => {
                    if (!unmountedRef.current) {
                        isLoaded(true);
                    }
                },
                (e) => console.error(`Error loading fallback for ${tagName}`, e)
            );
            return () => {
                unmountedRef.current = true;
            };
        }
    }, [theme, tagName, loader, shouldLoadSWC, fallbackLoaded]);

    const forceReactSpectrum = useForceReactSpectrum();
    const registeredTagName = useComponent(tagName);

    return {
        needsFallback:
            !isRegisteredCustomElement(registeredTagName) ||
            !!forceReactSpectrum,
        tagName: registeredTagName,
    };
}

export function filterBooleanProps<T extends object>(obj: T) {
    const result: { [K in keyof T]?: T[K] } = {};
    (Object.keys(obj) as Array<keyof T>).forEach((name) => {
        if (obj[name]) {
            result[name] = obj[name];
        }
    });
    return result;
}

export function chain(...callbacks: unknown[]) {
    return (...args: unknown[]) => {
        for (const callback of callbacks) {
            if (typeof callback === 'function') {
                callback(...args);
            }
        }
    };
}

export function configureTypekit(typeKitId: string) {
    return new Promise((resolve) => {
        if (!window.Typekit) {
            const config = {
                kitId: typeKitId,
                scriptTimeout: 3000,
            };
            const t = setTimeout(() => {
                resolve(null);
            }, config.scriptTimeout);

            const tk = document.createElement('script');
            let d = false;

            tk.src = `https://use.typekit.net/${config.kitId}.js`;
            tk.type = 'text/javascript';
            tk.async = true;
            tk.onload = function onload() {
                if (d) {
                    resolve(null);
                    return;
                }
                d = true;
                clearTimeout(t);
                try {
                    // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call
                    window.Typekit.load(config);
                } catch (b) {
                    /* empty */
                }
                resolve(null);
            };

            const s = document.getElementsByTagName('script')[0];
            s?.parentNode?.insertBefore(tk, s);
        } else {
            resolve(null);
        }
    });
}
