import React, { ComponentProps, useEffect, useMemo } from 'react'; // eslint-disable-line @typescript-eslint/consistent-type-imports
import type { Theme as ThemeType } from '@ccx-public/spectrum-web-component-fallbacks/dist/theme';
import createWrapper from './utils/createWrapper';
import { SWCLoader } from './utils/SWCLoader';
import type { SpectrumElementProps } from './utils';
import {
    configureTypekit,
    doesSWCNeedLoaded,
    loadSwcIfNeeded,
    useComponent,
} from './utils';
import interopRequireDefault from './utils/interopRequireDefault';
import { getProviderConfig, ThemeContext } from './utils/ThemeContext';
import { _register } from './preload';

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2Provider: React.ComponentType<unknown> = process.env.INCLUDE_RS2
    ? interopRequireDefault(require('react-spectrum/Provider')).default
    : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

const TAG_NAME = 'sp-theme';
let swcLoader: SWCLoader | undefined;
if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader([TAG_NAME], async () => {
        const { Theme } = await import(
            /* webpackChunkName: "SpTheme" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/theme'
        );
        return [Theme];
    });
}

let darkSpectrumThemeLoader = () => Promise.resolve() as Promise<unknown>;
let darkestSpectrumThemeLoader = () => Promise.resolve() as Promise<unknown>;
let lightSpectrumThemeLoader = () => Promise.resolve() as Promise<unknown>;
let lightestSpectrumThemeLoader = () => Promise.resolve() as Promise<unknown>;
let darkSpectrumTwoThemeLoader = () => Promise.resolve() as Promise<unknown>;
let darkestSpectrumTwoThemeLoader = () => Promise.resolve() as Promise<unknown>;
let lightSpectrumTwoThemeLoader = () => Promise.resolve() as Promise<unknown>;
let lightestSpectrumTwoThemeLoader = () =>
    Promise.resolve() as Promise<unknown>;
let darkExpressThemeLoader = () => Promise.resolve() as Promise<unknown>;
let darkestExpressThemeLoader = () => Promise.resolve() as Promise<unknown>;
let lightExpressThemeLoader = () => Promise.resolve() as Promise<unknown>;
let lightestExpressThemeLoader = () => Promise.resolve() as Promise<unknown>;
let largeSpectrumScaleLoader = () => Promise.resolve() as Promise<unknown>;
let mediumSpectrumScaleLoader = () => Promise.resolve() as Promise<unknown>;
let largeExpressScaleLoader = () => Promise.resolve() as Promise<unknown>;
let mediumExpressScaleLoader = () => Promise.resolve() as Promise<unknown>;
let largeSpectrumTwoScaleLoader = () => Promise.resolve() as Promise<unknown>;
let mediumSpectrumTwoScaleLoader = () => Promise.resolve() as Promise<unknown>;

// Theme loaders
if (!process.env.EXCLUDE_SWC) {
    darkSpectrumThemeLoader = async () => {
        return await import(
            /* webpackChunkName: "SWCDarkTheme" */ '@ccx-public/spectrum-web-component-fallbacks/dist/theme/theme-dark.js'
        );
    };
    darkestSpectrumThemeLoader = async () => {
        return await import(
            /* webpackChunkName: "SWCDarkestTheme" */ '@ccx-public/spectrum-web-component-fallbacks/dist/theme/theme-darkest.js'
        );
    };
    lightSpectrumThemeLoader = async () => {
        return await import(
            /* webpackChunkName: "SWCLightTheme" */ '@ccx-public/spectrum-web-component-fallbacks/dist/theme/theme-light.js'
        );
    };
    lightestSpectrumThemeLoader = async () => {
        return await import(
            /* webpackChunkName: "SWCLightestTheme" */ '@ccx-public/spectrum-web-component-fallbacks/dist/theme/theme-lightest.js'
        );
    };
    darkExpressThemeLoader = async () => {
        return await import(
            /* webpackChunkName: "SWCExpressDarkTheme" */ '@ccx-public/spectrum-web-component-fallbacks/dist/theme/express/theme-dark.js'
        );
    };
    darkestExpressThemeLoader = async () => {
        return await import(
            /* webpackChunkName: "SWCExpressDarkestTheme" */ '@ccx-public/spectrum-web-component-fallbacks/dist/theme/express/theme-darkest.js'
        );
    };
    lightExpressThemeLoader = async () => {
        return await import(
            /* webpackChunkName: "SWCExpressLightTheme" */ '@ccx-public/spectrum-web-component-fallbacks/dist/theme/express/theme-light.js'
        );
    };
    lightestExpressThemeLoader = async () => {
        return await import(
            /* webpackChunkName: "SWCExpressLightestTheme" */ '@ccx-public/spectrum-web-component-fallbacks/dist/theme/express/theme-lightest.js'
        );
    };
    darkSpectrumTwoThemeLoader = async () => {
        return await import(
            /* webpackChunkName: "SWCS2DarkTheme" */ '@ccx-public/spectrum-web-component-fallbacks/dist/theme/spectrum-two/theme-dark.js'
        );
    };
    darkestSpectrumTwoThemeLoader = async () => {
        return await import(
            /* webpackChunkName: "SWCS2DarkestTheme" */ '@ccx-public/spectrum-web-component-fallbacks/dist/theme/spectrum-two/theme-darkest.js'
        );
    };
    lightSpectrumTwoThemeLoader = async () => {
        return await import(
            /* webpackChunkName: "SWCS2LightTheme" */ '@ccx-public/spectrum-web-component-fallbacks/dist/theme/spectrum-two/theme-light.js'
        );
    };
    lightestSpectrumTwoThemeLoader = async () => {
        return await import(
            /* webpackChunkName: "SWCS2LightestTheme" */ '@ccx-public/spectrum-web-component-fallbacks/dist/theme/spectrum-two/theme-lightest.js'
        );
    };

    // Scale Loaders
    largeSpectrumScaleLoader = async () => {
        return await import(
            /* webpackChunkName: "SWCLargeScale" */ '@ccx-public/spectrum-web-component-fallbacks/dist/theme/scale-large.js'
        );
    };
    mediumSpectrumScaleLoader = async () => {
        return await import(
            /* webpackChunkName: "SWCMediumScale" */ '@ccx-public/spectrum-web-component-fallbacks/dist/theme/scale-medium.js'
        );
    };
    largeExpressScaleLoader = async () => {
        return await import(
            /* webpackChunkName: "SWCExpressLargeScale" */ '@ccx-public/spectrum-web-component-fallbacks/dist/theme/express/scale-large.js'
        );
    };
    mediumExpressScaleLoader = async () => {
        return await import(
            /* webpackChunkName: "SWCExpressMediumScale" */ '@ccx-public/spectrum-web-component-fallbacks/dist/theme/express/scale-medium.js'
        );
    };
    largeSpectrumTwoScaleLoader = async () => {
        return await import(
            /* webpackChunkName: "SWCS2LargeScale" */ '@ccx-public/spectrum-web-component-fallbacks/dist/theme/spectrum-two/scale-large.js'
        );
    };
    mediumSpectrumTwoScaleLoader = async () => {
        return await import(
            /* webpackChunkName: "SWCS2MediumScale" */ '@ccx-public/spectrum-web-component-fallbacks/dist/theme/spectrum-two/scale-medium.js'
        );
    };
}

async function loadScale(
    options: Pick<SpectrumElementProps<ThemeType>, 'scale' | 'system'>
): Promise<unknown> {
    switch (options.system) {
        case 'express':
            if (options.scale === 'large') {
                return largeExpressScaleLoader();
            } else {
                return mediumExpressScaleLoader();
            }
        case 'spectrum-two':
            if (options.scale === 'large') {
                return largeSpectrumTwoScaleLoader();
            } else {
                return mediumSpectrumTwoScaleLoader();
            }
        case 'spectrum':
        default:
            if (options.scale === 'large') {
                return largeSpectrumScaleLoader();
            } else {
                return mediumSpectrumScaleLoader();
            }
    }
}

async function loadColor(
    options: Pick<SpectrumElementProps<ThemeType>, 'color' | 'system'>
): Promise<unknown> {
    switch (options.color) {
        case 'dark':
            if (options.system === 'express') {
                return darkExpressThemeLoader();
            } else if (options.system === 'spectrum-two') {
                return darkSpectrumTwoThemeLoader();
            } else {
                return darkSpectrumThemeLoader();
            }
        case 'darkest':
            if (options.system === 'express') {
                return darkestExpressThemeLoader();
            } else if (options.system === 'spectrum-two') {
                return darkestSpectrumTwoThemeLoader();
            } else {
                return darkestSpectrumThemeLoader();
            }
        case 'light':
            if (options.system === 'express') {
                return lightExpressThemeLoader();
            } else if (options.system === 'spectrum-two') {
                return lightSpectrumTwoThemeLoader();
            } else {
                return lightSpectrumThemeLoader();
            }
        case 'lightest':
        default:
            if (options.system === 'express') {
                return lightestExpressThemeLoader();
            } else if (options.system === 'spectrum-two') {
                return lightestSpectrumTwoThemeLoader();
            } else {
                return lightestSpectrumThemeLoader();
            }
    }
}

type Overrides = {
    locale?: ThemeType['lang'];
    scale?: ThemeType['scale'];
    spectrumTheme?: ThemeType['system'];
    theme?: ThemeType['color'];
    // RS2-only props
    typekitId?: string;
    // UXP-RS2-only props
    disableNativeControls?: boolean;
    useHostThemes?: boolean;
};

_register(function (config) {
    const { scale, spectrumTheme, theme, typekitId } = config;
    const promises = [
        loadScale({ scale, system: spectrumTheme }),
        loadColor({ color: theme, system: spectrumTheme }),
        configureTypekit(typekitId),
    ];

    if (doesSWCNeedLoaded(TAG_NAME)) {
        promises.push(loadSwcIfNeeded(TAG_NAME, config, swcLoader));
    }

    return Promise.all(promises);
});

const Provider = createWrapper<ThemeType, Overrides>({
    displayName: 'Provider',
    fallback: RS2Provider,
    swcLoader,
    SWCWrapper: function SpProvider(props) {
        const {
            className,
            locale,
            scale,
            spectrumTheme,
            theme,
            typekitId = 'ruf7eed',
            ...rest
        } = props;

        useEffect(() => {
            loadScale({ scale, system: spectrumTheme }).catch(console.error);
        }, [scale, spectrumTheme]);

        useEffect(() => {
            loadColor({ color: theme, system: spectrumTheme }).catch(
                console.error
            );
        }, [spectrumTheme, theme]);

        useEffect(() => {
            configureTypekit(typekitId).catch(console.error);
        }, [typekitId]);

        const Provider = useComponent(TAG_NAME);

        return (
            <Provider
                {...rest}
                class={className}
                color={theme}
                lang={locale}
                scale={scale}
                system={spectrumTheme}
            />
        );
    },
    tagName: TAG_NAME,
});

export default function ProviderWrapper(
    props: ComponentProps<typeof Provider>
) {
    const { scale, spectrumTheme, theme, typekitId } = props;

    const config = useMemo(
        () => getProviderConfig({ scale, spectrumTheme, theme, typekitId }),
        [scale, spectrumTheme, theme, typekitId]
    );

    return (
        <ThemeContext.Provider value={config}>
            <Provider {...props} />
        </ThemeContext.Provider>
    );
}
