import React from 'react';

// https://opensource.adobe.com/spectrum-web-components/components/asset/
// https://git.corp.adobe.com/torq/react-spectrum/tree/develop/src/Asset
import type { Asset as AssetType } from '@ccx-public/spectrum-web-component-fallbacks/dist/asset';
import createWrapper from './utils/createWrapper';
import { SWCLoader } from './utils/SWCLoader';
import interopRequireDefault from './utils/interopRequireDefault';

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2Asset: React.ComponentType<unknown> = process.env.INCLUDE_RS2
    ? interopRequireDefault(require('react-spectrum/Asset')).Asset
    : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

let swcLoader;
if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(['sp-asset'], async () => {
        const { Asset } = await import(
            /* webpackChunkName: "SpAsset" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/asset'
        );
        return [Asset];
    });
}

type RS2AssetCompatProps = {
    type?: 'file' | 'folder' | 'image';
    alt?: string;
    src?: string;
    decorative?: boolean;
};

export const Asset = createWrapper<AssetType, RS2AssetCompatProps>({
    displayName: 'Asset',
    fallback: RS2Asset,
    swcLoader,
    swcProps: function (props) {
        const { className, type, alt, src, decorative, ...rest } = props;

        // ReactSpectrum2           | SpectrumWebComponent
        // ---------------------------------------------
        // type:file                | type:file
        // type:folder              | type:folder
        // type:undefined           | type:image
        // alt                      | label

        const variantSWC = type === 'image' ? undefined : type;
        const altSWC = decorative ? '' : alt;
        const typeImageSWC =
            type === 'image' ? <img src={src} alt={altSWC} /> : <></>;
        const labelSWC = type !== 'image' ? alt : undefined;
        return {
            children: typeImageSWC,
            class: className,
            label: labelSWC,
            variant: variantSWC,
            ...rest,
        };
    },
    tagName: 'sp-asset',
});
