import { useMemo } from "react";
import { useIntl } from "react-intl";
import { getTypeViewModel, getViewAttributesMap } from "../components/TypeDropdownFilter/utils.mjs";
import { getCompatibleTypesFileType, getFileTypeForMimeType, isValidCompatibleTypes } from "../utils/filtering-utils/compatibility-filter.mjs";
import is_normal_folder from "../utils/is-normal-folder.mjs";
import { AssetBrowser } from "@ccx-public/component-types";
import { FIREFLY_GENERATIONS_MIMETYPES, OTHER_MIMETYPES } from "../utils/filtering-utils/filtering-type-enums.mjs";
function useCompatibleTypesFilter({ compatibleTypes, includeFolders, filterType, allowedFilterTypes }) {
    const intl = useIntl();
    return useMemo(()=>createCompatibleTypesFilterViewModel({
            intl,
            compatibleTypes,
            includeFolders,
            filterType,
            allowedFilterTypes
        }), [
        intl,
        compatibleTypes,
        includeFolders,
        filterType,
        allowedFilterTypes
    ]);
}
function createCompatibleTypesFilterViewModel({ intl, compatibleTypes, includeFolders, filterType, allowedFilterTypes }) {
    if (!isValidCompatibleTypes(compatibleTypes)) return;
    if ('type-dropdown' === filterType) {
        const filters = createCompatibleTypesFilters(intl, compatibleTypes, includeFolders, allowedFilterTypes);
        return filters.length > 0 ? filters : void 0;
    }
    const compatibleTypesToggle = createCompatibleTypesToggle(intl, compatibleTypes, includeFolders);
    if (compatibleTypesToggle) {
        const allTypes = getTypeViewModel(intl, AssetBrowser.OtherFileTypeValues.AllFiles);
        return [
            compatibleTypesToggle,
            allTypes
        ];
    }
}
function createCompatibleTypesToggle(intl, compatibleTypes, includeFolders) {
    const fileType = getCompatibleTypesFileType(compatibleTypes);
    if (!fileType) return;
    const { label, icon, group } = getViewAttributesMap(intl, fileType);
    const compatibleTypesSet = new Set(compatibleTypes);
    const filter = (asset)=>{
        if (includeFolders && is_normal_folder(asset)) return true;
        return compatibleTypesSet.has(asset.mediaType);
    };
    const mediaTypes = [
        ...compatibleTypesSet,
        ...includeFolders ? OTHER_MIMETYPES[AssetBrowser.OtherFileTypeValues.Folder] : []
    ];
    return {
        label,
        icon,
        group,
        value: fileType,
        filter,
        mediaTypes
    };
}
function createCompatibleTypesFilters(intl, compatibleTypes, includeFolders, allowedFileTypes) {
    if (!isValidCompatibleTypes(compatibleTypes)) return [];
    const compatibleTypesSet = new Set(compatibleTypes);
    const fileTypeGroups = new Map();
    for (const mimeType of compatibleTypes){
        const fileType = getFileTypeForMimeType(mimeType, allowedFileTypes);
        if (!fileType) continue;
        const isFireflyGeneration = FIREFLY_GENERATIONS_MIMETYPES[AssetBrowser.FireflyGenerationTypeValues.GenerationAll]?.includes(mimeType);
        const fireflyAllowed = !allowedFileTypes || allowedFileTypes.includes(AssetBrowser.AdobeFileTypeValues.Firefly);
        if (isFireflyGeneration && fireflyAllowed) {
            let fireflyGroup = fileTypeGroups.get(AssetBrowser.AdobeFileTypeValues.Firefly);
            if (!fireflyGroup) {
                fireflyGroup = new Set();
                fileTypeGroups.set(AssetBrowser.AdobeFileTypeValues.Firefly, fireflyGroup);
            }
            fireflyGroup.add(mimeType);
        }
        let mimeTypesForFileType = fileTypeGroups.get(fileType);
        if (!mimeTypesForFileType) {
            mimeTypesForFileType = new Set();
            fileTypeGroups.set(fileType, mimeTypesForFileType);
        }
        mimeTypesForFileType.add(mimeType);
    }
    const filterViewModels = [];
    for (const [fileType, mimeTypesInGroup] of fileTypeGroups){
        if (mimeTypesInGroup.size === compatibleTypes.length) continue;
        const { label, icon, group } = getViewAttributesMap(intl, fileType);
        const filter = (asset)=>{
            if (includeFolders && is_normal_folder(asset)) return true;
            return mimeTypesInGroup.has(asset.mediaType);
        };
        const mediaTypes = [
            ...mimeTypesInGroup,
            ...includeFolders ? OTHER_MIMETYPES[AssetBrowser.OtherFileTypeValues.Folder] : []
        ];
        filterViewModels.push({
            label,
            icon,
            group,
            value: fileType,
            filter,
            mediaTypes
        });
    }
    const allCompatibleAttributes = getViewAttributesMap(intl, AssetBrowser.OtherFileTypeValues.AllCompatible);
    const allCompatibleViewModel = {
        label: allCompatibleAttributes.label,
        icon: allCompatibleAttributes.icon,
        group: allCompatibleAttributes.group,
        value: AssetBrowser.OtherFileTypeValues.AllCompatible,
        filter: (asset)=>{
            if (includeFolders && is_normal_folder(asset)) return true;
            return compatibleTypesSet.has(asset.mediaType);
        },
        mediaTypes: [
            ...compatibleTypesSet,
            ...includeFolders ? OTHER_MIMETYPES[AssetBrowser.OtherFileTypeValues.Folder] : []
        ]
    };
    filterViewModels.unshift(allCompatibleViewModel);
    return filterViewModels;
}
export { createCompatibleTypesFilterViewModel, useCompatibleTypesFilter };
