import type { Config, IAUPSDK } from '@ccx-public/component-types';
import type { Client, Event, EventHint, Integration } from '@sentry/core';
import { getCurrentScope } from '@sentry/react';
import {
    Consent,
    Environment,
    SourceCategory,
    SourceType,
    Status,
    TriBool,
    ingest,
    online,
    setIngestConfig,
} from '@dunamis/dunamis-sdk';
import type { OnStatus } from '@dunamis/dunamis-sdk';
import { v4 as uuidv4 } from 'uuid';

// Extract IngestInstance type from the public API
type IngestInstance = NonNullable<ReturnType<typeof ingest.start>['instance']>;

/**
 * Sentry Integration that forwards telemetry events to Dunamis via the Dunamis SDK.
 *
 * This integration hooks into Sentry's event processing pipeline and sends
 * a copy of each event to Dunamis using the @dunamis/dunamis-sdk with its own
 * apiKey and project configuration. Events are forwarded immediately as the SDK handles batching.
 */
export class DunamisIntegration implements Integration {
    // Integration identifier for Sentry
    public name = 'DunamisIntegration';

    // SDK instance for accessing config
    private sdk: IAUPSDK;

    // Logger instance from SDK config
    private logger: Config['logger'];

    // Dunamis ingest instance
    private ingestInstance: IngestInstance | undefined;

    // Configuration guid for this integration
    private configGuid: string;

    // Dunamis environment (PROD or STAGE)
    private dunamisEnvironment: Environment.PROD | Environment.STAGE | undefined;

    /**
     * Initialize the Dunamis Integration with SDK instance and optional Ingest configuration.
     *
     * @param sdk SDK instance for accessing config
     * @param options Optional configuration for Ingest
     * @param options.project Project name for Dunamis
     * @param options.environment Sentry environment ('production' | 'staging' | 'preview' | 'development')
     * @param options.abortSignal AbortSignal for cleanup lifecycle management
     */
    constructor(
        sdk: IAUPSDK,
        options?: { project?: string; environment?: string; abortSignal?: AbortSignal },
    ) {
        this.sdk = sdk;

        // Get logger from SDK config
        const config = this.sdk.getConfig();
        this.logger = config?.logger;

        // Generate a config guid if not provided (using a simple UUID v4-like format)
        this.configGuid = uuidv4();

        // Subscribe to abort signal for cleanup if provided
        if (options?.abortSignal) {
            options.abortSignal.addEventListener('abort', () => {
                this.close();
            });
        }

        // Initialize Dunamis SDK if apiKey and project are provided
        if (options?.project && options?.environment) {
            // Map Sentry environment to Dunamis environment
            // production -> PROD, staging/preview/development -> STAGE
            this.dunamisEnvironment =
                options.environment === 'production' ? Environment.PROD : Environment.STAGE;

            this.initializeDunamis({
                apiKey: options.project,
                project: options.project,
                environment: this.dunamisEnvironment,
            });
        } else {
            this.logger?.warn(
                '[DunamisIntegration] apiKey, project, or environment not provided - Dunamis SDK will not be initialized',
            );
        }
    }

    /**
     * Initialize the Dunamis SDK with the provided configuration.
     */
    private initializeDunamis(options: {
        apiKey: string;
        project: string;
        environment: Environment.STAGE | Environment.PROD;
    }): void {
        const config = this.sdk.getConfig();
        if (!config) {
            this.logger?.error(
                '[DunamisIntegration] Cannot initialize Dunamis - SDK config not available',
            );
            return;
        }

        const status = setIngestConfig(
            this.configGuid,
            options.environment,
            options.project,
            options.project,
            SourceType.HOST,
            SourceCategory.WEB,
            Consent.TRUE,
        );

        if (status !== Status.SUCCESS) {
            this.logger?.error(
                `[DunamisIntegration] Failed to set ingest config: status ${status}`,
            );
            return;
        }

        // Get common data from SDK config
        const productId = (config as { productId?: string }).productId || 'AssetBrowser';
        const appName = (config as { appName?: string }).appName;
        const appVersion = (config as { appVersion?: string }).appVersion;
        const clientId = (config as { clientId?: string }).clientId;

        const commonData: { [key: string]: unknown } = {
            source: {
                name: appName || productId,
                version: appVersion || 'unknown',
                client_id: clientId,
            },
        };

        // Start ingest instance
        const onStatus: OnStatus = (status: Status) => {
            if (status !== Status.SUCCESS) {
                this.logger?.warn(
                    `[DunamisIntegration] Ingest status: ${Status[status] || status}`,
                );
            }
        };

        const result = ingest.start(this.configGuid, commonData, onStatus);

        if (result.error !== Status.SUCCESS) {
            this.logger?.error(
                `[DunamisIntegration] Failed to start ingest instance: status ${result.error}`,
            );
            return;
        }

        this.ingestInstance = result.instance;

        // Call online() to enable HTTP calls
        // Async exceptions will be automatically reported to Sentry
        void online()
            .then((onlineStatus) => {
                if (onlineStatus !== Status.SUCCESS) {
                    this.logger?.warn(
                        `[DunamisIntegration] online() returned non-success status: ${onlineStatus}`,
                    );
                }
                return undefined;
            })
            .catch((error) => {
                // Handle promise rejection (e.g., network issues)
                // Errors are automatically reported to Sentry via global error handler
                this.logger?.warn(
                    `[DunamisIntegration] online() promise rejected: ${error instanceof Error ? error.message : String(error)}`,
                );
            });
    }

    /**
     * Sentry v10+ integration hook - called for each event
     * Processes events and forwards them to Dunamis asynchronously
     * CRITICAL: Always returns the event unchanged so Sentry.io continues normally
     *
     * @param event The Sentry event to process
     * @param _hint Event hint containing additional context (unused)
     * @param _client The Sentry client instance (unused)
     * @returns The event to allow Sentry to continue processing
     */
    public processEvent(event: Event, _hint: EventHint, _client: Client): Event | null {
        this.logger?.debug(
            `[DunamisIntegration] processEvent called for event type: ${event.type || 'exception'}, event_id: ${event.event_id}`,
        );

        // Process the event asynchronously - this does NOT block Sentry's pipeline
        // Async exceptions will be automatically reported to Sentry
        this.sendEventToDunamis(event);

        // Always return the event unchanged so Sentry continues normally
        // This ensures that even if Dunamis processing fails, Sentry.io still receives the event
        return event;
    }

    /**
     * Process a Sentry event and forward it to Dunamis via the Dunamis SDK.
     * This method is called for every event that Sentry processes (exceptions and transactions).
     * Events are forwarded immediately as the SDK handles its own batching logic.
     *
     * @param sentryEvent The event from Sentry
     */
    private async sendEventToDunamis(sentryEvent: Event): Promise<void> {
        if (!this.ingestInstance || sentryEvent.type !== 'transaction') {
            return;
        }

        // Transform Sentry's event format to Dunamis event format
        const eventData = this.transformToDunamisEvent(sentryEvent);

        this.logger?.debug(
            `[DunamisIntegration] Forwarding event to Dunamis SDK: ${sentryEvent.event_id}`,
        );

        // Submit event to Dunamis SDK
        const status = ingest.submitEvent(
            this.ingestInstance,
            eventData,
            true,
            false,
            TriBool.TRUE,
        );

        if (status !== Status.SUCCESS) {
            this.logger?.warn(`[DunamisIntegration] Failed to submit event: status ${status}`);
        } else {
            this.logger?.debug(
                `[DunamisIntegration] Successfully submitted event to Dunamis SDK: ${sentryEvent.event_id}`,
            );
        }
    }

    /**
     * Infer the event category from Sentry event data.
     * Maps Sentry platform/context data to Dunamis category values.
     *
     * @param sentryEvent Event from Sentry
     * @param allTags Collected tags from event and scope
     * @returns Category value: 'DESKTOP', 'WEB' or 'MOBILE'
     */
    private inferCategory(
        sentryEvent: Event,
        allTags: { [key: string]: unknown },
    ): 'DESKTOP' | 'WEB' | 'MOBILE' {
        // 1. Check if desktop app (Photoshop, Illustrator, InDesign)
        const appName = allTags['host.appName'] as string | undefined;
        if (appName === 'Photoshop' || appName === 'Illustrator' || appName === 'InDesign') {
            return 'DESKTOP';
        }

        // 2. Check OS context for mobile
        const osName = sentryEvent.contexts?.os?.name?.toLowerCase();
        if (osName === 'ios' || osName === 'android') {
            return 'MOBILE';
        }

        // 3. Check platform for node (could be SERVICE or WEB)
        // For browser-based UAB, node platform typically indicates a service/backend
        // within the web application.
        if (sentryEvent.platform === 'node') {
            return 'WEB';
        }

        // 4. Default to WEB (most common case for browser-based UAB)
        return 'WEB';
    }

    /**
     * Transform Sentry event format to Dunamis SDK event format.
     * This method extracts all relevant data from the Sentry event and
     * structures it according to Dunamis SDK submitEvent requirements.
     *
     * @param sentryEvent Event from Sentry (exception or transaction)
     * @returns Transformed JSON object for Dunamis SDK submitEvent
     */
    private transformToDunamisEvent(sentryEvent: Event): { [key: string]: unknown } {
        // Helper to ensure string values are valid (replace undefined/null/empty with UNKNOWN)
        const safeString = (value: unknown): string => {
            if (value === null || value === undefined) {
                return 'UNKNOWN';
            }
            const str = String(value).trim();
            return str || 'UNKNOWN';
        };

        // Collect tags from both event.tags and scope
        const allTags: { [key: string]: unknown } = {};

        // First, get tags from the event itself
        if (sentryEvent.tags) {
            Object.assign(allTags, sentryEvent.tags);
        }

        // Also get tags from the current scope (set by configureSentry)
        const scope = getCurrentScope();
        if (scope?.getScopeData) {
            const scopeData = scope.getScopeData();
            if (scopeData?.tags) {
                Object.assign(allTags, scopeData.tags);
            }
        }

        // Infer category from Sentry event data and tags
        const category = this.inferCategory(sentryEvent, allTags);

        // Build event data object with dot notation for event fields
        const eventData: { [key: string]: unknown } = {
            // Event metadata with dot notation
            'event.id': sentryEvent.event_id || 'UNKNOWN',
            'event.type': 'performance',
            'event.subtype': 'transaction',
            'event.category': category,
            'event.subcategory': 'Unknown',
            'event.workflow': safeString(sentryEvent.contexts?.trace?.op),

            // Environment and release
            environment: this.dunamisEnvironment === Environment.PROD ? 'prod' : 'stage',
            release: safeString(sentryEvent.release),

            // User context
            'user.id': safeString(sentryEvent.user?.id),

            // Browser context
            'browser.name': safeString(sentryEvent.contexts?.browser?.name),
            'browser.version': safeString(sentryEvent.contexts?.browser?.version),

            // OS context
            'os.name': safeString(sentryEvent.contexts?.os?.name),
            'os.version': safeString(sentryEvent.contexts?.os?.version),
            platform: safeString(sentryEvent.platform),
        };

        // Process all collected tags
        for (const [key, value] of Object.entries(allTags)) {
            // Copy all tags for backward compatibility
            eventData[`tag.${key}`] = value;

            // Extract host.* tags as structured host fields
            if (key.startsWith('host.')) {
                eventData[key] = value;
            }

            // Extract user.* tags as structured user fields
            if (key.startsWith('user.')) {
                eventData[key] = value;
            }
        }

        // Incude the 'aup-sdk:loading-total' measurement and overal transaction duration
        const loadingTotalSpan = sentryEvent.spans?.find(
            (span) => span.description === 'aup-sdk:loading-total',
        );
        const loadingTotaldurationMs =
            loadingTotalSpan?.timestamp && loadingTotalSpan?.start_timestamp
                ? (loadingTotalSpan.timestamp - loadingTotalSpan.start_timestamp) * 1000
                : undefined;
        eventData['custom.trn.loading_total_duration_ms'] = loadingTotaldurationMs;

        if (sentryEvent.timestamp && sentryEvent.start_timestamp) {
            const durationMs = (sentryEvent.timestamp - sentryEvent.start_timestamp) * 1000;
            eventData['custom.trn.duration_ms'] = durationMs;
        }
        eventData['custom.trn.name'] = safeString(sentryEvent.transaction);

        // Add request URL if available
        if (sentryEvent.request?.url) {
            eventData['custom.request.url'] = safeString(sentryEvent.request.url);
        }

        return eventData;
    }

    /**
     * Cleanup method - stops the ingest instance.
     * Called automatically when abortSignal fires, or can be called manually.
     *
     * Note: This method handles async cleanup internally to ensure proper resource cleanup
     * even when called from synchronous dispose() functions. The cleanup runs in the
     * background and errors are handled internally.
     */
    private close(): void {
        if (this.ingestInstance) {
            const instance = this.ingestInstance;

            // Clear reference immediately to prevent further operations
            this.ingestInstance = undefined;

            // Perform async cleanup in background - errors are handled internally
            void ingest
                .stop(instance)
                .then(() => {
                    this.logger?.debug('[DunamisIntegration] Ingest instance stopped');
                    return undefined;
                })
                .catch((error) => {
                    this.logger?.error(
                        '[DunamisIntegration] Error stopping ingest instance:',
                        error,
                    );
                });
        }
    }
}
