export class Timer {
    constructor() {
        this.timeoutId = null;
    }
    /**
     * Sets up a timer to run the function after the specified time
     * @param fn The function to run
     * @param ms The time in milliseconds to wait before running the function
     */
    startTimer(fn, ms) {
        this.clearTimer(); // clear any existing timer
        if (fn) {
            this.timeoutId = setTimeout(fn, ms);
        }
    }
    /**
     * Clears the timer
     */
    clearTimer() {
        if (this.timeoutId) {
            clearTimeout(this.timeoutId);
        }
        this.timeoutId = null;
    }
}
