import type { Tooltip as SpectrumTooltip } from '@ccx-public/spectrum-web-component-fallbacks/dist/tooltip';
import type { ReactProps } from './utils';
import createWrapper from './utils/createWrapper';
import { SWCLoader } from './utils/SWCLoader';
import interopRequireDefault from './utils/interopRequireDefault';

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2Tooltip: React.ComponentType<
    ReactProps<SpectrumTooltip, RS2CompatProps>
> = process.env.INCLUDE_RS2
    ? interopRequireDefault(require('react-spectrum/Tooltip')).default
    : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

let swcLoader;
if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(['sp-tooltip'], async () => {
        const { Tooltip } = await import(
            /* webpackChunkName: "SpTooltip" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/tooltip'
        );
        return [Tooltip];
    });
}

type RS2CompatProps = {
    testId?: string;
    children: React.ReactNode;
};

export default createWrapper<SpectrumTooltip, RS2CompatProps>({
    displayName: 'Tooltip',
    fallback: RS2Tooltip,
    swcLoader,
    swcProps: (props) => {
        const { className, ...rest } = props;
        return { ...rest, class: className };
    },
    tagName: 'sp-tooltip',
});
