export class EventStore {
    constructor() {
        this.items = [];
    }
    count() {
        return this.items.length;
    }
    push(item) {
        this.items.push(item);
    }
    peek(count) {
        count = Math.min(count, this.items.length);
        return this.items.slice(0, count);
    }
    pop(count) {
        count = Math.min(count, this.items.length);
        this.items.splice(0, count);
    }
    clear() {
        this.items = [];
    }
}
