// https://opensource.adobe.com/spectrum-web-components/components/radio/
// https://git.corp.adobe.com/torq/react-spectrum/tree/develop/src/RadioGroup
import type { RadioGroup as RadioGroupType } from '@ccx-public/spectrum-web-component-fallbacks/dist/radio';
import React, { useEffect, useRef } from 'react';
import type { ReactProps } from './utils';
import { filterBooleanProps, useComponent } from './utils';
import createWrapper from './utils/createWrapper';
import { SWCLoader } from './utils/SWCLoader';
import interopRequireDefault from './utils/interopRequireDefault';

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2RadioGroup: React.ComponentType<
    ReactProps<RadioGroupType, RS2CompatProps>
> = process.env.INCLUDE_RS2
    ? interopRequireDefault(require('react-spectrum/RadioGroup')).default
    : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

let swcLoader;
if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(['sp-radio-group'], async () => {
        const { RadioGroup } = await import(
            /* webpackChunkName: "SpRadio" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/radio'
        );
        return [RadioGroup];
    });
}

type RS2CompatProps = {
    /**
     * Which radio should be selected by default
     */
    defaultSelectedValue?: string;
    /**
     * Controlled: value of which radio should be selected
     */
    selectedValue?: string;

    /**
     * Display options in horizontal (default) or vertical alignment
     */
    vertical?: boolean;

    /**
     * Change event handler function
     */
    onChange?: (value: string) => unknown;
};

export default createWrapper<RadioGroupType, RS2CompatProps>({
    displayName: 'RadioGroup',
    fallback: RS2RadioGroup,
    swcLoader,
    SWCWrapper: (props) => {
        const radioGroupWrapperRef = useRef<RadioGroupType>(null);
        const {
            className,
            selectedValue,
            defaultSelectedValue,
            vertical = false,
            onChange,
            ...rest
        } = props;

        useEffect(() => {
            const current = radioGroupWrapperRef.current;

            const change = (event: Event) => {
                const target = event.target as RadioGroupType;
                onChange?.(target.selected);
            };

            if (current && onChange) {
                current.addEventListener('change', change);
            }

            return () => {
                if (current && onChange) {
                    current.removeEventListener('change', change);
                }
            };
        }, [onChange]);

        // ReactSpectrum2        | SpectrumWebComponent
        // ---------------------------------------------
        // selctedValue          | selected
        // defaultSelectedValue  | selected
        // vertical              | vertical
        // !vertical             | horizontal

        const RadioGroup = useComponent('sp-radio-group');
        return (
            <RadioGroup
                {...rest}
                {...filterBooleanProps({
                    horizontal: !vertical,
                    vertical,
                    selected: selectedValue
                        ? selectedValue
                        : defaultSelectedValue,
                })}
                class={className}
                ref={radioGroupWrapperRef}
            />
        );
    },
    tagName: 'sp-radio-group',
});
