export class DateTime {
    /**
     * @param date a date object
     * @returns ISO-8601 formatted local timestamp string with timezone offset
     */
    static format(date) {
        try {
            const tzOffset = date.getTimezoneOffset();
            const absTZOffset = Math.abs(tzOffset);
            const tzHours = Math.floor(absTZOffset / 60)
                .toString()
                .padStart(2, "0");
            const tzMins = (absTZOffset % 60).toString().padStart(2, "0");
            const tzSign = tzOffset > 0 ? "-" : "+"; // Sign is inverted
            const formattedTZOffset = tzSign + tzHours + tzMins;
            const formattedTimeStamp = new Date(date.getTime() - tzOffset * 60 * 1000)
                .toISOString()
                .replace("Z", formattedTZOffset);
            return formattedTimeStamp;
        }
        catch (error) {
            return "";
        }
    }
}
