//https://react-spectrum.corp.adobe.com/storybook/?path=/story/progress--default
//https://opensource.adobe.com/spectrum-web-components/components/progress-bar/api/
// SWC has ProgressBar and RS-2 has Progress
import type { ProgressBar as ProgressBarType } from '@ccx-public/spectrum-web-component-fallbacks/dist/progress-bar';
import { filterBooleanProps } from './utils';
import createWrapper from './utils/createWrapper';
import { SWCLoader } from './utils/SWCLoader';
import interopRequireDefault from './utils/interopRequireDefault';

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2Progress: React.ComponentType<unknown> = process.env.INCLUDE_RS2
    ? interopRequireDefault(require('react-spectrum/Progress')).default
    : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

let swcLoader;
if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(['sp-progress-bar'], async () => {
        const { ProgressBar } = await import(
            /* webpackChunkName: "SpProgessBar" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/progress-bar'
        );

        return [ProgressBar];
    });
}

type RS2CompatProps = {
    /**
     * Value between the min and max that specifies the progression of the progress bar.
     * Calculated percentage is automatically clamped to 0-100.
     */
    value?: number;

    /**
     * Boolean to determine if the Progress component should endlessly scroll (indeterminate)
     */
    isIndeterminate?: boolean;

    /**
     * What type of progress bar to show: 'positive' (green), 'warning' (orange), 'critical' (red)
     */
    variant?: 'positive' | 'warning' | 'critical' | 'overBackground';

    /**
     * Determines the positioning of the provided label.
     * Limited to 'left', 'top', or 'bottom'
     */
    labelPosition?: 'left' | 'top' | 'bottom';

    /**
     * SWC valid sizes are 's' | 'm' | 'l' | 'xl'
     * RS2 valid sizes are 'S' | 'M'
     */
    size?: ProgressBarType['size'] | 'S' | 'M';
};

export default createWrapper<ProgressBarType, RS2CompatProps>({
    displayName: 'Progress',
    fallback: RS2Progress,
    swcLoader,
    swcProps: (props) => {
        // Few properties are not supported by SWC like :: variant , labelPosition, showPercentage, min , max , size
        const {
            className,
            isIndeterminate,
            value,
            variant,
            labelPosition,
            size,
            ...rest
        } = props;

        // ReactSpectrum2           | SpectrumWebComponent
        // ---------------------------------------------
        // value                    | progress
        // isIndeterminate          | indeterminate
        // variant="overBackground" | static-color="white"
        // labelPosition            | sideLabel

        return {
            ...rest,
            ...filterBooleanProps({
                indeterminate: isIndeterminate,
                'static-color':
                    variant === 'overBackground' ? 'white' : undefined,
                'side-label': labelPosition === 'left' ? true : false,
            }),
            class: className,
            progress: value,
            size: getSWCSize(size),
        };
    },
    tagName: 'sp-progress-bar',
});

function getSWCSize(
    size: RS2CompatProps['size']
): ProgressBarType['size'] | undefined {
    switch (size) {
        case 'S':
            return 's';
        case 'M':
            return 'm';
        default:
            return size;
    }
}
