const hashCode = (brandId)=>{
    let hash = 0;
    for(let i = 0, len = brandId.length; i < len; i++){
        const chr = brandId.charCodeAt(i);
        hash = (hash << 5) - hash + chr;
        hash |= 0;
    }
    return Math.abs(hash);
};
const getBrandCoverIndex = (brandId, totalCovers)=>{
    if (!brandId) return 0;
    return hashCode(brandId) % totalCovers;
};
export { getBrandCoverIndex, hashCode };
