import type { MutableRefObject, RefCallback } from 'react';

export default function mergeRefs<T>(
    refs: Array<MutableRefObject<T> | RefCallback<T> | null>
): RefCallback<T> {
    return function (value: T) {
        refs.forEach((ref) => {
            if (!ref) {
                return;
            }

            if (typeof ref === 'function') {
                ref(value);
                return;
            }

            ref.current = value;
        });
    };
}
