/**
 * Simple matchMedia polyfill for UXP environment
 * Handles basic media queries needed for the desktop.js bundle
 */

const createMatchMediaPolyfill = () => {
    const parseQuery = (query: string): boolean => {
        // Clean up the query string
        const cleanQuery = query.trim().toLowerCase();

        // Handle pointer:coarse query (most common case for touch detection)
        if (cleanQuery.includes('pointer:coarse') || cleanQuery.includes('pointer: coarse')) {
            // In UXP desktop environment, we assume non-touch (pointer:fine)
            // Touch devices would typically have pointer:coarse
            return false;
        }

        // Handle pointer:fine query
        if (cleanQuery.includes('pointer:fine') || cleanQuery.includes('pointer: fine')) {
            // In UXP desktop environment, we assume fine pointer (mouse)
            return true;
        }

        // Handle width queries
        const widthMatch = cleanQuery.match(/\((?:max-width|min-width|width)\s*:\s*(\d+)px\)/);
        if (widthMatch) {
            const targetWidth = parseInt(widthMatch[1], 10);
            const currentWidth = window.screen?.width || window.innerWidth || 1920;

            if (cleanQuery.includes('max-width')) {
                return currentWidth <= targetWidth;
            } else if (cleanQuery.includes('min-width')) {
                return currentWidth >= targetWidth;
            } else {
                return currentWidth === targetWidth;
            }
        }

        // Handle height queries
        const heightMatch = cleanQuery.match(/\((?:max-height|min-height|height)\s*:\s*(\d+)px\)/);
        if (heightMatch) {
            const targetHeight = parseInt(heightMatch[1], 10);
            const currentHeight = window.screen?.height || window.innerHeight || 1080;

            if (cleanQuery.includes('max-height')) {
                return currentHeight <= targetHeight;
            } else if (cleanQuery.includes('min-height')) {
                return currentHeight >= targetHeight;
            } else {
                return currentHeight === targetHeight;
            }
        }

        // Handle orientation queries
        if (
            cleanQuery.includes('orientation:landscape') ||
            cleanQuery.includes('orientation: landscape')
        ) {
            const width = window.screen?.width || window.innerWidth || 1920;
            const height = window.screen?.height || window.innerHeight || 1080;
            return width > height;
        }

        if (
            cleanQuery.includes('orientation:portrait') ||
            cleanQuery.includes('orientation: portrait')
        ) {
            const width = window.screen?.width || window.innerWidth || 1920;
            const height = window.screen?.height || window.innerHeight || 1080;
            return height > width;
        }

        // Handle media types
        if (cleanQuery.includes('screen')) {
            return true; // UXP is screen-like
        }

        if (cleanQuery.includes('print')) {
            return false; // UXP is not print
        }

        if (cleanQuery.includes('all')) {
            return true; // 'all' matches everything
        }

        // Default case - return false for unknown queries
        console.warn(`matchMedia polyfill: Unknown query "${query}", returning false`);
        return false;
    };

    return (query: string) => {
        const matches = parseQuery(query);

        // Return a simple object that satisfies the basic matchMedia usage
        return {
            matches,
            media: query,
            addListener: () => {}, // No-op for UXP
            removeListener: () => {}, // No-op for UXP
            addEventListener: () => {}, // No-op for UXP
            removeEventListener: () => {}, // No-op for UXP
            dispatchEvent: () => false, // No-op for UXP
            onchange: null,
        } as MediaQueryList;
    };
};

/**
 * Load matchMedia polyfill if needed
 */
export const loadMatchMediaPolyfillIfNeeded = (): void => {
    if (typeof window !== 'undefined' && !window.matchMedia) {
        console.log('Loading matchMedia polyfill for UXP environment (UAB fallback)');
        window.matchMedia = createMatchMediaPolyfill();
    }
};

// Force side effect
//This condition help prevent tree-shaking
if (typeof window !== 'undefined') {
    loadMatchMediaPolyfillIfNeeded();
}
