import React from 'react';
import type { ButtonGroup as ButtonGroupType } from '@ccx-public/spectrum-web-component-fallbacks/dist/button-group';
import type { ReactProps } from './utils';
import { filterBooleanProps, isUXP, useComponent } from './utils';
import createWrapper from './utils/createWrapper';
import { SWCLoader } from './utils/SWCLoader';
import interopRequireDefault from './utils/interopRequireDefault';
import { forwardRef, useEffect, useRef } from 'react';
import type {
    ActionGroup,
    ActionGroup as ActionGroupType,
} from '@ccx-public/spectrum-web-component-fallbacks/dist/action-group';

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2ButtonGroup: React.ComponentType<
    ReactProps<ButtonGroupType, ButtonGroupRS2CompatProps>
> = process.env.INCLUDE_RS2
    ? interopRequireDefault(require('react-spectrum/ButtonGroup')).default
    : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

let buttonGroupLoader;
let actionGroupLoader;

if (!process.env.EXCLUDE_SWC) {
    buttonGroupLoader = new SWCLoader(['sp-button-group'], async () => {
        const { ButtonGroup } = await import(
            /* webpackChunkName: "SpButtonGroup" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/button-group'
        );
        return [ButtonGroup];
    });

    actionGroupLoader = new SWCLoader(['sp-action-group'], async () => {
        const { ActionGroup } = await import(
            /* webpackChunkName: "SpActionGroup" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/action-group'
        );
        return [ActionGroup];
    });
}

type ButtonGroupRS2CompatProps = {
    /**
     * Renders the button group as a row or a column
     */
    orientation: 'horizontal' | 'vertical' | 'both';
    multiple?: boolean;
    /**
     * Callback function to be called on change
     */
    onChange?: (event: string[]) => void;
    /**
     * Selected Value
     */
    value?: string | string[];
};

// https://git.corp.adobe.com/torq/react-spectrum/blob/develop/src/ButtonGroup/js/ButtonGroup.js
// https://opensource.adobe.com/spectrum-web-components/components/button-group/
const NormalButtonGroup = createWrapper<
    ButtonGroupType,
    ButtonGroupRS2CompatProps
>({
    displayName: 'ButtonGroup',
    fallback: RS2ButtonGroup,
    swcLoader: buttonGroupLoader,
    swcProps: (props) => {
        // Important Differences:
        // ReactSpectrum2        | SpectrumWebComponent     | UXPWebComponent
        // -----------------------------------------------------------------
        // orientation:          | vertical: boolean        | variant:
        //     'vertical' |      |                          |   'vertical'
        //     'horizontal       |                          |   'horizontal
        const { className, orientation, ...rest } = props;
        const vertical = orientation === 'vertical' || undefined;
        const compatabilityProps = isUXP
            ? // https://developers.corp.adobe.com/uxp/docs/apis/spectrum_uxp/spectrum_uxp_user_interface.md#sp-action-button
              // UXP has a special 'align' property, we will just set the default
              // to be 'center', which is standard in RS2 and SWC
              { variant: orientation, align: 'center' }
            : { vertical };
        return { ...rest, ...compatabilityProps, class: className };
    },
    tagName: 'sp-button-group',
});

const ActionButtonGroup = createWrapper<
    ActionGroupType,
    ButtonGroupRS2CompatProps
>({
    displayName: 'ActionGroup',
    fallback: RS2ButtonGroup,
    swcLoader: actionGroupLoader,
    SWCWrapper: function SpActionGroup(props) {
        const actionGroupContainer = useRef<ActionGroupType>(null);
        const { className, value, multiple, orientation, onChange, ...rest } =
            props;

        const vertical = orientation === 'vertical' || undefined;
        const selects = multiple ? 'multiple' : 'single';
        const selectedValues = selects === 'multiple' ? value : [value].flat();

        const compatabilityProps = isUXP
            ? // https://developers.corp.adobe.com/uxp/docs/apis/spectrum_uxp/spectrum_uxp_user_interface.md#sp-action-button
              // UXP has a special 'align' property, we will just set the default
              // to be 'center', which is standard in RS2 and SWC
              { variant: orientation, align: 'center' }
            : {
                  vertical,
                  selected: JSON.stringify(selectedValues),
                  ...(selects && { selects }),
              };

        useEffect(() => {
            const current = actionGroupContainer.current;

            const handleOnChange = (event: Event) => {
                const target = event.target as ActionGroup;
                onChange?.(target.selected);
            };

            if (current && onChange) {
                current.addEventListener('change', handleOnChange);
            }

            return () => {
                if (current && onChange) {
                    current.removeEventListener('change', handleOnChange);
                }
            };
        }, [onChange, value]);

        const ActionGroup = useComponent('sp-action-group');

        return (
            // eslint-disable-next-line @typescript-eslint/ban-ts-comment
            // @ts-ignore
            <ActionGroup
                ref={actionGroupContainer}
                {...rest}
                {...compatabilityProps}
                {...filterBooleanProps({
                    vertical,
                })}
                class={className}
            />
        );
    },
    tagName: 'sp-action-group',
});

export default forwardRef(function ButtonGroup(
    props: ReactProps<ButtonGroupType, ButtonGroupRS2CompatProps>,
    ref
) {
    if (props.onChange) {
        return <ActionButtonGroup {...props} ref={ref} />;
    }
    return <NormalButtonGroup {...props} ref={ref} />;
});
