// https://opensource.adobe.com/spectrum-web-components/components/accordion/
// https://git.corp.adobe.com/torq/react-spectrum/tree/develop/src/Accordion
import type {
    Accordion as AccordionType,
    AccordionItem as AccordionItemType,
} from '@ccx-public/spectrum-web-component-fallbacks/dist/accordion';
import type { Attributes, JSXElementConstructor, ReactElement } from 'react';
import { Children } from 'react';
import React from 'react';
import createWrapper from './utils/createWrapper';
import { SWCLoader } from './utils/SWCLoader';
import { filterBooleanProps } from './utils';
import interopRequireDefault from './utils/interopRequireDefault';

let RS2Accordion: React.ComponentType<unknown> | undefined = undefined;
let RS2AccordionItem: React.ComponentType<unknown> | undefined = undefined;

if (process.env.INCLUDE_RS2) {
    /* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
    const AccordionModule = interopRequireDefault(
        require('react-spectrum/Accordion')
    );
    RS2Accordion = AccordionModule.Accordion;
    RS2AccordionItem = AccordionModule.AccordionItem;
    /* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
}

let swcLoader;
if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(
        ['sp-accordion', 'sp-accordion-item'],
        async () => {
            const { Accordion, AccordionItem } = await import(
                /* webpackChunkName: "SpAccordion" */
                '@ccx-public/spectrum-web-component-fallbacks/dist/accordion'
            );
            return [Accordion, AccordionItem];
        }
    );
}

type RS2CompatProps = {
    /**
     * Flag that decides whether to open multiple accordionItem
     */
    multiselectable?: boolean;
    selectedIndex?: number;
    defaultSelectedIndex?: number;
};

export const Accordion = createWrapper<AccordionType, RS2CompatProps>({
    displayName: 'Accordion',
    fallback: RS2Accordion,
    swcLoader,
    swcProps: (props) => {
        const {
            multiselectable,
            children,
            className,
            defaultSelectedIndex,
            selectedIndex,
            ...rest
        } = props;

        // ReactSpectrum2        | SpectrumWebComponent
        // ---------------------------------------------
        // multiselectable       | 'allow-multiple'
        // handling selectedIndex and defaultSelectedIndex

        const accordionItems = Children.toArray(children);
        const index =
            selectedIndex || selectedIndex == 0
                ? selectedIndex
                : defaultSelectedIndex
                ? defaultSelectedIndex
                : accordionItems.length;
        if (index >= 0 && index < accordionItems.length) {
            const accordionItem = accordionItems[
                index
            ] as unknown as ReactElement<
                unknown,
                string | JSXElementConstructor<unknown>
            >;
            const target = React.cloneElement(accordionItem, {
                open: true,
            } as Partial<unknown> & Attributes);
            accordionItems[index] = target;
        }

        return {
            ...rest,
            ...filterBooleanProps({ 'allow-multiple': multiselectable }),
            children: accordionItems,
            class: className,
        };
    },
    tagName: 'sp-accordion',
});

type RS2AccordionItemCompatProps = {
    /**
     * header of accordion Item
     */
    header?: string;
};

export const AccordionItem = createWrapper<
    AccordionItemType,
    RS2AccordionItemCompatProps
>({
    displayName: 'AccordionItem',
    fallback: RS2AccordionItem,
    swcLoader,
    swcProps: (props) => {
        const { className, header, ...rest } = props;

        // ReactSpectrum2        | SpectrumWebComponent
        // ---------------------------------------------
        // readOnly              | readonly
        // label                 | label is directly passed as innerHTML text
        // renderlabel:          | no such flag to conditionally render label
        // flag based on which   |
        // label is rendered     |

        return {
            class: className,
            label: header,
            ...rest,
        };
    },
    tagName: 'sp-accordion-item',
});
