// https://opensource.adobe.com/spectrum-web-components/components/checkbox/
// https://git.corp.adobe.com/torq/react-spectrum/tree/develop/src/Checkbox
import type { Checkbox as CheckboxType } from '@ccx-public/spectrum-web-component-fallbacks/dist/checkbox';
import React, { useEffect, useRef } from 'react';
import { filterBooleanProps, useComponent } from './utils';
import createWrapper from './utils/createWrapper';
import { SWCLoader } from './utils/SWCLoader';
import interopRequireDefault from './utils/interopRequireDefault';

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2Checkbox: React.ComponentType<unknown> = process.env.INCLUDE_RS2
    ? interopRequireDefault(require('react-spectrum/Checkbox')).default
    : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

let swcLoader;
if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(['sp-checkbox'], async () => {
        const { Checkbox } = await import(
            /* webpackChunkName: "SpCheckbox" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/checkbox'
        );
        return [Checkbox];
    });
}

type RS2CompatProps = {
    /**
     * The label to display with the checkbox
     */
    label?: string;
    /**
     * Won't allow a permanent selection
     */
    readOnly?: boolean;
    /**
     * Flag that decides whether to display label
     */
    renderLabel?: boolean;
    onChange?: (value: boolean, event: Event) => unknown;
    onClick?: (event: React.MouseEvent) => unknown;
};

export default createWrapper<CheckboxType, RS2CompatProps>({
    displayName: 'Checkbox',
    fallback: RS2Checkbox,
    swcLoader,
    SWCWrapper: (props) => {
        const checkboxWrapperRef = useRef<CheckboxType>(null);
        const {
            className,
            renderLabel = true,
            readOnly,
            label,
            checked,
            disabled,
            invalid,
            indeterminate,
            emphasized,
            children,
            onChange,
            ...rest
        } = props;

        useEffect(() => {
            const current = checkboxWrapperRef.current;

            const change = (event: Event) => {
                const target = event.target as CheckboxType;
                onChange?.(target.checked, event);
            };

            if (current && onChange) {
                current.addEventListener('change', change);
            }

            return () => {
                if (current && onChange) {
                    current.removeEventListener('change', change);
                }
            };
        }, [onChange]);

        // ReactSpectrum2        | SpectrumWebComponent
        // ---------------------------------------------
        // readOnly              | readonly
        // label                 | label is directly passed as innerHTML text
        // renderlabel:          | no such flag to conditionally render label
        // flag based on which   |
        // label is rendered     |

        // checked, disabled, invalid, indeterminate, emphasized, readOnly are props in RS2
        // but when passed directly as attributes to SWC, they don't work as expected.
        // So these attributes are only passed if they are true;

        // label must be passed a prop and not as children to the wrapper.

        const Checkbox = useComponent('sp-checkbox');
        return (
            <Checkbox
                {...rest}
                {...filterBooleanProps({
                    checked,
                    disabled,
                    emphasized,
                    indeterminate,
                    invalid,
                    readonly: readOnly,
                })}
                class={className}
                ref={checkboxWrapperRef}
            >
                {renderLabel ? label : ''}
                {children}
            </Checkbox>
        );
    },
    tagName: 'sp-checkbox',
});
