import React, { Component } from 'react';
import { observer } from 'mobx-react';
import type { SAM } from '@ccx-public/component-types';
import type { IAnalyticsData, ICallbacks, IHostProductData, IIMSData, Themes } from '@ccx/ccx-cdo';
import {
    CloudDocuments,
    Deleted,
    Recents,
    SharedWithYou,
    ThinCDOProvider,
    getExistingCDCGlobalStore,
} from '@ccx/ccx-cdo';
import { AssetBrowser } from '@ccx-public/component-types';
import { EventType, Workflow } from '@csc/collection-view';
import type ComponentLoaderInitOptions from '@csc/common/@types/ComponentLoaderInitOptions';

interface viewProps {
    routeId?: string;
    routeToParent?: boolean;
}

type Props = React.PropsWithChildren<{
    sharedConfig: ComponentLoaderInitOptions;
    hostProductData: IHostProductData;
    imsData: IIMSData;
    currentView?: AssetBrowser.ContentViewType;
    contentViewProps?: viewProps;
    analyticsData?: IAnalyticsData;
    callbacks?: ICallbacks;
    messages?: { [id: string]: string };
    theme?: Themes;
    disableNativeControls?: boolean;
    __assetContext_forTestingOnly?: SAM.AssetContext;
}>;

@observer
export default class CDOReactComponent extends Component<Props> {
    private renderCDOContentView() {
        const currentView = this.props.currentView!;
        const isCloudDocuments: AssetBrowser.ContentViewType | 'your-files' =
            currentView === AssetBrowser.ContentViewType.CloudDocuments
                ? 'your-files'
                : currentView;
        if (isCloudDocuments) {
            getExistingCDCGlobalStore()?.cdoMetrics.fireEvent({
                event: {
                    subcategory: 'Files',
                    type: EventType.Click,
                    subtype: isCloudDocuments,
                    workflow: Workflow.Navigation,
                },
            });
        }
        switch (currentView) {
            case AssetBrowser.ContentViewType.SharedWithYou:
                return <SharedWithYou {...this.props.contentViewProps} />;
            case AssetBrowser.ContentViewType.Deleted:
                return <Deleted {...this.props.contentViewProps} />;
            case AssetBrowser.ContentViewType.CloudDocuments:
                return <CloudDocuments {...this.props.contentViewProps} />;
            case AssetBrowser.ContentViewType.Recents:
                return <Recents {...this.props.contentViewProps} />;
            default:
                return null;
        }
    }

    render() {
        return (
            <div
                className={`theme-${this.props.theme} cdo-CoreVariables`}
                style={{ height: '100%', width: '100%' }}
            >
                {/**
                 * Only rendering ThinCDOProvider because FMHS Recents is the only thing using CDOReactComponent
                 * since the other tabs are in webviews.
                 * When FMHS enableUABWebView flag is disabled, CDOReactComponent is rendered for all tabs, but
                 * that comes from old UAB v2.
                 */}
                <ThinCDOProvider
                    locale={this.props.hostProductData.uiLocale}
                    theme={this.props.theme}
                    disableNativeControls={this.props.disableNativeControls}
                >
                    {this.renderCDOContentView()}
                    {this.props.children}
                </ThinCDOProvider>
            </div>
        );
    }
}
