/* eslint-disable prettier/prettier */


    import React, { useContext } from "react";
    import { ThemeContext } from "../utils/ThemeContext";

import type { IconDeleteOutline } from '@ccx-public/spectrum-web-component-fallbacks/dist/icons-workflow/src/elements/IconDeleteOutline.js';
import { SWCLoader } from '../utils/SWCLoader';
import createWrapper from '../utils/createWrapper';
import { getSWCProps } from './utils';
import type { RS2IconProps } from './utils';
import interopRequireDefault from '../utils/interopRequireDefault';


/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2DeleteOutline: React.ComponentType<unknown> = process.env.INCLUDE_RS2
    ? interopRequireDefault(require('react-spectrum/Icon/DeleteOutline')).default
    : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

let swcLoader;
let s2swcLoader;

if (!process.env.EXCLUDE_SWC) {

    swcLoader = new SWCLoader(['sp-icon-delete-outline'], async () => {
        
        const { IconDeleteOutline } = await import(
            /* webpackChunkName: "SpIconDeleteOutline" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/icons-workflow/src/elements/IconDeleteOutline'
        );
        return [IconDeleteOutline];
    });

    s2swcLoader = new SWCLoader(['sp-icon-delete'], async () => {
        const { IconDelete } = await import(
            /* webpackChunkName: "SpIconIconDelete" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/icons-workflow/src/elements/IconDelete'
        );
        return [IconDelete];
    });
}


        
        const S1Icon = createWrapper<IconDeleteOutline, RS2IconProps>({
            displayName: 'DeleteOutline',
            fallback: RS2DeleteOutline,
            swcLoader,
            swcProps: getSWCProps,
            tagName: 'sp-icon-delete-outline',
        });
    
        const S2Icon = createWrapper<IconDeleteOutline, RS2IconProps>({
            displayName: 'DeleteOutline',
            fallback: RS2DeleteOutline,
            swcLoader: s2swcLoader,
            swcProps: getSWCProps,
            tagName: 'sp-icon-delete',
        });

        export default (props: React.ComponentProps<typeof S1Icon> & RS2IconProps) => {
            const { spectrumTheme } = useContext(ThemeContext);
            if (spectrumTheme === 'spectrum-two') {
                return <S2Icon {...props} />;
            }
            return <S1Icon {...props} />;
        };
    
/* eslint-enable prettier/prettier */
