import { VERSION } from "@dunamis-sdk/version";
import * as constants from "@dunamis-common/constants";
import { DateTime } from "@dunamis-core/utils/datetime";
import { SysInfo } from "@dunamis-core-sysinfo";
export function getConstantDerivedData() {
    const derivedData = {};
    try {
        derivedData[constants.key_data_entity_datasdk] = {
            [constants.key_datasdk_entity_version]: VERSION,
        };
        const deviceId = SysInfo.getDeviceId();
        if (deviceId) {
            derivedData[constants.key_data_event_device_guid] = deviceId;
        }
        const deviceModel = SysInfo.getDeviceModel();
        if (deviceModel) {
            derivedData[constants.key_data_source_device] = deviceModel;
        }
        const platformInfo = SysInfo.getPlatformInfo();
        if (platformInfo) {
            derivedData[constants.key_data_source_platform] = platformInfo;
        }
        const osVersion = SysInfo.getOSVersion();
        if (osVersion) {
            derivedData[constants.key_data_source_os_version] = osVersion;
        }
        return derivedData;
    }
    catch (error) {
        return {};
    }
}
export function getTransientDerivedData() {
    const transientDerivedData = {};
    try {
        const connectionType = SysInfo.getConnectionType();
        if (connectionType) {
            transientDerivedData[constants.key_data_event_connection] = connectionType;
        }
        const locale = SysInfo.getLocale();
        if (locale) {
            transientDerivedData[constants.key_data_event_language] = locale;
        }
        const isOffline = SysInfo.isOffline();
        if (isOffline) {
            transientDerivedData[constants.key_data_event_offline] = isOffline;
        }
        return transientDerivedData;
    }
    catch (error) {
        return {};
    }
}
export function getDeviceEntity() {
    const deviceEntity = {};
    try {
        const cpuSummary = SysInfo.getCPUSummary();
        if (cpuSummary) {
            deviceEntity[constants.key_device_entity_cpu_processor] = cpuSummary;
        }
        const cpuNumCores = SysInfo.getCPUCoreCount();
        if (cpuNumCores) {
            deviceEntity[constants.key_device_entity_cpu_num_cores] = cpuNumCores;
        }
        const cpuSpeed = SysInfo.getCPUSpeed();
        if (cpuSpeed) {
            deviceEntity[constants.key_device_entity_cpu_speed] = cpuSpeed;
        }
        const deviceId = SysInfo.getDeviceId();
        if (deviceId) {
            deviceEntity[constants.key_device_entity_device_guid] = deviceId;
        }
        const resolution = SysInfo.getScreenResolution();
        if (resolution) {
            deviceEntity[constants.key_device_entity_device_resolution] = resolution;
        }
        const hddSize = SysInfo.getDiskSize();
        if (hddSize) {
            deviceEntity[constants.key_device_entity_hdd_size] = hddSize;
        }
        const nicAddress = SysInfo.getPrimaryMACAddress();
        if (nicAddress) {
            deviceEntity[constants.key_device_entity_nic_guid] = nicAddress;
        }
        const ramSize = SysInfo.getRAMSize();
        if (ramSize) {
            deviceEntity[constants.key_device_entity_ram_size] = ramSize;
        }
        const penTouchSupport = SysInfo.getPenTouchSupport();
        if (penTouchSupport) {
            deviceEntity[constants.key_device_entity_pen_touch] = penTouchSupport;
        }
        return deviceEntity;
    }
    catch (error) {
        return {};
    }
}
export function getEnvEntity() {
    const envEntity = {};
    try {
        const connectionType = SysInfo.getConnectionType();
        if (connectionType) {
            envEntity[constants.key_env_entity_connection_type] = connectionType;
        }
        const eventTime = DateTime.format(new Date());
        if (eventTime) {
            envEntity[constants.key_env_entity_dts_end] = eventTime;
        }
        const locale = SysInfo.getLocale();
        if (locale) {
            envEntity[constants.key_env_entity_language] = locale;
        }
        const isOffline = SysInfo.isOffline();
        if (isOffline) {
            envEntity[constants.key_env_entity_offline] = isOffline;
        }
        return envEntity;
    }
    catch (error) {
        return {};
    }
}
