import type { ForwardedRef, MutableRefObject } from 'react';
import React, { forwardRef, useEffect, useRef } from 'react';

// https://opensource.adobe.com/spectrum-web-components/components/menu/
// https://git.corp.adobe.com/torq/react-spectrum/tree/develop/src/Menu
import type {
    MenuDivider as MenuDividerType,
    MenuGroup as MenuGroupType,
    MenuItem as MenuItemType,
    Menu as MenuType,
} from '@ccx-public/spectrum-web-component-fallbacks/dist/menu';
import type { ReactProps } from './utils';
import { filterBooleanProps, useComponent } from './utils';

import Popover from './Popover';
import { SWCLoader } from './utils/SWCLoader';
import createWrapper from './utils/createWrapper';
import interopRequireDefault from './utils/interopRequireDefault';
import mergeRefs from './utils/mergeRefs';

type RS2MenuCompatProps = {
    open?: boolean;
    onSelect?: (option: string) => void;
    onClose?: () => unknown;
};

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires */
const RS2Menu: {
    Menu: React.ComponentType<ReactProps<MenuType, RS2MenuCompatProps>>;
    MenuHeading: React.ComponentType<unknown>;
    SubMenu: React.ComponentType<unknown>;
    MenuDivider: React.ComponentType<unknown>;
    MenuItem: React.ComponentType<unknown>;
} = process.env.INCLUDE_RS2
    ? interopRequireDefault(require('react-spectrum/Menu'))
    : {};

/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires */

let swcLoader;
if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(
        ['sp-menu', 'sp-menu-group', 'sp-menu-item', 'sp-menu-divider'],
        async () => {
            const { Menu, MenuGroup, MenuItem, MenuDivider } = await import(
                /* webpackChunkName: "SpMenu" */
                '@ccx-public/spectrum-web-component-fallbacks/dist/menu'
            );
            return [Menu, MenuGroup, MenuItem, MenuDivider];
        }
    );
}

// SWC menus can reside outside of a popover, but RS2 Menus are always inside a popover.
// This is only so we can reuse a menu outside of the popover.
export const StandAloneMenu = createWrapper<MenuType>({
    displayName: 'StandAloneMenu',
    fallback: undefined,
    swcLoader,
    SWCWrapper: forwardRef(function SpStandAloneMenuPreview(
        props: ReactProps<MenuType, RS2MenuCompatProps>,
        ref: ForwardedRef<HTMLElement>
    ) {
        const privateRef = useRef<MenuType>(null);
        const menuWrapperRef = ref
            ? (ref as MutableRefObject<HTMLElement>)
            : privateRef;
        const { className, onSelect, ...rest } = props;
        useEffect(() => {
            const { current } = menuWrapperRef;
            const handleSelect = (event: Event) => {
                const target = event.target as HTMLInputElement;

                onSelect?.(target.value);
            };

            if (current && onSelect) {
                current.addEventListener('change', handleSelect);
            }

            return () => {
                if (current && onSelect) {
                    current.removeEventListener('change', handleSelect);
                }
            };
        }, [onSelect, menuWrapperRef]);

        const Menu = useComponent('sp-menu');

        return <Menu ref={menuWrapperRef} class={className} {...rest} />;
    }),
    tagName: 'sp-menu',
});

export const Menu = createWrapper<MenuType, RS2MenuCompatProps>({
    displayName: 'Menu',
    fallback: RS2Menu.Menu,
    swcLoader,
    SWCWrapper: forwardRef(function SpMenuPreview(
        props,
        ref: ForwardedRef<HTMLElement>
    ) {
        const privateRef = useRef<MenuType>(null);
        const menuWrapperRef = ref
            ? (ref as MutableRefObject<HTMLElement>)
            : privateRef;
        const { open, slot, style, onClose, ...rest } = props;

        useEffect(() => {
            const { current } = menuWrapperRef;

            if (current && onClose) {
                current.addEventListener('close', onClose);
            }

            return () => {
                if (current && onClose) {
                    current.removeEventListener('close', onClose);
                }
            };
        }, [onClose, menuWrapperRef]);

        return (
            <Popover
                open={open as boolean}
                title={''}
                style={{ minWidth: 'min-content', padding: 0, ...style }}
                slot={slot}
                excludeDialog
            >
                <StandAloneMenu ref={menuWrapperRef} {...rest} />
            </Popover>
        );
    }),
    tagName: 'sp-menu',
});

type RS2MenuItemCompatProps = {
    description?: JSX.Element | string;
    icon?: JSX.Element;
    role?: string;
    valueContent?: JSX.Element;
};

function getIconSlot(icon?: RS2MenuItemCompatProps['icon']): React.ReactNode {
    if (!icon) {
        return;
    }

    return React.cloneElement(icon, { slot: 'icon' });
}

function getValueSlot(
    value?: RS2MenuItemCompatProps['valueContent']
): React.ReactNode {
    if (!value) {
        return;
    }

    return React.cloneElement(value, { slot: 'value' });
}

export const MenuItem = createWrapper<MenuItemType, RS2MenuItemCompatProps>({
    displayName: 'MenuItem',
    fallback: RS2Menu.MenuItem,
    swcLoader,
    swcProps: function (props) {
        const {
            children,
            description,
            disabled,
            icon,
            selected,
            valueContent,
            className,
            ...rest
        } = props;

        // ReactSpectrum2                   | SpectrumWebComponent
        // ---------------------------------------------
        // N/A (if Select, use renderItem)  | description
        // N/A (if Select, use renderItem)  | valueContent

        const iconSlot = getIconSlot(icon);
        const valueSlot = getValueSlot(valueContent);

        return {
            class: className,
            ...rest,
            ...filterBooleanProps({
                disabled: disabled,
                selected: selected,
            }),
            children: (
                <>
                    {iconSlot}
                    {children}
                    {description && (
                        <span slot="description">{description}</span>
                    )}
                    {valueSlot}
                </>
            ),
        };
    },
    tagName: 'sp-menu-item',
});

export const MenuDivider = createWrapper<MenuDividerType>({
    displayName: 'MenuDivider',
    fallback: RS2Menu.MenuDivider,
    swcLoader,
    swcProps: function (props) {
        const { className, ...rest } = props;
        return { class: className, ...rest };
    },
    tagName: 'sp-menu-divider',
});

export const MenuHeading = createWrapper<MenuGroupType>({
    displayName: 'MenuHeading',
    fallback: RS2Menu.MenuHeading,
    swcLoader,
    swcProps: function (props) {
        const { children, ...rest } = props;

        // For swc, preferable to use the header prop of MenuGroup not MenuHeading.
        return {
            ...rest,
            children: <span slot="header">{children}</span>,
        };
    },
    tagName: 'sp-menu-group',
});

export const SubMenu = createWrapper<MenuItemType, RS2MenuItemCompatProps>({
    displayName: 'SubMenu',
    fallback: RS2Menu.SubMenu,
    swcLoader,
    SWCWrapper: function (props) {
        const { label, children, ...rest } = props;
        const Menu = useComponent('sp-menu');
        const MenuItem = useComponent('sp-menu-item');

        return (
            <MenuItem {...rest}>
                {label}
                <Menu slot="submenu">{children}</Menu>
            </MenuItem>
        );
    },
    tagName: 'sp-menu-item',
});

type MenuGroupReactCompatProps = {
    // Will get transformed into a header slot for SWC.
    header?: string;
    onSelect?: (option: string) => unknown;
};

/**
 * MenuGroup component is only supported by Spectrum Web Components
 */
export const MenuGroup = createWrapper<
    MenuGroupType,
    MenuGroupReactCompatProps
>({
    displayName: 'MenuGroup',
    fallback: undefined,
    swcLoader,
    SWCWrapper: forwardRef(function SpMenuGroupPreview(
        props: ReactProps<MenuGroupType, MenuGroupReactCompatProps>,
        ref: ForwardedRef<HTMLElement>
    ) {
        const menuGroupWrapperRef = useRef<MenuGroupType>(null);
        const { className, children, header, onSelect, ...rest } = props;

        useEffect(() => {
            const { current } = menuGroupWrapperRef;
            const handleChange = (event: Event) => {
                const target = event.target as HTMLInputElement;

                onSelect?.(target.value);
            };

            if (current && onSelect) {
                current.addEventListener('change', handleChange);
            }

            return () => {
                if (current && onSelect) {
                    current.removeEventListener('change', handleChange);
                }
            };
        }, [onSelect, menuGroupWrapperRef]);

        const MenuGroup = useComponent('sp-menu-group');

        return (
            <MenuGroup
                ref={mergeRefs([ref, menuGroupWrapperRef])}
                class={className}
                {...rest}
            >
                {header && <span slot="header">{header}</span>}
                {children}
            </MenuGroup>
        );
    }),
    tagName: 'sp-menu-group',
});

export const menuSwcLoader = swcLoader;
