import React, { useEffect, useRef } from 'react';
import type { Toast as ToastType } from '@ccx-public/spectrum-web-component-fallbacks/dist/toast';
import createWrapper from './utils/createWrapper';
import { SWCLoader } from './utils/SWCLoader';
import type { ReactProps } from './utils';
import { filterBooleanProps, useComponent } from './utils';
import interopRequireDefault from './utils/interopRequireDefault';
import Button from './Button';

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2Toast: React.ComponentType<ReactProps<ToastType, RS2CompatProps>> =
    process.env.INCLUDE_RS2
        ? interopRequireDefault(require('react-spectrum/Toast')).Toast
        : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

let swcLoader;
if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(['sp-toast'], async () => {
        const { Toast } = await import(
            /* webpackChunkName: "SpToast" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/toast'
        );
        return [Toast];
    });
}

// https://opensource.adobe.com/spectrum-web-components/components/toast/
// https://git.corp.adobe.com/torq/react-spectrum/tree/develop/src/Toast
// https://git.corp.adobe.com/React/react-spectrum-v2/blob/master/src/Toast/js/Toast.js
type RS2CompatProps = {
    /**
     * Variant of Toast: Success, Error, Warning, Info
     */
    variant?: 'error' | 'warning' | 'info' | 'success';
    /**
     * actionLabel of Toast: Button inside a toast
     */
    actionLabel?: string;
    /**
     * closeOnAction: Close the toast after clicking on button
     */
    closeOnAction?: boolean;
    /**
     * onAction: click on button of toast
     */
    onAction?: () => void;
    /**
     * onClose: click on close of toast
     */
    onClose: () => void;
    /**
     * Whether to show close button on toast.
     */
    closable?: boolean;
};

export const Toast = createWrapper<ToastType, RS2CompatProps>({
    displayName: 'Toast',
    fallback: RS2Toast,
    swcLoader,
    SWCWrapper: function SpToast(props) {
        const toastContainer = useRef<ToastType>(null);

        const {
            variant,
            className,
            actionLabel,
            children,
            closeOnAction,
            onAction,
            onClose,
            // eslint-disable-next-line @typescript-eslint/no-unused-vars
            closable,
            open = true,
            ...rest
        } = props;

        useEffect(() => {
            const current = toastContainer?.current;

            if (current && onClose) {
                current.addEventListener('close', onClose);
            }

            return () =>
                current && onClose
                    ? current.removeEventListener('close', onClose)
                    : undefined;
        });

        // ReactSpectrum2        | SpectrumWebComponent
        // ---------------------------------------------
        // closable               | N/A (always closable)
        // actionable             | added button component separately
        // closeOnAction          | added button component separately
        // Variant:error          | Variant:negative
        // Variant:warning        | N/A
        // Variant:info           | Variant:info
        // Variant:success        | Variant:positive

        //In SWC on close action they just disable the open attributes

        const swcVariant =
            variant === 'success'
                ? ('positive' as const)
                : variant === 'error'
                ? ('negative' as const)
                : variant;

        const Toast = useComponent('sp-toast');
        return (
            <Toast
                {...rest}
                {...filterBooleanProps({ open })}
                class={className}
                ref={toastContainer}
                variant={swcVariant}
            >
                {children}
                {actionLabel && (
                    <Button
                        slot="action"
                        variant="overBackground"
                        onClick={() => {
                            onAction?.();
                            if (closeOnAction) {
                                toastContainer.current?.close();
                            }
                        }}
                    >
                        {actionLabel}
                    </Button>
                )}
            </Toast>
        );
    },
    tagName: 'sp-toast',
});
