import { bearer, header_authorization, path_ims_profile } from "@dunamis-common/constants";
import { Request } from "@dunamis-core/http/request";
import { Method } from "@dunamis-core/http/types";
import { appendPathToURL } from "@dunamis-core/utils/url";
export class ImsAPI {
    constructor(endpoint) {
        this.endpoint_ = endpoint;
    }
    profile(accessToken) {
        let fetchUrl = this.endpoint_;
        fetchUrl = appendPathToURL(fetchUrl, path_ims_profile);
        return new Request(fetchUrl, Method.Get).addHeader(header_authorization, bearer + accessToken);
    }
}
