import { AssetBrowser } from "@ccx-public/component-types";
import { PickerMode } from "@csc/common";
const isViewEnabledForSave = (navigationDetail)=>{
    if (!navigationDetail) return true;
    const { name } = navigationDetail;
    switch(name){
        case AssetBrowser.ContentViewType.Projects:
            return false;
        default:
            return true;
    }
};
const isViewEnabledForFrameIO = (tabId, navigationDetail)=>{
    if ('frameio' !== tabId) return true;
    const espParams = navigationDetail?.params?.esp ?? {};
    const parentCollectionKind = espParams?.parentCollectionKind ?? '';
    const validFrameIOParentKinds = [
        'PROJECT',
        'FOLDER'
    ];
    return validFrameIOParentKinds.includes(parentCollectionKind);
};
const defaultIsViewEnabled = (mode, tabId, navigationDetail)=>{
    switch(mode){
        case PickerMode.saveToFolder:
        case PickerMode.saveAs:
        case PickerMode.saveAsCopy:
            return isViewEnabledForSave(navigationDetail);
        case PickerMode["export"]:
            switch(tabId){
                case 'frameio':
                    return isViewEnabledForFrameIO(tabId, navigationDetail);
                default:
                    return true;
            }
        default:
            return true;
    }
};
export { defaultIsViewEnabled, isViewEnabledForFrameIO };
