import type { internal_RootSDK as IRootSDK } from '@ccx-public/component-types';

// Minimal local shims to avoid runtime dependency on @opentelemetry/instrumentation
type InstrumentationConfig = { enabled?: boolean };
class InstrumentationBase<TConfig extends InstrumentationConfig = InstrumentationConfig> {
    public readonly instrumentationName: string;
    public readonly instrumentationVersion: string;
    protected _config: TConfig;

    constructor(name: string, version = '1.0.0', config = {} as TConfig) {
        this.instrumentationName = name;
        this.instrumentationVersion = version;
        this._config = config;
    }

    // Consumers expect these lifecycle hooks to exist on instrumentations
    public enable(): void {}
    public disable(): void {}
}

// Define our own minimal span type with only the properties we actually use
type PartialReadableSpan = { name: string };

interface LoadingInstrumentationConfig extends InstrumentationConfig {
    selectors?: string[];
    loadingActualSpanIdleTimeoutMs?: number;
    /**
     * When false, do not emit User Timing marks/measures. Internal tracking still occurs.
     */
    emitMeasures?: boolean;
    /**
     * Limit the number of per-element measures created. Remaining elements are
     * grouped into a single aggregated measure to avoid span explosion.
     */
    perElementMeasureLimit?: number;
    /**
     * When true, keep per-element performance marks in place to aid debugging
     * in DevTools. By default, marks are cleared after measuring to bound
     * the performance entry buffer.
     */
    retainElementMarks?: boolean;
}

/**
 * Feature: Track user-visible loading durations and per-element timings
 *
 * Background:
 *   Given performance measurement is enabled in the SDK configuration
 *   And the runtime is a browser with MutationObserver and IntersectionObserver available
 *   And a combined selector list identifies loading indicators (e.g., "loading", "spinner", "progress")
 *
 * OTel Compatibility:
 *   This class follows the Instrumentation interface shape for future compatibility
 *   while maintaining a lightweight window.performance-based implementation under the hood.
 *   No external OTel runtime dependencies are required; the public surface is instrumentation-shaped.
 *
 * Preferred Loading State Marking:
 *   Use data-loading-indicator="true" for critical loading indicators (list views, asset thumbnails, etc.)
 *   This is the most robust approach as it won't get minified or refactored out.
 *   Only apply to elements where loading performance truly matters for user experience.
 *
 * Fallback Detection:
 *   CSS classes, test IDs, and ARIA attributes are detected as fallbacks
 *   but may be less reliable due to refactoring and minification.
 *
 * Authoritative idle timeout:
 *   After `loadingActualSpanIdleTimeoutMs` of inactivity, finalize regardless of any
 *   remaining started/visible elements or selector matches; in-flight elements are
 *   finalized at the same end time.
 *
 * Definitions:
 *   - "selector label": a concise string used in measure names, derived from tag, id, key classes,
 *     and attributes like role or data-testid, bounded for readability in DevTools.
 *   - "UI component": an element inside a Shadow DOM.
 *   - "loading-element-<count> [selector label]": per-element measure for loading indicators in the light DOM. Starts when an element first becomes visible in the viewport and ends when it leaves the viewport, stops matching selectors, or becomes non-visible. Each visibility cycle produces a new measure with a new sequential <count>.
 *   - "loading-ui-component-<count> [selector label]": per-element measure for loading indicators inside Shadow DOMs. Same semantics as "loading-element", attributed to UI components and contributes to the UI components aggregate.
 *   - "loading-actual": global measure spanning from the first loading indicator (element or UI component) start to the last recorded loading activity within the aggregation window. Emitted once per navigation.
 *   - "loading-ui-components": aggregate measure spanning from the first UI component start to the last UI component end.
 *   - "loading-host": host/light DOM duration from transaction (navigation) start to "loading-actual-start".
 *   - "loading-total": total duration from transaction (navigation) start to "loading-actual-end" (i.e., when the last indicator finalizes/hides).
 *   - "loading-elements [selector label] (grouped N)": grouped overflow measure emitted when the per-element limit is exceeded. One measure per selector label, spanning the minimum start to maximum end across grouped elements, with N as the count of grouped elements.
 *
 * Rule: Aggregation lifecycle
 *
 * Scenario: Start aggregation on first visible indicator
 *   Given no active loading aggregation
 *   When a matching loading indicator becomes visible in the viewport
 *   Then a start mark for that element is recorded and a unique sequential count is assigned
 *   And a global mark "loading-actual-start" is recorded at the same timestamp
 *   And the idle finalize timer is scheduled using the configured timeout
 *
 * Scenario: Measure a visible loading indicator
 *   Given an element has a start mark and later stops intersecting
 *   When the element is finalized
 *   Then an end mark is recorded
 *   And a performance measure named "loading-element-<count> [selector label]" exists
 *   And the per-element measure name includes the selector label when available
 *   And element-specific marks are cleared unless retainElementMarks is true
 *
 * Scenario: Measure repeated visibility cycles before idle timeout
 *   Given an element alternates between being visible and hidden within the aggregation window
 *   When it exits the viewport and later becomes visible again before the idle timeout fires
 *   Then each visibility cycle produces a new per-element measure with a new sequential id
 *   And the element remains enrolled for subsequent visibility cycles
 *   And the idle finalize timer is rescheduled on each cycle
 *
 * Scenario: Finalize after idle timeout
 *   Given loading aggregation has started
 *   And no element activity occurs for loadingActualSpanIdleTimeoutMs
 *   When the idle timer fires
 *   Then a mark "loading-actual-end" is recorded at the last activity time
 *   And measures "loading-actual" (actual start to actual end) and "loading-total" (total start to actual end) exist
 *   And measure "loading-host" (host/light DOM from navigation start to loading-actual-start) exists
 *   And measure "loading-ui-components" (0ms if no UI components displayed a loading state, or first UI component start to last UI component end) exists
 *   And any grouped overflow measure is emitted
 *   And currently tracked elements are finalized at the same end time
 *   And all observer Maps (activeObservers, rootIntersectionObservers, rootObservedElements, observedElements) are cleared
 *   And all IntersectionObserver and MutationObserver instances are disconnected
 *   And references to Elements and ShadowRoots are released to allow garbage collection
 *
 * Scenario: Emit global measures once per navigation
 *   Given a navigation has started and global start marks exist
 *   And a first loading window has finalized and emitted global measures
 *   When a new loading window starts without a navigation
 *   Then global measures ("loading-actual", "loading-total", "loading-host") are not re-emitted
 *
 * Rule: Overflow aggregation
 *
 * Scenario: Cap per-element measures and group overflow by selector label
 *   Given the perElementMeasureLimit is N
 *   And more than N loading elements finalize within the aggregation window
 *   When the (N+1)th or later element finalizes
 *   Then grouped overflow includes that timing keyed by its selector label with min start, max end, and count
 *   And after aggregation finalizes, one grouped measure is emitted per selector label with suffix "(grouped N)"
 *
 * Rule: DOM mutations and attributes
 *
 * Scenario: Track indicators added and removed via DOM mutations
 *   Given a MutationObserver is installed for each root (document or shadow root)
 *   When nodes matching the selectors are added
 *   Then a coalesced scan enrolls them for visibility tracking via IntersectionObserver
 *   When tracked nodes are removed (including descendants and shadow subtrees)
 *   Then those elements are finalized and detached
 *
 * Scenario: React to attribute changes affecting matching and visibility
 *   Given an element is observed for mutations
 *   When its attributes among {class, aria-hidden, aria-busy, role, data-testid, data-loading-indicator, style} change
 *   And it now matches the selectors
 *   Then it is enrolled for visibility tracking
 *   And if it was previously enrolled but never became visible and now stops matching
 *   Then a synthetic instantaneous start and end are recorded for the element only
 *   And the element is finalized
 *   And global aggregation is NOT started (synthetic instantaneous elements never became visible)
 *   And if a started element stops matching the selectors (e.g., loader class removed, aria-busy="false")
 *   Then the element is finalized immediately without waiting for intersection exit
 *   And if a started element becomes non-visible (hidden, aria-hidden, style display:none or visibility hidden/collapse)
 *   Then the element is finalized immediately without waiting for intersection exit
 *
 * Scenario: Observe data-loading-indicator and style changes
 *   Given a loading indicator toggles via data-loading-indicator or inline style
 *   When the attribute changes
 *   Then the observer enrolls or finalizes as appropriate
 *
 * Rule: Shadow DOM
 *
 * Scenario: Track loading indicators inside Shadow DOMs
 *   Given an element with a shadow root is added to the DOM
 *   When the document MutationObserver triggers a scan
 *   Then the TreeWalker discovers the shadow root via node.shadowRoot
 *   And observes that root for mutations
 *   And detects loading indicators inside it
 *   And creates per-element measures with prefix "loading-ui-component-<id>"
 *   And emits an aggregate measure "loading-ui-components" spanning all UI component timings
 *
 * Rule: Navigation reset
 *
 * Scenario: Reset on SPA navigations
 *   Given a SPA navigation occurs (history, popstate, or hashchange)
 *   When a navigation event is observed
 *   Then the current aggregation is finalized if active
 *   And all observers and tracked elements are detached for the old route
 *   And new marks "loading-total-start" and "loading-host-start" are recorded for the new route
 *   And previously created measures with the "aup-sdk:" prefix are cleared
 *   And the document is (re)observed for mutations
 *   And the document is scanned immediately and on the next animation frame to enroll new indicators
 *
 * Scenario: Do not restart within same navigation
 *   Given aggregation was finalized due to idle timeout
 *   When loading indicators appear again without a navigation
 *   Then no new per-element or grouped measures are recorded
 *   And aggregation does not restart until a navigation reset occurs
 *   And `recordingEnabled` is set to false until navigation reset
 *
 * Scenario: Coalesce back-to-back navigation signals
 *   Given navigation signals (e.g., hashchange, history.pushState/replaceState) can arrive back-to-back
 *   And a delayed pushState may occur after initial route activation (e.g., redirect following an async fetch, hidden history state)
 *   When multiple navigation signals are observed within a 300ms coalescing window
 *   Then only one navigation reset is performed for that window
 *   And if no loading indicators appear after the reset, emit one set of global measures ("loading-actual", "loading-total", "loading-host", "loading-ui-components") via the idle finalize path
 *
 * Rule: Initialization and environment
 *
 * Scenario: Teardown
 *   Given the tracker is running
 *   When teardown is invoked
 *   Then idle timers are cleared and all observers (intersection/mutation/navigation and shadow-root observation) are removed
 *   And no further marks or measures are created
 *
 * Scenario: Exit gracefully when required APIs are unavailable
 *   Given the environment lacks window/document or required observer APIs
 *   When the tracker is constructed
 *   Then it exits early without throwing (logs a warning only when window/document is missing)
 *
 * Scenario: Record initial navigation start marks
 *   Given the tracker is constructed on first page load
 *   When initialization completes
 *   Then marks "loading-total-start" and "loading-host-start" are recorded at navigation start
 *
 * Scenario: Allocate element IDs and reset on navigation
 *   Given element IDs are human-friendly and contiguous
 *   When timing starts for an element (first intersection)
 *   Then a new sequential ID is allocated without gaps
 *   And on navigation reset the ID counter is reset so the next element starts at 1
 *
 * Notes:
 * - Performance API calls are used conservatively; marks/measures are prefixed and cleared where applicable.
 * - Emission of marks/measures can be disabled via `emitMeasures` while retaining internal timing.
 * - When marks are recreated via `ensureMark`, a debug counter (`recreatedMarksCount`) is incremented and logged at debug level.
 * - Selector labels are concise and bounded for readability in DevTools.
 * - Scans are coalesced to limit thrash during bursty updates; work is deferred to the next animation frame.
 */
export class LoadingInstrumentation extends InstrumentationBase<LoadingInstrumentationConfig> {
    private static readonly SPAN_PREFIX = 'aup-sdk:';
    private static readonly MIN_FRAME_DURATION_MS = 16;

    private readonly sdk!: IRootSDK;
    private readonly loadingActualSpanIdleTimeoutMs!: number;
    private readonly selector!: string;
    private readonly perElementMeasureLimit!: number;
    private readonly retainElementMarks!: boolean;
    private readonly emitMeasures!: boolean;
    private elementIdCounter = 0;

    private getNextElementId(): number {
        return ++this.elementIdCounter;
    }

    private observedElements = new Map<
        Element,
        {
            started: boolean;
            root: Document | ShadowRoot;
            insideShadow?: boolean;
            span?: PartialReadableSpan;
            selectorLabel?: string;
            id?: number;
            startTime?: number;
        }
    >();
    private activeObservers = new Map<Document | ShadowRoot, MutationObserver>();
    private rootIntersectionObservers = new Map<Document | ShadowRoot, IntersectionObserver>();
    private rootObservedElements = new Map<Document | ShadowRoot, Set<Element>>();
    private scheduledScanRoots = new Set<Document | ShadowRoot>();

    private loadingAggregationStarted = false;
    private loadingAggregationTimeout: ReturnType<typeof setTimeout> | null = null;
    private lastActivityTime = 0;
    private perElementMeasuresCreated = 0;
    private firstUiComponentStartTime = 0;
    private lastUiComponentEndTime = 0;
    private groupedOverflow = new Map<
        string,
        {
            minId: number;
            maxId: number;
            minStart: number;
            maxEnd: number;
            count: number;
        }
    >();
    private firstIndividualSelectorLabel: string | null = null;
    private hasEmittedGlobalMeasures: boolean = false;
    private recordingEnabled: boolean = true;
    private logTimeOriginMs: number = 0;
    private recreatedMarksCount: number = 0;
    private navigationDebounceHandle: ReturnType<typeof setTimeout> | null = null;
    private navigationDebounceWindowMs: number = 300;
    private lastNavigationHref: string | null = null;

    private origPushState?: typeof history.pushState;
    private origReplaceState?: typeof history.replaceState;
    private disposed = false;

    constructor(sdk: IRootSDK, options: LoadingInstrumentationConfig = {}) {
        super('loading-performance-instrumentation', '1.0.0', options);
        this.sdk = sdk;

        if (typeof window === 'undefined' || typeof document === 'undefined') {
            sdk.getConfig().logger?.warn('LoadingPerformanceTracker: Only available in browser');

            return;
        }

        if (
            typeof MutationObserver === 'undefined' ||
            typeof IntersectionObserver === 'undefined'
        ) {
            return;
        }

        const {
            selectors = [
                '[data-loading-indicator="true"]',
                '[class*="loading"]',
                '[class*="loader"]',
                '[class*="skeleton"]',
                '[class*="shimmer"]',
                '[class*="placeholder"]',
                '[class*="spinner"]',
                '[class*="progress"]',
                '[data-testid*="loading"]',
                '[data-testid*="loader"]',
                '[data-testid*="skeleton"]',
                '[data-testid*="shimmer"]',
                '[data-testid*="placeholder"]',
                '[data-testid*="spinner"]',
                '[data-testid*="progress"]',
                '[role="progressbar"]',
                '[aria-busy="true"]',
            ],
            loadingActualSpanIdleTimeoutMs = 2000,
            perElementMeasureLimit = 3,
            emitMeasures = true,
            retainElementMarks = false,
        } = options;

        this.selector = selectors.join(',');
        this.loadingActualSpanIdleTimeoutMs = loadingActualSpanIdleTimeoutMs;
        this.perElementMeasureLimit = perElementMeasureLimit;
        this.retainElementMarks = retainElementMarks;
        this.emitMeasures = emitMeasures;

        this.installNavigationListeners();
        this.logTimeOriginMs = 0;
        this.markLoadingTotalStart(this.logTimeOriginMs);
        this.markLoadingHostStart(this.logTimeOriginMs);
        this.scanAndTrack(document);
        this.observeMutations(document);
        this.log('LoadingInstrumentation initialized');
    }

    /**
     * Force finalize loading aggregation synchronously if it has started and the measure is missing.
     * This ensures the loading-total measure exists before Sentry reads performance measures.
     * Used to prevent race conditions where Sentry's idleTimeout fires before LoadingInstrumentation's timeout.
     */
    public finish(): void {
        if (
            this.loadingAggregationStarted &&
            !this.hasEmittedGlobalMeasures &&
            this.emitMeasures &&
            performance?.getEntriesByName
        ) {
            const loadingTotalMeasures = performance.getEntriesByName(
                'aup-sdk:loading-total',
                'measure',
            );
            // Only finalize if measure is missing (prevents race condition)
            if (!loadingTotalMeasures?.length) {
                this.finalizeLoadingAggregation();
            }
        }
    }

    /**
     * Manually trigger a navigation reset for environments where history events
     * are not available (e.g., UXP webviews). This should be called when
     * startUITransaction is invoked to ensure loading instrumentation tracks
     * the new navigation properly.
     *
     * @param immediate - When true (e.g. from startUITransaction), apply reset
     * immediately so loading-total and loading-host marks align with the
     * transaction start. When false, uses debouncing for history-based navigation.
     */
    public resetForNavigation(immediate = false): void {
        if (this.disposed) {
            return;
        }
        if (immediate) {
            if (this.navigationDebounceHandle) {
                clearTimeout(this.navigationDebounceHandle);
                this.navigationDebounceHandle = null;
            }
            this.lastNavigationHref = typeof location !== 'undefined' ? String(location.href) : '';
            this.resetLoadingAggregation();
        } else {
            this.scheduleNavigationReset();
        }
    }

    public disable(): void {
        this.dispose();
    }

    public dispose(): void {
        this.disposed = true;
        // Clear scheduled scans so pending RAF callbacks become no-ops
        this.scheduledScanRoots.clear();
        if (this.loadingAggregationTimeout) {
            clearTimeout(this.loadingAggregationTimeout);
            this.loadingAggregationTimeout = null;
        }
        if (this.navigationDebounceHandle) {
            clearTimeout(this.navigationDebounceHandle);
            this.navigationDebounceHandle = null;
        }
        this.unobserveAll(false);
        for (const intersectionObserver of this.rootIntersectionObservers.values()) {
            intersectionObserver.disconnect();
        }
        this.rootIntersectionObservers.clear();
        for (const mutationObserver of this.activeObservers.values()) {
            mutationObserver.disconnect();
        }
        this.activeObservers.clear();
        this.uninstallNavigationListeners();
    }

    private log = (message: string, ...rest: unknown[]): void => {
        const logger = this.sdk.getConfig?.()?.logger;
        const t = Math.round(performance.now() - this.logTimeOriginMs);
        logger?.info(`[LoadingInstrumentation t=${t}ms] ${message}`, ...rest);
    };

    private debug = (message: string, ...rest: unknown[]): void => {
        const logger = this.sdk.getConfig?.()?.logger;
        const t = Math.round(performance.now() - this.logTimeOriginMs);
        logger?.debug(`[LoadingInstrumentation t=${t}ms] ${message}`, ...rest);
    };

    private getRootForElement(el: Element): Document | ShadowRoot {
        const root = el.getRootNode() as any;
        if (root instanceof Document) {
            return root;
        }
        if (typeof ShadowRoot !== 'undefined' && root instanceof ShadowRoot) {
            return root;
        }
        if (root && root.host) {
            return root as unknown as ShadowRoot;
        }
        return document;
    }

    private isElementInsideShadow(el: Element): boolean {
        const rootNode = (el.getRootNode && el.getRootNode()) as any;
        if (typeof ShadowRoot !== 'undefined' && rootNode instanceof ShadowRoot) {
            return true;
        }
        return !!rootNode?.host;
    }

    private getIntersectionObserverForRoot(root: Document | ShadowRoot): IntersectionObserver {
        let intersectionObserver = this.rootIntersectionObservers.get(root);
        if (!intersectionObserver) {
            intersectionObserver = new IntersectionObserver(
                (entries) => {
                    if (!this.recordingEnabled) {
                        return;
                    }
                    for (const entry of entries) {
                        const target = entry.target;
                        const data = this.observedElements.get(target);
                        if (!data) {
                            continue;
                        }
                        if (entry.isIntersecting && !data.started) {
                            const elementId = this.getNextElementId();
                            const baseName = data.insideShadow
                                ? 'loading-ui-component'
                                : 'loading-element';

                            const span = this.createElementSpan(elementId.toString(), baseName);
                            data.span = span;
                            data.id = elementId;
                            data.selectorLabel = this.buildElementSelectorLabel(target);

                            const now = performance.now();
                            data.startTime = now;
                            data.started = true;
                            if (data.insideShadow) {
                                if (this.firstUiComponentStartTime === 0) {
                                    this.firstUiComponentStartTime = now;
                                } else {
                                    this.firstUiComponentStartTime = Math.min(
                                        this.firstUiComponentStartTime,
                                        now,
                                    );
                                }
                            }
                            this.log(
                                'Element became visible, starting loading aggregation',
                                target,
                            );
                            this.startLoadingAggregation(now);
                        } else if (!entry.isIntersecting && data.started) {
                            this.finalizeElement(target, { detach: false });
                        }
                    }
                },
                { threshold: 0 },
            );
            this.rootIntersectionObservers.set(root, intersectionObserver);
        }
        return intersectionObserver;
    }

    private finalizeElement(
        target: Element,
        options?: { endTime?: number; detach?: boolean },
    ): void {
        const data = this.observedElements.get(target);
        if (!data) {
            return;
        }
        if (!data.started || !data.span) {
            this.observedElements.delete(target);
            const set = this.rootObservedElements.get(data.root);
            if (set) {
                set.delete(target);
            }
            const intersectionObserver = this.rootIntersectionObservers.get(data.root);
            intersectionObserver?.unobserve(target);
            return;
        }
        const effectiveEndTime = options?.endTime ?? performance.now();

        if (data.insideShadow) {
            this.lastUiComponentEndTime = Math.max(this.lastUiComponentEndTime, effectiveEndTime);
        }

        const underLimit = this.perElementMeasuresCreated < this.perElementMeasureLimit;
        if (underLimit) {
            if (data.span && this.emitMeasures) {
                const startMark = data.span.name;
                const endMark = `${startMark}-end`;
                const startTimeForRecreate = data.startTime ?? effectiveEndTime;
                this.ensureMark(startMark, startTimeForRecreate);
                const adjustedEndTime = this.ensureMinimumDuration(
                    startTimeForRecreate,
                    effectiveEndTime,
                );
                performance.mark(endMark, { startTime: adjustedEndTime });
                const nameForMeasure = data.selectorLabel
                    ? `${startMark} ${data.selectorLabel}`
                    : startMark;
                performance.measure(nameForMeasure, startMark, endMark);
                if (!this.firstIndividualSelectorLabel && data.selectorLabel) {
                    this.firstIndividualSelectorLabel = data.selectorLabel;
                }
                if (!this.retainElementMarks && 'clearMarks' in performance) {
                    performance.clearMarks(startMark);
                    performance.clearMarks(endMark);
                }
            }
            this.perElementMeasuresCreated += 1;
        } else {
            const start = data.startTime || 0;
            const end = effectiveEndTime;
            const adjustedEnd = this.ensureMinimumDuration(start, end);
            const id = data.id || 0;
            const labelKey = data.selectorLabel ?? '(unknown)';
            const existing = this.groupedOverflow.get(labelKey);
            if (!existing) {
                this.groupedOverflow.set(labelKey, {
                    minId: id,
                    maxId: id,
                    minStart: start,
                    maxEnd: adjustedEnd,
                    count: 1,
                });
            } else {
                existing.minId = Math.min(existing.minId, id);
                existing.maxId = Math.max(existing.maxId, id);
                existing.minStart = Math.min(existing.minStart, start);
                existing.maxEnd = Math.max(existing.maxEnd, adjustedEnd);
                existing.count += 1;
            }
        }
        const shouldDetach = options?.detach !== undefined ? options.detach : true;
        if (shouldDetach) {
            this.observedElements.delete(target);
            const set = this.rootObservedElements.get(data.root);
            if (set) {
                set.delete(target);
            }
            const intersectionObserver = this.rootIntersectionObservers.get(data.root);
            intersectionObserver?.unobserve(target);
        } else {
            const existing = this.observedElements.get(target);
            if (existing) {
                existing.started = false;
                existing.span = undefined;
                existing.startTime = undefined;
                existing.id = undefined;
            }
        }
        this.recordLoadingActivity();
    }

    private buildElementSelectorLabel(el: Element): string {
        const parts: string[] = [];
        const tag = el.tagName ? el.tagName.toLowerCase() : '';
        if (tag) {
            parts.push(tag);
        }
        const id = (el as HTMLElement).id;
        if (id) {
            parts.push(`#${id}`);
        }
        const classList = (el as HTMLElement).classList;
        if (classList && classList.length) {
            const preferred = Array.from(classList).filter((c) =>
                /(loading|skeleton|spinner|progress|spectrum|icon)/i.test(c),
            );
            const classes = (preferred.length ? preferred : Array.from(classList)).slice(0, 3);
            if (classes.length) {
                parts.push(`.${classes.join('.')}`);
            }
        }
        const role = el.getAttribute('role');
        if (role) {
            parts.push(`[role="${role}"]`);
        }
        const testId = el.getAttribute('data-testid');
        if (testId) {
            parts.push(`[data-testid="${this.truncate(testId, 24)}"]`);
        }
        const elementTiming = el.getAttribute('elementtiming');
        if (elementTiming) {
            parts.push(`[elementtiming="${this.truncate(elementTiming, 24)}"]`);
        }
        const label = parts.join('');
        return label.length > 80 ? `${label.slice(0, 77)}...` : label;
    }

    private truncate(value: string, max: number): string {
        return value.length > max ? `${value.slice(0, max - 1)}…` : value;
    }

    private isElementActuallyVisible(el: HTMLElement): boolean {
        if (el.hidden || el.getAttribute('aria-hidden') === 'true') {
            return false;
        }
        const style = el.style;
        if (style) {
            const displayNone = style.display === 'none';
            const visibilityHidden =
                style.visibility === 'hidden' || style.visibility === 'collapse';
            if (displayNone || visibilityHidden) {
                return false;
            }
        }
        return true;
    }

    private unobserveAll(finalize: boolean, forcedEndTime?: number): void {
        for (const [root, set] of this.rootObservedElements.entries()) {
            const intersectionObserver = this.rootIntersectionObservers.get(root);

            if (!set) {
                continue;
            }
            for (const el of set.values()) {
                if (finalize) {
                    this.finalizeElement(el, { endTime: forcedEndTime });
                } else {
                    intersectionObserver?.unobserve(el);
                    this.observedElements.delete(el);
                }
            }
            set.clear();
        }
    }

    private startLoadingAggregation(
        startTime: number,
        options?: { skipScheduling?: boolean; activityTime?: number },
    ): void {
        if (!this.recordingEnabled) {
            return;
        }
        if (!this.loadingAggregationStarted) {
            this.createGlobalSpan('loading-actual-start', startTime);
            this.loadingAggregationStarted = true;
            this.log('loading-actual tracking started');
            if (!options?.skipScheduling) {
                this.scheduleIdleFinalize(options?.activityTime);
            } else if (options.activityTime !== undefined) {
                this.lastActivityTime = options.activityTime;
            }
        } else {
            this.log('startLoadingAggregation called but already started');
        }
    }

    private scheduleIdleFinalize(activityTime?: number): void {
        this.lastActivityTime = activityTime ?? performance.now();

        if (this.loadingAggregationTimeout) {
            clearTimeout(this.loadingAggregationTimeout);
        }

        this.loadingAggregationTimeout = setTimeout(() => {
            if (!this.loadingAggregationStarted) {
                this.log('Timeout reached with no loading indicators; emitting 0ms measures');
                // Start aggregation using navigation start time with matching activity time.
                // Skip scheduling a new timeout since we're already in a timeout callback and
                // will finalize immediately. This ensures all marks align to navigation start,
                // producing 0ms measures when no loading indicators appeared.
                this.startLoadingAggregation(this.logTimeOriginMs, {
                    skipScheduling: true,
                    activityTime: this.logTimeOriginMs,
                });
            } else {
                this.log('Idle timeout reached; finalizing loading-actual');
            }
            this.finalizeLoadingAggregation();
        }, this.loadingActualSpanIdleTimeoutMs);
    }

    private recordLoadingActivity(): void {
        if (this.loadingAggregationStarted) {
            this.lastActivityTime = performance.now();
            this.scheduleIdleFinalize();
        }
    }

    private finalizeLoadingAggregation(): void {
        if (this.loadingAggregationTimeout) {
            clearTimeout(this.loadingAggregationTimeout);
            this.loadingAggregationTimeout = null;
        }
        if (!this.loadingAggregationStarted) {
            this.log('finalizeLoadingAggregation skipped: not started');
            return;
        }
        const actualStartName = `${LoadingInstrumentation.SPAN_PREFIX}loading-actual-start`;
        const startEntries = performance.getEntriesByName?.(actualStartName) ?? [];
        const startEntry = startEntries[startEntries.length - 1];
        if (!startEntry && this.emitMeasures) {
            const fallbackStart = this.firstUiComponentStartTime || this.logTimeOriginMs;
            this.ensureMark(actualStartName, fallbackStart);
        }
        const startEntriesAfter = performance.getEntriesByName?.(actualStartName) ?? [];
        const startEntryEffective = startEntriesAfter[startEntriesAfter.length - 1];
        if (!startEntryEffective) {
            this.log('finalizeLoadingAggregation skipped: missing start mark');
            return;
        }
        const finalizeEndTime =
            this.lastActivityTime && this.lastActivityTime >= startEntryEffective.startTime
                ? this.lastActivityTime
                : this.ensureMinimumDuration(startEntryEffective.startTime, performance.now());

        if (!this.hasEmittedGlobalMeasures && this.emitMeasures) {
            // Calculate all required adjustments upfront to handle shared marks correctly
            const adjustedActualEndTime = this.ensureMinimumDuration(
                startEntryEffective.startTime,
                finalizeEndTime,
            );
            const adjustedTotalEndTime = this.ensureMinimumDuration(
                this.logTimeOriginMs,
                adjustedActualEndTime,
            );
            const adjustedHostEndTime = this.ensureMinimumDuration(
                this.logTimeOriginMs,
                startEntryEffective.startTime,
            );

            // Use the maximum adjustment for shared marks
            const finalActualStartTime = adjustedHostEndTime;
            // Ensure loading-actual measure has minimum duration
            const finalActualEndTime = Math.max(
                adjustedActualEndTime,
                adjustedTotalEndTime,
                finalActualStartTime + LoadingInstrumentation.MIN_FRAME_DURATION_MS,
            );

            // Update loading-actual-start if host measure requires adjustment
            if (finalActualStartTime !== startEntryEffective.startTime) {
                performance.mark(`${LoadingInstrumentation.SPAN_PREFIX}loading-actual-start`, {
                    startTime: finalActualStartTime,
                });
            }

            // Create loading-actual-end mark
            performance.mark(`${LoadingInstrumentation.SPAN_PREFIX}loading-actual-end`, {
                startTime: finalActualEndTime,
            });

            // Create all measures
            performance.measure(
                `${LoadingInstrumentation.SPAN_PREFIX}loading-actual`,
                `${LoadingInstrumentation.SPAN_PREFIX}loading-actual-start`,
                `${LoadingInstrumentation.SPAN_PREFIX}loading-actual-end`,
            );
            this.log(
                `Created loading-actual measure (${Math.round(finalActualEndTime - finalActualStartTime)}ms)`,
            );

            this.ensureMark(
                `${LoadingInstrumentation.SPAN_PREFIX}loading-total-start`,
                this.logTimeOriginMs,
            );
            performance.measure(
                `${LoadingInstrumentation.SPAN_PREFIX}loading-total`,
                `${LoadingInstrumentation.SPAN_PREFIX}loading-total-start`,
                `${LoadingInstrumentation.SPAN_PREFIX}loading-actual-end`,
            );
            this.log(
                `Created loading-total measure (${Math.round(finalActualEndTime - this.logTimeOriginMs)}ms)`,
            );

            this.ensureMark(
                `${LoadingInstrumentation.SPAN_PREFIX}loading-host-start`,
                this.logTimeOriginMs,
            );
            performance.measure(
                `${LoadingInstrumentation.SPAN_PREFIX}loading-host`,
                `${LoadingInstrumentation.SPAN_PREFIX}loading-host-start`,
                `${LoadingInstrumentation.SPAN_PREFIX}loading-actual-start`,
            );
            this.log(
                `Created loading-host measure (${Math.round(finalActualStartTime - this.logTimeOriginMs)}ms)`,
            );

            this.hasEmittedGlobalMeasures = true;
        } else {
            // Still create the end mark even if measures aren't emitted for consistency
            const adjustedActualEndTime = this.ensureMinimumDuration(
                startEntryEffective.startTime,
                finalizeEndTime,
            );
            performance.mark(`${LoadingInstrumentation.SPAN_PREFIX}loading-actual-end`, {
                startTime: adjustedActualEndTime,
            });
        }

        if ('clearMarks' in performance && !this.retainElementMarks) {
            performance.clearMarks(`${LoadingInstrumentation.SPAN_PREFIX}loading-actual-start`);
            performance.clearMarks(`${LoadingInstrumentation.SPAN_PREFIX}loading-actual-end`);
        }
        let uiStartTime = this.firstUiComponentStartTime;
        let uiEndTime = this.lastUiComponentEndTime;
        for (const data of this.observedElements.values()) {
            if (data.started && data.insideShadow) {
                uiEndTime = Math.max(uiEndTime, finalizeEndTime);
                if (uiStartTime === 0 && data.startTime !== undefined) {
                    uiStartTime = data.startTime;
                }
            }
        }
        if (uiStartTime === 0 && uiEndTime > 0) {
            uiStartTime = startEntryEffective.startTime;
        }
        // When there were no UI components observed, emit a minimum duration aggregate aligned to navigation start
        if (uiStartTime === 0 && uiEndTime === 0) {
            uiStartTime = startEntryEffective.startTime;
            uiEndTime = startEntryEffective.startTime;
        }
        if (uiEndTime >= uiStartTime && this.emitMeasures) {
            const adjustedUiEndTime = this.ensureMinimumDuration(uiStartTime, uiEndTime);
            performance.mark(`${LoadingInstrumentation.SPAN_PREFIX}loading-ui-components-start`, {
                startTime: uiStartTime,
            });
            performance.mark(`${LoadingInstrumentation.SPAN_PREFIX}loading-ui-components-end`, {
                startTime: adjustedUiEndTime,
            });
            performance.measure(
                `${LoadingInstrumentation.SPAN_PREFIX}loading-ui-components`,
                `${LoadingInstrumentation.SPAN_PREFIX}loading-ui-components-start`,
                `${LoadingInstrumentation.SPAN_PREFIX}loading-ui-components-end`,
            );
            this.log(
                `Created loading-ui-components measure (${Math.round(adjustedUiEndTime - uiStartTime)}ms)`,
            );
            if ('clearMarks' in performance && !this.retainElementMarks) {
                performance.clearMarks(
                    `${LoadingInstrumentation.SPAN_PREFIX}loading-ui-components-start`,
                );
                performance.clearMarks(
                    `${LoadingInstrumentation.SPAN_PREFIX}loading-ui-components-end`,
                );
            }
        }
        if (this.groupedOverflow.size > 0 && this.emitMeasures) {
            for (const [label, group] of this.groupedOverflow.entries()) {
                const adjustedGroupEnd = this.ensureMinimumDuration(group.minStart, group.maxEnd);
                const groupStart = `${LoadingInstrumentation.SPAN_PREFIX}loading-elements-grouped-start ${label}`;
                const groupEnd = `${LoadingInstrumentation.SPAN_PREFIX}loading-elements-grouped-end ${label}`;
                performance.mark(groupStart, {
                    startTime: group.minStart,
                });
                performance.mark(groupEnd, {
                    startTime: adjustedGroupEnd,
                });
                const effectiveLabel = label || this.firstIndividualSelectorLabel || '(unknown)';
                const name = `${LoadingInstrumentation.SPAN_PREFIX}loading-elements ${effectiveLabel} (grouped ${group.count})`;
                performance.measure(name, groupStart, groupEnd);
                if ('clearMarks' in performance && !this.retainElementMarks) {
                    performance.clearMarks(groupStart);
                    performance.clearMarks(groupEnd);
                }
            }
        }
        this.loadingAggregationStarted = false;
        this.lastActivityTime = 0;
        this.perElementMeasuresCreated = 0;
        this.elementIdCounter = 0;
        this.firstUiComponentStartTime = 0;
        this.lastUiComponentEndTime = 0;
        this.groupedOverflow.clear();
        this.firstIndividualSelectorLabel = null;
        this.unobserveAll(true, finalizeEndTime);
        this.releaseAllReferences();
        this.recordingEnabled = false;
    }

    private trackVisibility(el: Element): void {
        if (!this.recordingEnabled) {
            return;
        }
        if (this.observedElements.has(el)) {
            const existing = this.observedElements.get(el);
            if (existing?.started) {
                this.recordLoadingActivity();
            }
            this.debug('trackVisibility: element already tracked', el);
            return;
        }

        const root = this.getRootForElement(el);
        const intersectionObserver = this.getIntersectionObserverForRoot(root);

        const insideShadow = this.isElementInsideShadow(el);

        this.observedElements.set(el, {
            started: false,
            root,
            insideShadow,
        });
        let set = this.rootObservedElements.get(root);
        if (!set) {
            set = new Set<Element>();
            this.rootObservedElements.set(root, set);
        }
        set.add(el);
        intersectionObserver.observe(el);
    }

    private scanAndTrack(root: Element | Document | ShadowRoot): void {
        if (!root) {
            this.log('scanAndTrack skipped: no root');
            return;
        }
        if (this.disposed) {
            return;
        }
        if (root instanceof Element && root.matches(this.selector)) {
            this.trackVisibility(root);
        }
        let matched: NodeListOf<Element> | null = null;
        matched = (root as ParentNode).querySelectorAll?.(
            this.selector,
        ) as NodeListOf<Element> | null;
        if (matched) {
            for (let i = 0; i < matched.length; i++) {
                this.trackVisibility(matched[i]);
            }
        }

        const walker = document.createTreeWalker(root as Node, NodeFilter.SHOW_ELEMENT);
        while (walker.nextNode()) {
            const node = walker.currentNode as Element & {
                shadowRoot?: ShadowRoot;
            };
            if (node.shadowRoot) {
                const shadow = node.shadowRoot;
                this.scanAndTrack(shadow);
                this.observeMutations(shadow);
            }
        }
    }

    private observeMutations(targetRoot: Document | ShadowRoot): void {
        if (this.activeObservers.has(targetRoot)) {
            return;
        }
        const mo = new MutationObserver((mutations) => {
            if (this.disposed) {
                return;
            }
            for (const mutation of mutations) {
                if (mutation.type === 'childList') {
                    this.scheduleScan(targetRoot);
                    mutation.removedNodes.forEach((node) => {
                        if (node instanceof HTMLElement) {
                            const stack: Element[] = [node];
                            let cur: Element | undefined;
                            while ((cur = stack.pop()) !== undefined) {
                                const current = cur;
                                if (this.observedElements.has(current)) {
                                    this.finalizeElement(current);
                                }
                                current.childNodes.forEach((child) => {
                                    if (child instanceof HTMLElement) {
                                        stack.push(child);
                                    }
                                });
                            }
                            const host = node as Element & {
                                shadowRoot?: ShadowRoot;
                            };
                            if (host.shadowRoot) {
                                this.cleanupRoot(host.shadowRoot);
                            }
                        }
                    });
                } else if (mutation.type === 'attributes') {
                    if (mutation.target instanceof HTMLElement) {
                        const el = mutation.target;
                        const observed = this.observedElements.get(el);
                        if (observed?.started && !this.isElementActuallyVisible(el)) {
                            this.finalizeElement(el);
                            continue;
                        }
                        const nowMatches = el.matches(this.selector);
                        if (nowMatches) {
                            this.trackVisibility(el);
                        } else if (this.observedElements.has(el)) {
                            const data = this.observedElements.get(el);
                            if (data && !data.started) {
                                const elementId = this.getNextElementId();
                                const insideShadow = this.isElementInsideShadow(el);
                                const baseName = insideShadow
                                    ? 'loading-ui-component'
                                    : 'loading-element';
                                const span = this.createElementSpan(elementId.toString(), baseName);
                                data.span = span;
                                data.id = elementId;
                                data.selectorLabel = this.buildElementSelectorLabel(el);
                                const now = performance.now();
                                data.startTime = now;
                                data.started = true;
                                this.finalizeElement(el, { endTime: now });
                            } else if (data && data.started) {
                                this.finalizeElement(el);
                            }
                        }
                    }
                }
            }
        });
        mo.observe(targetRoot, {
            childList: true,
            subtree: true,
            attributes: true,
            attributeFilter: [
                'class',
                'aria-hidden',
                'aria-busy',
                'role',
                'data-testid',
                'data-loading-indicator',
                'style',
            ],
        });
        this.activeObservers.set(targetRoot, mo);
    }

    private scheduleScan(root: Document | ShadowRoot): void {
        if (this.disposed || this.scheduledScanRoots.has(root)) {
            return;
        }
        this.scheduledScanRoots.add(root);
        window.requestAnimationFrame(() => {
            this.scheduledScanRoots.delete(root);
            if (this.disposed) {
                return;
            }
            this.scanAndTrack(root);
        });
    }

    private cleanupRoot(root: Document | ShadowRoot): void {
        const set = this.rootObservedElements.get(root);
        if (set) {
            const io = this.rootIntersectionObservers.get(root);
            for (const el of set.values()) {
                io?.unobserve(el);
                this.observedElements.delete(el);
            }
            set.clear();
            this.rootObservedElements.delete(root);
        }
        const intersectionObserver = this.rootIntersectionObservers.get(root);
        if (intersectionObserver) {
            intersectionObserver.disconnect();
            this.rootIntersectionObservers.delete(root);
        }
        const mutationObserver = this.activeObservers.get(root);
        if (mutationObserver) {
            mutationObserver.disconnect();
            this.activeObservers.delete(root);
        }
    }

    private installNavigationListeners(): void {
        window.addEventListener('popstate', this.handleNavigationEvent);
        window.addEventListener('hashchange', this.handleNavigationEvent);
        this.origPushState = history.pushState.bind(history);
        this.origReplaceState = history.replaceState.bind(history);
        history.pushState = ((...args: Parameters<typeof history.pushState>) => {
            this.origPushState?.(...args);
            this.scheduleNavigationReset();
        }) as typeof history.pushState;
        history.replaceState = ((...args: Parameters<typeof history.replaceState>) => {
            this.origReplaceState?.(...args);
            this.scheduleNavigationReset();
        }) as typeof history.replaceState;
        this.log('Navigation monitoring enabled');
    }

    private uninstallNavigationListeners(): void {
        window.removeEventListener('popstate', this.handleNavigationEvent);
        window.removeEventListener('hashchange', this.handleNavigationEvent);
        if (this.origPushState) {
            history.pushState = this.origPushState;
        }
        if (this.origReplaceState) {
            history.replaceState = this.origReplaceState;
        }
    }

    private handleNavigationEvent = (): void => {
        this.scheduleNavigationReset();
    };

    private scheduleNavigationReset(): void {
        if (this.disposed) {
            return;
        }
        const href = typeof location !== 'undefined' ? String(location.href) : '';
        if (this.navigationDebounceHandle) {
            clearTimeout(this.navigationDebounceHandle);
            this.navigationDebounceHandle = null;
        }
        this.navigationDebounceHandle = setTimeout(() => {
            this.navigationDebounceHandle = null;
            if (this.disposed) {
                return;
            }
            this.lastNavigationHref = href;
            this.resetLoadingAggregation();
        }, this.navigationDebounceWindowMs);
    }

    private resetLoadingAggregation = (): void => {
        if (this.disposed) {
            return;
        }
        if (this.loadingAggregationStarted) {
            this.finalizeLoadingAggregation();
        }
        this.loadingAggregationStarted = false;
        this.hasEmittedGlobalMeasures = false;
        this.lastActivityTime = 0;
        if (this.loadingAggregationTimeout) {
            clearTimeout(this.loadingAggregationTimeout);
            this.loadingAggregationTimeout = null;
        }
        this.unobserveAll(false);
        this.perElementMeasuresCreated = 0;
        this.elementIdCounter = 0;
        this.recordingEnabled = true;
        if ('clearMarks' in performance && !this.retainElementMarks) {
            performance.clearMarks(`${LoadingInstrumentation.SPAN_PREFIX}loading-actual-start`);
            performance.clearMarks(`${LoadingInstrumentation.SPAN_PREFIX}loading-actual-end`);
            performance.clearMarks(`${LoadingInstrumentation.SPAN_PREFIX}loading-total-start`);
            performance.clearMarks(`${LoadingInstrumentation.SPAN_PREFIX}loading-host-start`);
        }
        if ('getEntriesByType' in performance && 'clearMeasures' in performance) {
            const measures = performance.getEntriesByType('measure') as PerformanceEntry[];
            for (const entry of measures) {
                if (entry.name?.startsWith(LoadingInstrumentation.SPAN_PREFIX)) {
                    performance.clearMeasures(entry.name);
                }
            }
        }
        this.groupedOverflow.clear();
        this.firstIndividualSelectorLabel = null;
        this.log('Reset for new navigation');
        const now = performance.now();
        this.logTimeOriginMs = now;
        this.markLoadingTotalStart(now);
        this.markLoadingHostStart(now);
        this.observeMutations(document);
        this.scanAndTrack(document);
        window.requestAnimationFrame(() => this.scanAndTrack(document));
        this.scheduleIdleFinalize();
    };

    private markLoadingTotalStart(startTime: number): void {
        this.createGlobalSpan('loading-total-start', startTime);
        this.log('loading-total tracking started');
    }

    private markLoadingHostStart(startTime: number): void {
        this.createGlobalSpan('loading-host-start', startTime);
        this.log('loading-host tracking started');
    }

    private ensureMark(name: string, startTime: number): void {
        if (!this.emitMeasures) {
            return;
        }

        const exists =
            typeof performance.getEntriesByName === 'function' &&
            performance.getEntriesByName(name)?.length > 0;
        if (!exists) {
            performance.mark(name, { startTime });
            this.recreatedMarksCount += 1;
            this.debug('Recreated missing mark %s (total=%d)', name, this.recreatedMarksCount);
        }
    }

    private createSpan(name: string, startTime?: number): PartialReadableSpan {
        const now = startTime ?? performance.now();
        performance.mark(name, { startTime: now });
        return { name };
    }

    private createElementSpan(
        elementId: string,
        baseName: string,
        startTime?: number,
    ): PartialReadableSpan {
        const spanName = `${LoadingInstrumentation.SPAN_PREFIX}${baseName}-${elementId}`;
        return this.createSpan(spanName, startTime);
    }

    private createGlobalSpan(baseName: string, startTime?: number): PartialReadableSpan {
        const spanName = `${LoadingInstrumentation.SPAN_PREFIX}${baseName}`;
        return this.createSpan(spanName, startTime);
    }

    private releaseAllReferences(): void {
        // Disconnect and clear all per-root observer maps and element references
        for (const io of this.rootIntersectionObservers.values()) {
            io.disconnect();
        }
        this.rootIntersectionObservers.clear();
        for (const mo of this.activeObservers.values()) {
            mo.disconnect();
        }
        this.activeObservers.clear();
        this.rootObservedElements.clear();
        this.observedElements.clear();
    }

    /**
     * Ensures a minimum duration of 1 frame (16ms) for performance measures.
     * Adjusts the end time if the duration would be less than the minimum.
     */
    private ensureMinimumDuration(startTime: number, endTime: number): number {
        const duration = endTime - startTime;
        if (duration < LoadingInstrumentation.MIN_FRAME_DURATION_MS) {
            return startTime + LoadingInstrumentation.MIN_FRAME_DURATION_MS;
        }
        return endTime;
    }
}
