import type { Icon as SpectrumIcon } from '@ccx-public/spectrum-web-component-fallbacks/dist/icon';
import createWrapper from './utils/createWrapper';
import interopRequireDefault from './utils/interopRequireDefault';
import { SWCLoader } from './utils/SWCLoader';
import { getSWCProps } from './Icon/utils';
import type { RS2IconProps } from './Icon/utils';

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2Icon: React.ComponentType<unknown> = process.env.INCLUDE_RS2
    ? interopRequireDefault(require('react-spectrum/Icon')).default
    : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

let swcLoader;

if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(['sp-icon'], async () => {
        const { Icon } = await import(
            /* webpackChunkName: "SpIcon" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/icon'
        );
        return [Icon];
    });
}

const Icon = createWrapper<SpectrumIcon, RS2IconProps>({
    displayName: 'Icon',
    fallback: RS2Icon,
    swcLoader,
    swcProps: getSWCProps,
    tagName: 'sp-icon',
});

export default Icon;
