import type { ElementSize } from '@ccx-public/spectrum-web-component-fallbacks/dist/base';
import type { ProgressCircle } from '@ccx-public/spectrum-web-component-fallbacks/dist/progress-circle';
import { SWCLoader } from './utils/SWCLoader';
import createWrapper from './utils/createWrapper';
import { filterBooleanProps } from './utils';
import interopRequireDefault from './utils/interopRequireDefault';

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2Wait: React.ComponentType<unknown> = process.env.INCLUDE_RS2
    ? interopRequireDefault(require('react-spectrum/Wait')).default
    : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

let swcLoader;
if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(['sp-progress-circle'], async () => {
        const { ProgressCircle } = await import(
            /* webpackChunkName: "SpProgressCircle" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/progress-circle'
        );
        return [ProgressCircle];
    });
}

type RS2Size = 'S' | 'M' | 'L';
type RS2CompatProps = {
    /** progress of the progress circle */
    value?: number;
    variant?: 'overBackground';
    size?: RS2Size;
};

const SIZE_CONVERSIONS: Record<RS2Size, ElementSize> = {
    S: 's',
    M: 'm',
    L: 'l',
};

export default createWrapper<ProgressCircle, RS2CompatProps>({
    displayName: 'Wait',
    fallback: RS2Wait,
    swcLoader,
    swcProps: (props) => {
        const {
            className,
            variant,
            value,
            indeterminate,
            size = 'M',
            ...rest
        } = props;

        // ReactSpectrum2           | SpectrumWebComponent
        // ---------------------------------------------
        // value                    | progress
        // variant:overBackground   | staticColor

        return {
            ...rest,
            ...filterBooleanProps({
                indeterminate: typeof value === 'undefined' || indeterminate,
            }),
            class: className,
            progress: value,
            size: SIZE_CONVERSIONS[size],
            'static-color':
                variant && variant === 'overBackground' ? 'white' : undefined,
        };
    },
    tagName: 'sp-progress-circle',
});
