// https://opensource.adobe.com/spectrum-web-components/components/radio/
// https://git.corp.adobe.com/torq/react-spectrum/tree/develop/src/Radio
import type { Radio as RadioType } from '@ccx-public/spectrum-web-component-fallbacks/dist/radio';
import { filterBooleanProps } from './utils';
import createWrapper from './utils/createWrapper';
import { SWCLoader } from './utils/SWCLoader';
import interopRequireDefault from './utils/interopRequireDefault';

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2Radio: React.ComponentType<unknown> = process.env.INCLUDE_RS2
    ? interopRequireDefault(require('react-spectrum/Radio')).default
    : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

let swcLoader;
if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(['sp-radio'], async () => {
        const { Radio } = await import(
            /* webpackChunkName: "SpRadio" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/radio'
        );
        return [Radio];
    });
}

type RS2CompatProps = {
    /**
     * The label to display with the radio
     */
    label?: string;

    /**
     * Flag that decides whether to display label
     */
    renderLabel?: boolean;

    /**
     * Flag that decides black/blue checks of circle
     */
    quiet?: boolean;
};

export default createWrapper<RadioType, RS2CompatProps>({
    displayName: 'Radio',
    fallback: RS2Radio,
    swcLoader,
    swcProps: (props) => {
        const {
            className,
            renderLabel = true,
            label,
            checked,
            disabled,
            invalid,
            quiet = false,
            ...rest
        } = props;

        // ReactSpectrum2        | SpectrumWebComponent
        // ---------------------------------------------
        // labelBelow            | label-below
        // emphasized            | !quiet
        // label                 | label is directly passed as innerHTML text
        // renderlabel:          | no such flag to conditionally render label
        // flag based on which   |
        // label is rendered     |
        //

        // checked, disabled, invalid, emphasized, readOnly are props in RS2
        // but when passed directly as attributes to SWC, they don't work as expected.
        // So these attributes are only passed if they are true;

        // label must be passed a prop and not as children to the wrapper.

        return {
            ...rest,
            ...filterBooleanProps({
                checked,
                disabled,
                invalid,
                emphasized: !quiet,
            }),
            children: renderLabel ? label : '',
            class: className,
        };
    },
    tagName: 'sp-radio',
});
