import React, { useEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';

import type { ReactProps } from './utils';
import { filterBooleanProps, useComponent } from './utils';

// https://opensource.adobe.com/spectrum-web-components/components/popover/
// https://git.corp.adobe.com/torq/react-spectrum/tree/develop/src/Popover
import type { Popover as PopoverType } from '@ccx-public/spectrum-web-component-fallbacks/dist/popover';
import { SWCLoader } from './utils/SWCLoader';
import createWrapper from './utils/createWrapper';
import interopRequireDefault from './utils/interopRequireDefault';

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2Popover: React.ComponentType<
    ReactProps<PopoverType, BaseOptions & RS2CompatProps>
> = process.env.INCLUDE_RS2
    ? interopRequireDefault(require('react-spectrum/Popover')).default
    : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

let swcLoader;
if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(['sp-popover', 'sp-dialog'], async () => {
        const [{ Popover }, { Dialog }] = await Promise.all([
            import(
                /* webpackChunkName: "SpPopover" */
                '@ccx-public/spectrum-web-component-fallbacks/dist/popover'
            ),
            import(
                /* webpackChunkName: "SpDialog" */
                '@ccx-public/spectrum-web-component-fallbacks/dist/dialog'
            ),
        ]);

        return [Popover, Dialog];
    });
}

type RS2CompatProps = {
    contentStyle?: object;
    isDialog?: boolean;
    open?: boolean;
    role?: string;
    title?: string;
    trapFocus?: boolean;
    variant?: string;
};

type BaseOptions = {
    enablePortaling?: boolean;
    contentStyle?: object;
    excludeDialog?: boolean;
};

export default createWrapper<PopoverType, BaseOptions & RS2CompatProps>({
    displayName: 'Popover',
    fallback: RS2Popover,
    swcLoader,
    SWCWrapper: function (props) {
        const {
            children,
            className,
            contentStyle = {},
            enablePortaling = false,
            open,
            placement,
            title,
            /* eslint-disable @typescript-eslint/no-unused-vars */
            // RS2-UXP-only props
            trapFocus,
            isDialog,
            role,
            /* eslint-enable @typescript-eslint/no-unused-vars */
            excludeDialog,
            ...rest
        } = props;

        // ReactSpectrum2           | SpectrumWebComponent
        // ---------------------------------------------
        // title                    | title: present in child
        // placement                 | placement with tip & dialog true

        const childrenArr = [];
        const hasTitle = title && title !== '';

        if (hasTitle) {
            childrenArr.push(<span slot="heading">{title}</span>);
        }

        childrenArr.push(
            <div key="popover-children" style={contentStyle}>
                {children}
            </div>
        );

        const childrenWrapperRef = useRef<HTMLDivElement>(null);
        const [, forceUpdate] = useState(false);

        useEffect(() => {
            if (enablePortaling) {
                forceUpdate(true);
            }
        }, [enablePortaling]);

        let popoverContents = enablePortaling ? (
            <div ref={childrenWrapperRef}></div>
        ) : (
            childrenArr
        );

        const Popover = useComponent('sp-popover');
        const Dialog = useComponent('sp-dialog');

        if (!excludeDialog) {
            popoverContents = (
                <Dialog {...filterBooleanProps({ 'no-divider': !hasTitle })}>
                    {popoverContents}
                </Dialog>
            );
        }

        return (
            <>
                <Popover
                    {...rest}
                    {...filterBooleanProps({
                        open: open,
                        tip: !!placement,
                    })}
                    class={className}
                    placement={placement}
                >
                    {popoverContents}
                </Popover>
                {enablePortaling &&
                    childrenWrapperRef.current &&
                    createPortal(childrenArr, childrenWrapperRef.current)}
            </>
        );
    },
    tagName: 'sp-popover',
});
