// https://react-spectrum.corp.adobe.com/storybook/?path=/story/overlaytrigger--with-trigger-click
// https://opensource.adobe.com/spectrum-web-components/components/overlay-trigger/
import type {
    OverlayTrigger as OverlayTriggerType,
    OverlayContentTypes,
    Placement,
} from '@ccx-public/spectrum-web-component-fallbacks/dist/overlay';
import React, { useRef, useEffect } from 'react';
import createWrapper from './utils/createWrapper';
import { SWCLoader } from './utils/SWCLoader';
import interopRequireDefault from './utils/interopRequireDefault';
import { filterBooleanProps, useComponent } from './utils';

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2OverlayTrigger: React.ComponentType<unknown> = process.env.INCLUDE_RS2
    ? interopRequireDefault(require('react-spectrum/OverlayTrigger')).default
    : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

let swcLoader;
if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(['overlay-trigger'], async () => {
        const { OverlayTrigger } = await import(
            /* webpackChunkName: "SpOverlay" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/overlay'
        );
        return [OverlayTrigger];
    });
}

type Triggers = 'click' | 'longClick' | 'hover' | 'focus';

type BoundariesElementType = (() => Element | null) | string;
type RS2CompatProps = {
    open?: OverlayContentTypes;
    placement?: string;
    trigger?: Triggers | Triggers[];
    onShow?: () => void;
    onHide?: () => void;
    delayShow?: number;
    disabled?: boolean;
    // RS2-UXP-only prop
    boundariesElement?: BoundariesElementType;
    show?: boolean;
};

// RS2 to SWC Placement map
const placementMap: Record<string, Placement> = {
    left: 'left',
    right: 'right',
    top: 'top',
    bottom: 'bottom',
    'top left': 'top-start',
    'top right': 'top-end',
    'bottom left': 'bottom-start',
    'bottom right': 'bottom-end',
    'left top': 'left-start',
    'left bottom': 'left-end',
    'right top': 'right-start',
    'right bottom': 'right-end',
};

const DEFAULT_TRIGGERS = ['hover', 'focus'];

export default createWrapper<OverlayTriggerType, RS2CompatProps>({
    displayName: 'OverlayTrigger',
    fallback: RS2OverlayTrigger,
    swcLoader,
    SWCWrapper: function OverlayTrigger(props) {
        const {
            trigger = DEFAULT_TRIGGERS,
            children,
            className,
            onHide,
            onShow,
            disabled,
            delayShow,
            // RS2-UXP-only props
            /* eslint-disable @typescript-eslint/no-unused-vars */
            boundariesElement,
            show,
            /* eslint-enable @typescript-eslint/no-unused-vars */
            ...rest
        } = props;
        const childrenArray = React.Children.toArray(children);
        const modalTriggerRef = useRef<OverlayTriggerType>(null);
        const triggers =
            typeof trigger === 'object' ? trigger : trigger ? [trigger] : [];
        const slotNames: string[] = [];
        const resultArray: JSX.Element[] = [];

        // map RS2 to SWC Placement mapping
        const placement = props.placement
            ? placementMap[props.placement]
            : 'left';

        useEffect(() => {
            const current = modalTriggerRef?.current;

            if (current && onShow) {
                current.addEventListener('sp-opened', onShow);
            }
            if (current && onHide) {
                current.addEventListener('sp-closed', onHide);
            }

            return () => {
                if (current && onShow) {
                    current.removeEventListener('sp-opened', onShow);
                }
                if (current && onHide) {
                    current.removeEventListener('sp-closed', onHide);
                }
            };
        }, [onShow, onHide]);

        triggers.forEach((curTrigger: string) => {
            if (
                curTrigger?.includes('hover') ||
                curTrigger?.includes('focus')
            ) {
                slotNames.push('hover-content');
            } else if (curTrigger?.includes('click')) {
                slotNames.push('click-content');
            } else if (curTrigger?.includes('longClick')) {
                slotNames.push('longpress-content');
            }
        });

        /*
         * RS2 only supports two children to be used in an overlay trigger.
         * It is assumed that the first child is the trigger element and the second child is
         * the element to overlay. The following check, along with checking for trigger above
         * and slot props below, are used to know if the RS2 interface is being used. If this is
         * the case we make the same assuptions as RS2 and treat the first child as the trigger
         * and the second child as the element to overlay.
         * If any of these checks fail we still allow the overlay to render so the SWC interface cas be used as well.
         * https://git.corp.adobe.com/React/react-spectrum-v2/blob/v2.39.0/src/OverlayTrigger/js/OverlayTrigger.js#L510
         */
        if (slotNames.length && childrenArray.length === 2) {
            const firstChild = childrenArray[0] as JSX.Element;
            const secondChild = childrenArray[1] as JSX.Element;

            // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
            if (!firstChild.props?.slot) {
                const TriggerComp = React.cloneElement(firstChild, {
                    slot: 'trigger',
                });
                resultArray.push(TriggerComp);
            } else {
                resultArray.push(firstChild);
            }

            // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
            if (!secondChild.props?.slot) {
                slotNames.forEach((curSlot: string) => {
                    const TriggerTargetComp = React.cloneElement(secondChild, {
                        slot: curSlot,
                        delayed: delayShow ? true : undefined,
                    });
                    resultArray.push(TriggerTargetComp);
                });
            } else {
                resultArray.push(secondChild);
            }
        }

        const OverlayTrigger = useComponent('overlay-trigger');

        return (
            <OverlayTrigger
                {...rest}
                {...filterBooleanProps({ disabled })}
                placement={placement}
                class={className}
                triggered-by={triggers.join(' ')}
                ref={modalTriggerRef}
            >
                {resultArray.length ? resultArray : children}
            </OverlayTrigger>
        );
    },
    tagName: 'overlay-trigger',
});
