const colorToHex = (color)=>{
    const colorRound = Math.max(0, Math.min(255, Math.round(color)));
    const hexadecimal = colorRound.toString(16);
    return 1 === hexadecimal.length ? '0' + hexadecimal : hexadecimal;
};
const rgbaToHex = (r, g, b, a)=>'#' + colorToHex(r) + colorToHex(g) + colorToHex(b) + colorToHex(Math.floor(255 * a));
export { colorToHex, rgbaToHex };
