import apps from './apps'

const GLOBAL_REGION_CODE = 'ZZ'
const GLOBAL_REGION_NAME = 'Global'

/*
 * @param {string} app - app code. For a complete apps code, see https://git.corp.adobe.com/intl/adobe-locales#supported-apps
 * @returns {array} app supported region code or code/name pair. Returns empty array if passed locale is not supported in the app. 
 */
const getAppRegions = (app, withName = true, nameLocale = 'en') => {
  const appSettings = apps.get(app) 
  const regions = (appSettings && appSettings.regions) || []

  if (regions.length > 0 && withName === true) {
    const regionNames = Intl.DisplayNames && new Intl.DisplayNames([nameLocale], { type: 'region' })
    
    return regions.map(region => ({
      code: region,
      name: region === GLOBAL_REGION_CODE ? GLOBAL_REGION_NAME : regionNames && regionNames.of(region)
    }))
  }

  return regions
}

export default getAppRegions;



