// https://opensource.adobe.com/spectrum-web-components/components/switch/
// https://git.corp.adobe.com/torq/react-spectrum/tree/develop/src/switch
import React, { useEffect, useRef } from 'react';
import type { Switch as SwitchType } from '@ccx-public/spectrum-web-component-fallbacks/dist/switch';
import { filterBooleanProps, useComponent } from './utils';
import createWrapper from './utils/createWrapper';
import { SWCLoader } from './utils/SWCLoader';
import interopRequireDefault from './utils/interopRequireDefault';

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2Switch: React.ComponentType<unknown> = process.env.INCLUDE_RS2
    ? interopRequireDefault(require('react-spectrum/Switch')).default
    : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

let swcLoader;
if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(['sp-switch'], async () => {
        const { Switch } = await import(
            /* webpackChunkName: "SpSwitch" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/switch'
        );
        return [Switch];
    });
}

type RS2CompatProps = {
    /**
     * The label to display with the Switch
     */
    label?: string;

    /**
     * Flag that decides whether to display label
     */
    renderLabel?: boolean;
    /**
     * Flag that decides black/blue checks of Switch
     */
    quiet?: boolean;
    onChange?: (value: boolean, event: Event) => unknown;
    /**
     * SWC doesn't support fully controlling the checked state.
     * Adding defaultChecked for RS2 compatability but checked and defaultChecked now behave the same.
     */
    defaultChecked?: boolean;
};

export default createWrapper<SwitchType, RS2CompatProps>({
    displayName: 'Switch',
    fallback: RS2Switch,
    swcLoader,
    SWCWrapper: (props) => {
        const switchWrapperRef = useRef<SwitchType>(null);
        const {
            renderLabel = true,
            label,
            className,
            checked,
            defaultChecked,
            disabled,
            children,
            quiet,
            onChange,
            ...rest
        } = props;

        useEffect(() => {
            const current = switchWrapperRef.current;

            const change = (event: Event) => {
                const target = event.target as SwitchType;
                onChange?.(target.checked, event);
            };

            if (current && onChange) {
                current.addEventListener('change', change);
            }

            return () => {
                if (current && onChange) {
                    current.removeEventListener('change', change);
                }
            };
        }, [onChange]);

        // Differences:
        // ReactSpectrum           | SpectrumWebComponent
        // ---------------------------------------------
        // label                   | label is directly passed as innerHTML text

        const Switch = useComponent('sp-switch');
        return (
            <Switch
                {...rest}
                {...filterBooleanProps({
                    checked: checked ?? defaultChecked,
                    disabled,
                    emphasized: !quiet,
                })}
                class={className}
                ref={switchWrapperRef}
            >
                {renderLabel ? label : ''}
                {children}
            </Switch>
        );
    },
    tagName: 'sp-switch',
});
