import { Config } from "@dunamis-service/config/ingest_config";
export class IngestConfigProvider {
    constructor(configGuid, onFetchConfig) {
        this.configGuid_ = configGuid;
        this.config_ = Config.getDefaultConfig();
        this.onFetchConfig_ = onFetchConfig;
        this.refreshConfig();
    }
    refreshConfig() {
        this.updateConfig(this.onFetchConfig_(this.configGuid_));
    }
    updateConfig(config) {
        this.config_ = config;
    }
    getConfigGuid() {
        return this.configGuid_;
    }
    getApiKey() {
        return this.config_.setup.ingest.apiKey;
    }
    getProject() {
        return this.config_.setup.ingest.project;
    }
    getEnvironment() {
        return this.config_.setup.ingest.environment;
    }
    getSourceType() {
        return this.config_.setup.ingest.sourceType;
    }
    getConsent() {
        return this.config_.setup.ingest.consent;
    }
    getSourceCategory() {
        return this.config_.setup.ingest.sourceCategory;
    }
    getValidation() {
        return this.config_.reserved.validation;
    }
    getBatchSize() {
        return this.config_.reserved.event.batchSize;
    }
    getBatchInterval() {
        return this.config_.reserved.event.batchInterval;
    }
    getFlushOnStopEnabled() {
        return this.config_.reserved.event.flushOnStopEnabled;
    }
    getMetaEventEnabled() {
        return this.config_.reserved.event.metaEventEnabled;
    }
    getHeartBeatEnabled() {
        return this.config_.reserved.heartbeat.enabled;
    }
    getHeartBeatInterval() {
        return this.config_.reserved.heartbeat.interval;
    }
    isValidationDisabled() {
        return !this.config_.reserved.validation.flag;
    }
}
