const LEIA_STAGE_URL = 'https://leia-stage.adobe.io/v1/acp_report_abuse';
const LEIA_PROD_URL = 'https://leia.adobe.io/v1/acp_report_abuse';
async function postReportAbuse(assetId, reportAbuseInputData, environment, appName, apiKey, language = 'en_US') {
    const requestHeaders = {
        'Content-Type': 'application/json',
        'X-Api-Key': apiKey
    };
    const requestBody = JSON.stringify({
        productId: appName,
        assetList: [
            {
                assetId
            }
        ],
        reportDate: new Date().toISOString(),
        reportType: reportAbuseInputData.reportType,
        reportDesc: reportAbuseInputData.reportDesc,
        reporterName: reportAbuseInputData.reporterName,
        reporterEmail: reportAbuseInputData.reporterEmail,
        language: language.replace('-', '_')
    });
    const requestOptions = {
        method: 'POST',
        headers: requestHeaders,
        body: requestBody
    };
    const LEIA_URL = 'stage' === environment ? LEIA_STAGE_URL : LEIA_PROD_URL;
    const response = await fetch(LEIA_URL, requestOptions);
    return response;
}
export { postReportAbuse };
