import moving_files from "../assets/moving-files.mjs";
import no_files_to_show from "../assets/no-files-to-show.mjs";
import shortcut_for_bulk_selection from "../assets/shortcut-for-bulk-selection.mjs";
import mobile_long_press from "../assets/mobile-long-press.mjs";
import { isTouchDevice } from "@csc/common";
const DEFAULT_ONBOARDING_STEPS = [
    'movingFiles',
    'rightClick',
    'bulkSelect'
];
const TOUCHSCREEN_ONBOARDING_STEPS = [
    'longPress'
];
const ONBOARDING_STEPS_ILLUSTRATIONS = {
    movingFiles: moving_files,
    rightClick: no_files_to_show,
    bulkSelect: shortcut_for_bulk_selection,
    longPress: mobile_long_press
};
const getCDOOnboardingSteps = (intl)=>{
    const isTouchScreen = isTouchDevice();
    if (isTouchScreen) return TOUCHSCREEN_ONBOARDING_STEPS.map((step)=>({
            id: step,
            title: intl.formatMessage({
                id: `onboarding.title.${step}`
            }),
            description: intl.formatMessage({
                id: `onboarding.description.${step}`
            }),
            image: ONBOARDING_STEPS_ILLUSTRATIONS[step]
        }));
    return DEFAULT_ONBOARDING_STEPS.map((step)=>({
            id: step,
            title: intl.formatMessage({
                id: `onboarding.title.${step}`
            }),
            description: intl.formatMessage({
                id: `onboarding.description.${step}`
            }),
            image: ONBOARDING_STEPS_ILLUSTRATIONS[step]
        }));
};
const invokeOnboardingDialog = ({ onboardingSteps, delay, intl, onboardingStore })=>{
    const isTouchScreen = isTouchDevice();
    const cdoOnboardingSteps = getCDOOnboardingSteps(intl);
    const updatedOnboardingDetails = isTouchScreen ? cdoOnboardingSteps : onboardingSteps?.slice() ?? [];
    if (!isTouchScreen) cdoOnboardingSteps.forEach((step)=>{
        if (!updatedOnboardingDetails.find((s)=>s.id === step.id)) updatedOnboardingDetails.push(step);
    });
    onboardingStore.setOnboardingSteps(updatedOnboardingDetails ?? []);
    onboardingStore.setOpenUserOnboardingDialog(true, delay);
};
export { DEFAULT_ONBOARDING_STEPS, ONBOARDING_STEPS_ILLUSTRATIONS, TOUCHSCREEN_ONBOARDING_STEPS, getCDOOnboardingSteps, invokeOnboardingDialog };
