// SWC Props Link :: https://opensource.adobe.com/spectrum-web-components/components/textfield/api/
// RS2 Props Link :: https://react-spectrum.corp.adobe.com/storybook/?path=/story/textfield
import React, { forwardRef, useEffect, useRef } from 'react';
import type { Textfield as TextfieldType } from '@ccx-public/spectrum-web-component-fallbacks/dist/textfield';
import createWrapper from './utils/createWrapper';
import interopRequireDefault from './utils/interopRequireDefault';
import { SWCLoader } from './utils/SWCLoader';
import type { ReactProps, SpectrumElementProps } from './utils';
import { filterBooleanProps, useComponent } from './utils';
import mergeRefs from './utils/mergeRefs';

export type RS2TextfieldCompatProps = {
    // RS2: autoFocus, SWC: autofocus
    autoFocus?: boolean;
    // Whether to disable the text field
    disabled?: boolean;
    // RS2-UXP-only prop: Whether the input gets converted into a span to handle z-index issues in UXP
    disableOnOverlay?: boolean;
    // RS2: DEPRECATED: use validationState instead, SWC: Whether to show the warning icon and red border.
    invalid?: boolean;
    // RS2: maxLength, SWC: maxlength The maximum number of characters that can be entered
    maxLength?: number;
    // RS2: multiLine, SWC: multiline: Whether to render a text field that accepts multiple lines of text
    multiLine?: boolean;
    // Function called when the text field value is changed
    onChange?: (value: string, event?: Event) => void;
    // Function called when focus is taken away from the text field
    onBlur?: React.FocusEventHandler;
    // Function called when focus is put on the text field
    onFocus?: React.FocusEventHandler;
    // Function called when a key is pressed while the input is focused
    onKeyDown?: React.KeyboardEventHandler;
    // Function called when a key is released while the input is focused
    onKeyUp?: React.KeyboardEventHandler;
    // Function called when a paste event has been fired on the input
    onPaste?: React.ClipboardEventHandler;
    // Composition events fired during IME input
    onCompositionStart?: (event: Event) => unknown;
    onCompositionUpdate?: (event: Event) => unknown;
    onCompositionEnd?: (event: Event) => unknown;
    // Whether the text field should render using a quiet variant
    quiet?: boolean;
    // RS2: readOnly, SWC: readonly: Whether the text field can only be read
    readOnly?: boolean;
    // Whether the text field requires user input (shows warning if empty)
    required?: boolean;
    // RS2: spellCheck, SWC: spellcheck: Whether to enable spell checking
    spellCheck?: string;
    // RS2-only, SWC will slot content into valid or invalid boolean props based on it
    // It show either checkmark or warning icons
    validationState?: 'valid' | 'invalid';
};

let swcLoader: SWCLoader | undefined;

if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(['sp-textfield'], async () => {
        const { Textfield } = await import(
            /* webpackChunkName: "SpTextfield" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/textfield'
        );
        return [Textfield];
    });
}

type TextfieldProps = ReactProps<TextfieldType, RS2TextfieldCompatProps>;

export { swcLoader };

export function convertTextfieldPropsToSWC(
    props: TextfieldProps
): SpectrumElementProps<TextfieldType> {
    const {
        autoFocus,
        className,
        disabled,
        invalid,
        maxLength,
        multiLine,
        quiet,
        readOnly,
        required,
        spellCheck,
        /* eslint-disable @typescript-eslint/no-unused-vars */
        // RS2-only props
        disableOnOverlay,
        validationState,
        // Non-relevant props
        onChange,
        /* eslint-enable @typescript-eslint/no-unused-vars */
        ...rest
    } = props;

    // Mapping for RS2 and SWC components which differ in name i.e readonly <-> readOnly
    // ReactSpectrum2           | SpectrumWebComponent
    // ---------------------------------------------
    // autoFocus                | autofocus
    // maxLength                | maxlength
    // multiLine                | multiline
    // readOnly                 | readonly
    // spellCheck               | spellcheck
    // validationState (string) | invalid (boolean)

    return {
        ...rest,
        ...filterBooleanProps({
            autofocus: autoFocus,
            disabled,
            invalid: validationState === 'invalid' ? true : invalid,
            multiline: multiLine,
            quiet,
            readonly: readOnly,
            required,
            valid: validationState === 'valid',
        }),
        class: className,
        maxlength: maxLength,
        spellcheck: spellCheck === 'false' ? false : true,
    };
}

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2Textfield: React.ComponentType<unknown> = process.env.INCLUDE_RS2
    ? interopRequireDefault(require('react-spectrum/Textfield')).default
    : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

export const SpTextfield = forwardRef(function SpTextfield(
    props: TextfieldProps,
    ref
) {
    const textfieldRef = useRef<TextfieldType>(null);
    const {
        onChange,
        onCompositionStart,
        onCompositionUpdate,
        onCompositionEnd,
        ...restProps
    } = props;

    useEffect(() => {
        const { current } = textfieldRef;

        const handleInput = (event: Event) => {
            const target = event.target as HTMLInputElement;

            onChange?.(target.value, event);
        };

        if (current && onChange) {
            current.addEventListener('input', handleInput);
        }

        return () => {
            if (current && onChange) {
                current.removeEventListener('input', handleInput);
            }
        };
    }, [onChange]);

    useEffect(() => {
        const { current } = textfieldRef;

        if (!current) {
            return;
        }

        // Until sp-textfield is updated to support composition events, we need to use the inner focusElement
        const inputEl = current.focusElement;
        if (!inputEl) {
            return;
        }

        const handleCompStart = (event: Event) => {
            onCompositionStart?.(event);
        };
        const handleCompUpdate = (event: Event) => {
            onCompositionUpdate?.(event);
        };
        const handleCompEnd = (event: Event) => {
            onCompositionEnd?.(event);
        };

        if (onCompositionStart)
            inputEl.addEventListener('compositionstart', handleCompStart);
        if (onCompositionUpdate)
            inputEl.addEventListener('compositionupdate', handleCompUpdate);
        if (onCompositionEnd)
            inputEl.addEventListener('compositionend', handleCompEnd);

        return () => {
            if (onCompositionStart)
                inputEl.removeEventListener(
                    'compositionstart',
                    handleCompStart
                );
            if (onCompositionUpdate)
                inputEl.removeEventListener(
                    'compositionupdate',
                    handleCompUpdate
                );
            if (onCompositionEnd)
                inputEl.removeEventListener('compositionend', handleCompEnd);
        };
    }, [onCompositionStart, onCompositionUpdate, onCompositionEnd]);

    const Textfield = useComponent('sp-textfield');
    return (
        <Textfield
            ref={mergeRefs([ref, textfieldRef])}
            {...convertTextfieldPropsToSWC(restProps)}
        />
    );
});

export default createWrapper<TextfieldType, RS2TextfieldCompatProps>({
    displayName: 'Textfield',
    fallback: RS2Textfield,
    swcLoader,
    SWCWrapper: forwardRef(function SpTextarea(props, ref) {
        return <SpTextfield {...props} ref={ref} />;
    }),
    tagName: 'sp-textfield',
});
