import { SAM } from "@ccx-public/component-types";
import { DEFAULT_PAGE_SIZE } from "@csc/sam-utils";
import { when } from "mobx";
import { useCallback, useMemo } from "react";
const useSAMListPagination = ({ samList, maxAssets, hideNextPageLoadingIndicator, pageSize = DEFAULT_PAGE_SIZE })=>{
    const samListStatus = samList?.status;
    const samListItemsLength = samList?.items.length ?? 0;
    const loadNextPage = useCallback(async ({ startIndex, stopIndex: _stopIndex })=>{
        if (!samList) return;
        if (samListStatus === SAM.AssetListStatus.HadLoaderErrors) return void console.error('issue loading next page');
        if (0 === samListItemsLength && 0 === startIndex && samListStatus === SAM.AssetListStatus.Loading) return;
        if (samListStatus === SAM.AssetListStatus.ReadyFullyLoaded) return;
        if (maxAssets && samListItemsLength >= maxAssets) return;
        const limit = maxAssets ? Math.min(maxAssets - samListItemsLength, pageSize) : pageSize;
        await when(()=>samListStatus !== SAM.AssetListStatus.Loading);
        if (samListStatus === SAM.AssetListStatus.ReadyHasMorePages) samList.loadNextPage({
            limit
        });
    }, [
        maxAssets,
        samList,
        samListStatus,
        samListItemsLength,
        pageSize
    ]);
    const pagination = useMemo(()=>{
        if (!samList) return {
            hasNextPage: false,
            loadNextPage: ()=>Promise.resolve(),
            isNextPageLoading: false,
            pageSize
        };
        if (hideNextPageLoadingIndicator) return {
            hasNextPage: false,
            isNextPageLoading: 0 === samListItemsLength && samListStatus === SAM.AssetListStatus.Loading,
            loadNextPage: ()=>Promise.resolve(),
            pageSize
        };
        return {
            hasNextPage: maxAssets ? samListItemsLength < maxAssets && samListStatus === SAM.AssetListStatus.ReadyHasMorePages : samListStatus === SAM.AssetListStatus.ReadyHasMorePages,
            isNextPageLoading: samListStatus === SAM.AssetListStatus.Loading,
            loadNextPage,
            pageSize
        };
    }, [
        loadNextPage,
        maxAssets,
        samListStatus,
        samListItemsLength,
        hideNextPageLoadingIndicator,
        samList,
        pageSize
    ]);
    return pagination;
};
export { useSAMListPagination };
