import type { ReactProps } from './utils';
import { filterBooleanProps, useComponent } from './utils';

import { MenuDivider, MenuItem, menuSwcLoader } from './Menu';
import { SWCLoader } from './utils/SWCLoader';
// https://opensource.adobe.com/spectrum-web-components/components/picker/
// https://git.corp.adobe.com/torq/react-spectrum/tree/develop/src/Select
import type { Picker as SelectType } from '@ccx-public/spectrum-web-component-fallbacks/dist/picker';
import createWrapper from './utils/createWrapper';
import interopRequireDefault from './utils/interopRequireDefault';
import React, { forwardRef, useEffect, useRef } from 'react';

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2Select: React.ComponentType<ReactProps<SelectType, RS2CompatProps>> =
    process.env.INCLUDE_RS2
        ? interopRequireDefault(require('react-spectrum/Select')).default
        : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

let swcLoader;
if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(
        ['sp-picker'],
        async () => {
            const { Picker } = await import(
                /* webpackChunkName: "SpPicker" */
                '@ccx-public/spectrum-web-component-fallbacks/dist/picker'
            );
            return [Picker];
        },
        menuSwcLoader ? [menuSwcLoader] : undefined
    );
}

type OptionObject = {
    label: string;
    value: string;
    description?: JSX.Element | string;
    disabled?: boolean;
    icon?: JSX.Element;
    valueContent?: JSX.Element;
    [key: string]: unknown;
};

type RS2CompatProps = {
    /**
     * Default Selected Value
     */
    defaultValue?: string;
    /**
     * Selected Value
     */
    value?: string;

    quiet?: boolean;
    /**
     * Flag that decides whether to display label
     */
    placeholder?: string;
    invalid?: boolean;
    /**
     * Select Dropdown options with label and value
     */
    options: (OptionObject | 'divider')[];

    /**
     * Callback function to be called on change
     */
    onChange?: (value: string) => void;

    /**
     * Callback function to be called on close
     */
    onClose?: (event: Event) => void;

    /**
     * Callback function to be called on open
     */
    onOpen?: (event: Event) => void;

    /**
     * A function that returns a wrapper component to render a list item label.
     * Useful in providing custom html to the rendered label.
     */
    renderItem?: (option: OptionObject) => React.ReactNode;

    /**
     * Flag that sets placement to bottom-end
     */
    alignRight?: boolean;

    /**
     * Allows the Select button to grow past the fixed 100px width. RS2 only.
     */
    flexible?: boolean;

    /**
     * Defines a classname for the generated menu. RS2 only.
     */
    menuClassName?: string;
};

export default createWrapper<SelectType, RS2CompatProps>({
    displayName: 'Select',
    fallback: forwardRef(function Select(props, ref) {
        const { children, ...rest } = props;
        if (RS2Select) {
            return (
                <RS2Select {...rest} ref={ref}>
                    {React.Children.map(children, (child) =>
                        React.isValidElement(child)
                            ? React.cloneElement(child, {
                                  // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                                  // @ts-ignore
                                  forceFallback: true,
                              })
                            : child
                    )}
                </RS2Select>
            );
        }
        return null;
    }),
    swcLoader,
    SWCWrapper: function SpSelectPreview(props) {
        const selectWrapperRef = useRef<SelectType>(null);
        const {
            defaultValue,
            className,
            value,
            quiet,
            disabled,
            placeholder,
            placement,
            invalid,
            options,
            alignRight,
            // eslint-disable-next-line @typescript-eslint/no-unused-vars
            flexible,
            // eslint-disable-next-line @typescript-eslint/no-unused-vars
            menuClassName,
            onChange,
            onClose,
            onOpen,
            renderItem,
            ...rest
        } = props;

        useEffect(() => {
            const current = selectWrapperRef.current;

            const change = (event: Event) => {
                const target = event.target as SelectType;
                if (onChange) {
                    onChange(target.value);
                }
            };

            if (current && onChange) {
                current.addEventListener('change', change);
            }

            return () => {
                if (current && onChange) {
                    current.removeEventListener('change', change);
                }
            };
        }, [onChange]);

        useEffect(() => {
            const current = selectWrapperRef.current;

            const handleClose = (event: Event) => {
                if (onClose) {
                    onClose(event);
                }
            };

            if (current && onClose) {
                current.addEventListener('sp-closed', handleClose);
            }

            return () => {
                if (current && onClose) {
                    current.removeEventListener('sp-closed', handleClose);
                }
            };
        }, [onClose]);

        useEffect(() => {
            const current = selectWrapperRef.current;

            const handleOpen = (event: Event) => {
                if (onOpen) {
                    onOpen(event);
                }
            };

            if (current && onOpen) {
                current.addEventListener('sp-opened', handleOpen);
            }

            return () => {
                if (current && onOpen) {
                    current.removeEventListener('sp-opened', handleOpen);
                }
            };
        }, [onOpen]);

        // ReactSpectrum2        | SpectrumWebComponent
        // ---------------------------------------------
        // placeholder           | label
        // options               | menu item use the options
        // defaultValue |value   | value
        // alignRight            | placement='bottom-end'
        // menuClassName         | n/a
        // flexible              | n/a (always flexible)

        const SWCSelectProps = {
            label: placeholder,
            value: defaultValue || value,
            placement: alignRight ? 'bottom-end' : placement,
            ...rest,
        };
        const booleanProps = filterBooleanProps({
            invalid,
            disabled,
            quiet,
        });
        const selectChildren: React.ReactNode =
            options &&
            options.map((option: OptionObject | 'divider', index) => {
                if (option === 'divider') {
                    return <MenuDivider key={`divider-${index}`} />;
                }
                return (
                    <MenuItem
                        {...filterBooleanProps({ disabled: option.disabled })}
                        description={option.description}
                        icon={option.icon}
                        key={option.value}
                        value={option.value}
                        valueContent={option.valueContent}
                    >
                        {renderItem ? renderItem(option) : option.label}
                    </MenuItem>
                );
            });

        const Picker = useComponent('sp-picker');
        return (
            <Picker
                ref={selectWrapperRef}
                class={className}
                {...SWCSelectProps}
                {...booleanProps}
            >
                {selectChildren}
            </Picker>
        );
    },
    tagName: 'sp-picker',
});
