/**
 * PickerMode is an enum for quickly configuring parts of CDP UI to show/hide various
 * features including tabs, buttons, and behvaioral changes. Modes can be sent through several APIs including through
 * Panel.tsx, Commands.tsx, and WebCommands.tsx, returned from host.getPickerInfo() calls and
 * through a PICKERSTATECHANGED event sent from UXP which provides the new mode.
 * The mode is also sent through executeValidPickerAction call into the host.
 */
export var PickerMode;
(function (PickerMode) {
    /**
     * Place mode that is for the 2021 Place workflow. This mode will be just like Open but will have different
     * analytics and a different callback.
     */
    PickerMode["placeLinkOrEmbed"] = "placeLinkOrEmbed";
    /**
     * Link Assets mode that is primarily used with XD. This mode is not considered a "Save As" mode meaning
     * it's primarily used for "Opening Documents" scenarios.
     * Visible Tabs - Cloud Documents, Shared With You, Convert To Sketch Libraries.
     */
    PickerMode["linkAssets"] = "linkAssets";
    /**
     * The primary mode for users when selecting documents to open. When a document is clicked, it's
     * selected and then highlights the "Open" button so the user can opened the selected document.
     * This mode is not considered a "Save As" view mode.
     * Visible Tabs - Recent Tab, Cloud Documents Tab, Shared With you tab.
     */
    PickerMode["open"] = "open";
    /**
     * The primary mode for CDP when Saving Documents to the host application. Shows the "Save As" header
     * with an input for the user to type. This mode is unlike "Opening" modes in that the users is supposed
     * to provide a name for the file to be saved. It  shows a "Save" Button and no "On Your Computer"
     * buttons. When an item is clicked, we set the Save As Input field to the name of the item that was clicked.
     */
    PickerMode["saveAs"] = "saveAs";
    /**
     * This is another "Save As" mode that shoud be identical to PickerMode.saveAs. The main difference
     * here is for the host app to know when a user invoked Save As Copy instead of just a plain
     * Save As. When an item is clicked, we set the Save As Input field to the name of the item that was clicked.
     */
    PickerMode["saveAsCopy"] = "saveAsCopy";
    PickerMode["saveToFolder"] = "saveToFolder";
    /**
     * This is another "Save As" mode that shoud be similar (not identical) to PickerMode.saveAs. Header and
     * primaryButton labels will display 'export' specific labelling. Like "Save As", user can update the name of
     * exported asset and choose the export format.
     */
    PickerMode["export"] = "export";
    /**
     * Copy items to Projects or Cloud Documents.
     */
    PickerMode["copy"] = "copy";
    /**
     * Generic move for moving items to new location.
     */
    PickerMode["move"] = "move";
    /**
     * Move item(s) to a target location. (e.g. assets from Files to Projects)
     */
    PickerMode["moveFrom"] = "moveFrom";
    /**
     * Generic mode for selecting an asset and returning it to the caller
     */
    PickerMode["add"] = "add";
    /**
     * Similar to "Add," but used for opening assets in a Firefly board.
     * The Boards tab is selected by default, the side nav is always hidden,
     * and the CTA label is "Open in board."
     */
    PickerMode["openInBoard"] = "openInBoard";
})(PickerMode || (PickerMode = {}));
