const createPrimaryActionClickEvent = (params)=>{
    const { destination_location, subcategory, subtype, extension, view_type } = params;
    return {
        event: {
            subcategory,
            subtype,
            type: 'click',
            workflow: 'Document-Operation'
        },
        content: {
            category: 'Cloud Documents',
            ...extension && {
                extension
            },
            ...destination_location && {
                destination_location
            }
        },
        ...view_type && {
            ui: {
                view_type
            }
        }
    };
};
export { createPrimaryActionClickEvent };
