/**
 * @torq-native/react-spectrum exports CommonJS modules:
 * https://git.corp.adobe.com/torq/react-spectrum/blob/develop/src/Provider/index.js#L20
 * @react/react-spectrum exports ES6 modules:
 * https://github.com/adobe/react-spectrum/blob/main/packages/%40react-spectrum/provider/src/Provider.tsx#L123
 * Ensure that we can import both types of modules isomorphically by
 * wrapping required CommonJS or ES6 modules and making them compatible with the ES6 module import syntax.
 * This is usually achieved by using Babel's `@babel/plugin-transform-modules-commonjs` plugin:
 * https://babeljs.io/docs/babel-plugin-transform-modules-commonjs#importinterop
 * but we don't want to add Babel as a dependency to this project.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default function interopRequireDefault(obj: any) {
    // eslint-disable-next-line @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-assignment
    return obj?.__esModule ? obj : { default: obj };
}
