// RS2 :: https://react-spectrum.corp.adobe.com/storybook/?path=/story/fieldlabel--default
// SWC :: https://opensource.adobe.com/spectrum-web-components/components/field-label/
// Using Dialog Wrapper from dialog which implements similar properties as RS2.
import type {
    Dialog as DialogType,
    DialogBase as DialogBaseType,
    DialogWrapper as DialogWrapperType,
} from '@ccx-public/spectrum-web-component-fallbacks/dist/dialog';
import React, { forwardRef, useEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { filterBooleanProps, useComponent } from './utils';
import createWrapper from './utils/createWrapper';
import { SWCLoader } from './utils/SWCLoader';
import interopRequireDefault from './utils/interopRequireDefault';
import mergeRefs from './utils/mergeRefs';

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2Dialog: React.ComponentType<unknown> = process.env.INCLUDE_RS2
    ? interopRequireDefault(require('react-spectrum/Dialog')).default
    : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

let swcLoader;
if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(
        ['sp-dialog', 'sp-dialog-base', 'sp-dialog-wrapper'],
        async () => {
            const { Dialog, DialogBase, DialogWrapper } = await import(
                /* webpackChunkName: "SpDialog" */
                '@ccx-public/spectrum-web-component-fallbacks/dist/dialog'
            );
            return [Dialog, DialogBase, DialogWrapper];
        }
    );
}

type RS2CompatProps = {
    /**
     * Can dismiss by clicking on the backdrop
     */
    backdropClickable?: boolean;

    /**
     * Label of the cancel button
     */
    cancelLabel?: string;

    /**
     * Label of the confirm button
     */
    confirmLabel?: string;

    /**
     * Whether it is a dismissible dialogs. Dismissible dialogs should not have buttons.
     */
    isDismissible?: boolean;

    /**
     * Callback when dialog closes via cancel button
     */
    onCancel?: () => void;

    /**
     * Callback when dialog closes
     */
    onClose?: () => void;

    /**
     * Callback when dialog closes via confirm button
     */
    onConfirm?: (type: string, evt: Event) => void;

    /**
     * For ARIA telling what type of dialog this is
     */
    role?: string;

    /**
     * Label for an additional button
     */
    secondaryLabel?: string;

    /**
     * Title of the dialog
     */
    title?: string;
};

export default createWrapper<DialogWrapperType, RS2CompatProps>({
    displayName: 'Dialog',
    fallback: RS2Dialog,
    swcLoader,
    SWCWrapper: function SpDialogWrapper(props) {
        const dialogWrapperRef = useRef<DialogWrapperType>(null);

        const {
            backdropClickable,
            cancelLabel,
            children,
            className,
            confirmLabel,
            isDismissible,
            onCancel,
            onClose,
            onConfirm,
            open,
            secondaryLabel,
            title,
            underlay,
            ...rest
        } = props;

        useEffect(() => {
            const current = dialogWrapperRef?.current;

            if (current && onClose) {
                current.addEventListener('close', onClose);
            }

            return () => {
                if (current && onClose) {
                    current.removeEventListener('close', onClose);
                }
            };
        }, [onClose]);

        useEffect(() => {
            const current = dialogWrapperRef?.current;
            const handleConfirm = (evt: Event) => {
                onConfirm?.(evt.type, evt);
                if (current) {
                    current.open = false;
                }
            };

            if (current && onConfirm) {
                current.addEventListener('confirm', handleConfirm);
                current.addEventListener('secondary', handleConfirm);
            }

            return () => {
                if (current && onConfirm) {
                    current.removeEventListener('confirm', handleConfirm);
                    current.removeEventListener('secondary', handleConfirm);
                }
            };
        }, [onConfirm]);

        useEffect(() => {
            const current = dialogWrapperRef?.current;
            const handleCancel = () => {
                onCancel?.();
                if (current) {
                    current.open = false;
                }
            };

            if (current && onCancel) {
                current.addEventListener('cancel', handleCancel);
            }

            return () => {
                if (current && onCancel) {
                    current.removeEventListener('cancel', handleCancel);
                }
            };
        }, [onCancel]);

        const childrenWrapperRef = useRef<HTMLDivElement>(null);
        const [, forceUpdate] = useState(false);

        useEffect(() => {
            forceUpdate(true);
        }, []);

        // ReactSpectrum2               | SpectrumWebComponent
        // ---------------------------------------------------
        // isDismissible                | dismissable
        // title                        | headline
        // confirmLabel                 | confirm-label
        // cancelLabel                  | cancel-label
        // secondaryLabel               | secondary-label
        // backdropClickable or open    | underlay

        const DialogWrapper = useComponent('sp-dialog-wrapper');
        return (
            <>
                <DialogWrapper
                    {...rest}
                    {...filterBooleanProps({
                        dismissable: isDismissible,
                        open,
                        underlay:
                            (underlay || backdropClickable || open) ?? true,
                    })}
                    ref={dialogWrapperRef}
                    class={className}
                    headline={title}
                    confirm-label={confirmLabel}
                    cancel-label={cancelLabel}
                    secondary-label={secondaryLabel}
                >
                    <div ref={childrenWrapperRef} />
                </DialogWrapper>
                {childrenWrapperRef.current &&
                    createPortal(children, childrenWrapperRef.current)}
            </>
        );
    },
    tagName: 'sp-dialog-wrapper',
});

type DialogCompatProps = Pick<RS2CompatProps, 'onClose'>;
/**
 * DialogContent wraps SWC's sp-dialog and does not have an exact RS2 equivalent.
 * This has been added to spectrum-wrapper because:
 *
 * 1. In UAB, hosts provide a `showModal` function where pass them the content
 *    that we want to show in a dialog. This should have the behavior and
 *    accessibility roles of a role="dialog" element such as sp-dialog, but
 *    without the extra behavior that comes along with sp-dialog-wrapper or
 *    RS2's Dialog like showing/closing the dialog or rendering an underlay.
 * 2. UAB also does not currently have a requirement to run in UXP and so does
 *    not require an RS2 fallback.
 * 3. It is still useful to use spectrum-wrapper rather than SWC directly so
 *    that there is still the async loading of SWC components and automatic
 *    re-use of SWC components already loaded and registered in the host app.
 */
export const DialogContent = createWrapper<DialogType, DialogCompatProps>({
    displayName: 'Dialog',
    fallback: RS2Dialog,
    swcLoader: swcLoader,
    SWCWrapper: forwardRef(function SpDialog(
        { dismissable, error, noDivider, onClose, ...rest },
        forwardRef
    ) {
        const DialogContent = useComponent('sp-dialog');
        const ref = useRef<DialogType>(null);

        useEffect(() => {
            const { current } = ref;

            if (current && onClose) {
                current.addEventListener('close', onClose);
            }

            return () => {
                if (current && onClose) {
                    current.removeEventListener('close', onClose);
                }
            };
        }, [onClose]);

        return (
            <DialogContent
                {...rest}
                {...filterBooleanProps({ dismissable, error, noDivider })}
                ref={mergeRefs([forwardRef, ref])}
            />
        );
    }),
    tagName: 'sp-dialog',
});

type DialogBaseCompatProps = Pick<RS2CompatProps, 'onClose'>;

/**
 * DialogBase wraps SWC's sp-dialog-base and does not have a direct equivalent
 * in RS2. It has been added to spectrum-wrapper only as a complement to
 * DialogContent above. At the time of writing it's not expected that this would
 * actually be used in production, but it is useful in local development
 * environments to show DialogContent in a modal dialog context.
 */
export const DialogBase = createWrapper<DialogBaseType, DialogBaseCompatProps>({
    displayName: 'Dialog',
    fallback: RS2Dialog,
    swcLoader: swcLoader,
    SWCWrapper: forwardRef(function SpDialog(
        { dismissable, onClose, open, responsive, underlay, ...rest },
        forwardRef
    ) {
        const DialogBase = useComponent('sp-dialog-base');
        const ref = useRef<DialogBaseType>(null);

        useEffect(() => {
            const { current } = ref;

            if (current && onClose) {
                current.addEventListener('close', onClose);
            }

            return () => {
                if (current && onClose) {
                    current.removeEventListener('close', onClose);
                }
            };
        }, [onClose]);

        return (
            <DialogBase
                {...rest}
                {...filterBooleanProps({
                    dismissable,
                    open,
                    responsive,
                    underlay,
                })}
                ref={mergeRefs([forwardRef, ref])}
            />
        );
    }),
    tagName: 'sp-dialog-base',
});
