import type { SyntheticEvent } from 'react';
import React, { useEffect, useRef } from 'react';

// https://opensource.adobe.com/spectrum-web-components/components/action-menu/
// https://git.corp.adobe.com/torq/react-spectrum/tree/develop/src/DropdownButton
import type { ActionMenu as ActionMenuType } from '@ccx-public/spectrum-web-component-fallbacks/dist/action-menu';
import type { ReactProps } from './utils';
import { SWCLoader } from './utils/SWCLoader';
import createWrapper from './utils/createWrapper';
import { filterBooleanProps, useComponent } from './utils';
import mergeRefs from './utils/mergeRefs';

type RS2DropdownButtonCompatProps = {
    label?: string;
    // RS2 icon prop will get transformed into an icon slot for SWC.
    icon?: JSX.Element;
    onBlur?: (event: SyntheticEvent) => void;
    onClick?: (event: SyntheticEvent) => void;
    onFocus?: (event: SyntheticEvent) => void;
    onSelect?: (option: string) => void;
    alignRight?: boolean;
    'aria-label'?: string;
};

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2DropdownButton: React.ComponentType<
    ReactProps<ActionMenuType, RS2DropdownButtonCompatProps>
> = process.env.INCLUDE_RS2
    ? require('react-spectrum/DropdownButton').default
    : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

function getButtonIcon(
    icon?: RS2DropdownButtonCompatProps['icon']
): React.ReactNode {
    if (!icon) {
        return;
    }

    return React.cloneElement(icon, { slot: 'icon' });
}

let swcLoader;
if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(['sp-action-menu'], async () => {
        const { ActionMenu } = await import(
            /* webpackChunkName: "SpActionMenu" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/action-menu'
        );
        return [ActionMenu];
    });
}

// Temporary work around due to SWC bug causing @change to be fired twice for tablet devices
// https://github.com/adobe/spectrum-web-components/issues/5556
// Once this is resolved we can remove this debounce and upgrade the SWC version
function debounce<T extends (...args: any[]) => any>(
    func: T,
    wait: number
): (...args: Parameters<T>) => void {
    let timeoutId: NodeJS.Timeout | null = null;

    return (...args: Parameters<T>): void => {
        if (timeoutId !== null) {
            clearTimeout(timeoutId);
        }

        timeoutId = setTimeout(() => {
            func(...args);
        }, wait);
    };
}

const isLargeTouchScreen = () => {
    const SWC_MOBILE_BREAKPOINT = 743;
    return (
        matchMedia('(pointer:coarse)').matches &&
        window.screen.width > SWC_MOBILE_BREAKPOINT
    );
};

const DEBOUNCE_TIMEOUT = isLargeTouchScreen() ? 50 : 0;

export default createWrapper<ActionMenuType, RS2DropdownButtonCompatProps>({
    displayName: 'DropdownButton',
    fallback: React.forwardRef(function DropdownButtonFallback(props, ref) {
        const { children, ...rest } = props;
        if (RS2DropdownButton) {
            return (
                <RS2DropdownButton {...rest} ref={ref}>
                    {React.Children.map(children, (child) =>
                        React.isValidElement(child)
                            ? React.cloneElement(child, {
                                  // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                                  // @ts-ignore
                                  forceFallback: true,
                              })
                            : child
                    )}
                </RS2DropdownButton>
            );
        }
        return null;
    }),
    swcLoader,
    SWCWrapper: React.forwardRef(function DropdownButtonSWC(props, ref) {
        const actionMenuWrapperRef = useRef<ActionMenuType>(null);
        const {
            className,
            children,
            icon,
            label,
            onSelect,
            disabled,
            focused,
            invalid,
            open,
            quiet,
            readonly,
            alignRight,
            placement,
            'aria-label': ariaLabel,
            ...rest
        } = props;
        const buttonIcon = getButtonIcon(icon);
        const labelContents = label ? <span slot="label">{label}</span> : null;
        const menuPlacement = alignRight ? 'bottom-end' : placement;

        useEffect(() => {
            const { current } = actionMenuWrapperRef;

            const debouncedOnSelect = debounce((value: string) => {
                onSelect?.(value);
            }, DEBOUNCE_TIMEOUT);

            const handleSelect = (event: Event) => {
                const target = event.target as HTMLInputElement;
                const value = target.value;
                debouncedOnSelect(value);
            };

            if (current && onSelect) {
                current.addEventListener('change', handleSelect);
            }

            return () => {
                if (current && onSelect) {
                    current.removeEventListener('change', handleSelect);
                }
            };
        }, [onSelect]);

        const SWCActionMenuProps = {
            ...filterBooleanProps({
                disabled,
                focused,
                invalid,
                open,
                quiet,
                readonly,
            }),
            label: ariaLabel,
            placement: menuPlacement,
            ...rest,
        };

        const ActionMenu = useComponent('sp-action-menu');
        return (
            <ActionMenu
                ref={mergeRefs([actionMenuWrapperRef, ref])}
                class={className}
                {...SWCActionMenuProps}
            >
                {buttonIcon}
                {labelContents}
                {typeof children !== 'string' && children}
            </ActionMenu>
        );
    }),
    tagName: 'sp-action-menu',
});
