class Subscribable {
    notifySubscribers(name, ...values) {
        this.initSubscriptionMap(name);
        for (const fn of this.subscriptions[name].values())fn(...values);
    }
    subscribe(name, key, fn) {
        this.initSubscriptionMap(name);
        this.subscriptions[name].set(key, fn);
    }
    unsubscribe(name, key) {
        this.initSubscriptionMap(name);
        this.subscriptions[name].delete(key);
    }
    initSubscriptionMap(name) {
        if (!this.subscriptions[name]) this.subscriptions[name] = new Map();
    }
    constructor(){
        this.subscriptions = {};
    }
}
export { Subscribable };
