// https://opensource.adobe.com/spectrum-web-components/components/status-light/
// There will be no RS2 fallback.
import type { StatusLight as StatusLightType } from '@ccx-public/spectrum-web-component-fallbacks/dist/status-light';
import { filterBooleanProps } from './utils';
import createWrapper from './utils/createWrapper';
import { SWCLoader } from './utils/SWCLoader';

let swcLoader;
if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(['sp-status-light'], async () => {
        const { StatusLight } = await import(
            /* webpackChunkName: "SpStatusLight" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/status-light'
        );
        return [StatusLight];
    });
}

export default createWrapper<StatusLightType>({
    displayName: 'StatusLight',
    fallback: undefined,
    swcLoader,
    swcProps: (props) => {
        const { className, disabled, ...rest } = props;

        return {
            ...rest,
            ...filterBooleanProps({
                disabled,
            }),
            class: className,
        };
    },
    tagName: 'sp-status-light',
});
