// https://opensource.adobe.com/spectrum-web-components/components/illustrated-message
// https://git.corp.adobe.com/torq/react-spectrum/tree/develop/src/IllustratedMessage
import type { IllustratedMessage as IllustratedMessageType } from '@ccx-public/spectrum-web-component-fallbacks/dist/illustrated-message';
import createWrapper from './utils/createWrapper';
import { SWCLoader } from './utils/SWCLoader';
import interopRequireDefault from './utils/interopRequireDefault';
import React from 'react';

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2IllustratedMessage: React.ComponentType<unknown> = process.env
    .INCLUDE_RS2
    ? interopRequireDefault(require('react-spectrum/IllustratedMessage'))
          .default
    : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

let swcLoader;
if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(['sp-illustrated-message'], async () => {
        const { IllustratedMessage } = await import(
            /* webpackChunkName: "SpIllustratedMessage" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/illustrated-message'
        );
        return [IllustratedMessage];
    });
}

type RS2CompatProps = {
    /** The heading level for the heading element to preserve hierarchy of headings in web page for accessibility. */
    ariaLevel?: number;

    /**
     * The description attribute in sp-illustrated-message only accepts a
     * string, but we override it to use a slot instead so that you can pass a
     * ReactNode.
     */
    description?: React.ReactNode;

    /**
     * The illustration to be rendered above heading. Should be an SVG element.
     */
    illustration?: React.ReactNode;
};

export default createWrapper<IllustratedMessageType, RS2CompatProps>({
    displayName: 'IllustratedMessage',
    fallback: RS2IllustratedMessage,
    swcLoader,
    swcProps: (props) => {
        const { ariaLevel, className, description, illustration, ...rest } =
            props;

        // ReactSpectrum2        | SpectrumWebComponent
        // ---------------------------------------------
        // heading               | heading
        // description           | description
        // illustration          | drop-in as default slot
        // ariaLevel             |

        // illustration is for rendering icon in RS2 but dropped into default slot for spectrum web component
        // ariaLevel is used for accessibility in RS2 only

        return {
            ...rest,
            ariaLevel: ariaLevel?.toString(),
            class: className,
            children: (
                <>
                    {illustration}
                    {description && (
                        <div slot="description" style={{ display: 'contents' }}>
                            {description}
                        </div>
                    )}
                </>
            ),
        };
    },
    tagName: 'sp-illustrated-message',
});
