import { Status } from "@dunamis-public/types";
export class DunamisError extends Error {
    constructor(status, message) {
        super(message !== null && message !== void 0 ? message : Status[status]);
        this.status_ = Status.SUCCESS;
        this.status_ = status;
    }
    get status() {
        return this.status_;
    }
}
