import type { SyntheticEvent } from 'react';
import React from 'react';
import { filterBooleanProps } from './utils';
import type {
    SideNavHeading as SideNavHeadingType,
    SideNav as SideNavType,
    SideNavItem as SideNavItemType,
} from '@ccx-public/spectrum-web-component-fallbacks/dist/sidenav';
import createWrapper from './utils/createWrapper';
import { SWCLoader } from './utils/SWCLoader';
import interopRequireDefault from './utils/interopRequireDefault';

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires */
const RS2SideNav: {
    SideNav: React.ComponentType<unknown>;
    SideNavHeading: React.ComponentType<unknown>;
    SideNavItem: React.ComponentType<unknown>;
} = process.env.INCLUDE_RS2
    ? interopRequireDefault(require('react-spectrum/SideNav'))
    : {};
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires */

let swcLoader;
if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(
        ['sp-sidenav', 'sp-sidenav-item', 'sp-sidenav-heading'],
        async () => {
            const { SideNav, SideNavItem, SideNavHeading } = await import(
                /* webpackChunkName: "SpSideNav" */
                '@ccx-public/spectrum-web-component-fallbacks/dist/sidenav'
            );
            return [SideNav, SideNavItem, SideNavHeading];
        }
    );
}

// https://opensource.adobe.com/spectrum-web-components/components/sidenav/
// https://git.corp.adobe.com/torq/react-spectrum/tree/develop/src/SideNav

type RS2SideNavCompatProps = {
    variant?: 'multilevel' | undefined;
    value?: string;
    defaultValue?: string;
};

export const SideNav = createWrapper<SideNavType, RS2SideNavCompatProps>({
    displayName: 'SideNav',
    fallback: RS2SideNav.SideNav,
    swcLoader,
    swcProps: (props) => {
        const { value, defaultValue, className, ...rest } = props;

        // ReactSpectrum2        | SpectrumWebComponent
        // ---------------------------------------------
        // handling value and defaultValue

        return {
            ...rest,
            value: defaultValue || value,
            class: className,
        };
    },
    tagName: 'sp-sidenav',
});

type RS2SideNavHeadingCompatProps = {
    label?: string;
    onClick?: (event: SyntheticEvent) => void;
};

export const SideNavHeading = createWrapper<
    SideNavHeadingType,
    RS2SideNavHeadingCompatProps
>({
    displayName: 'SideNavHeading',
    fallback: RS2SideNav.SideNavHeading,
    swcLoader,
    swcProps: (props) => {
        const { className, label, ...rest } = props;

        return {
            ...rest,
            class: className,
            label: label,
        };
    },
    tagName: 'sp-sidenav-heading',
});

type RS2SideNavItemCompatProps = {
    disabled?: boolean;
    /**
     * sp-sidenav-item supports icons via the 'icon' slot, RS2 supports icon
     * via the 'icon' prop.
     */
    icon?: React.ReactElement<{ slot: string }>;
    onClick?: (event: React.MouseEvent) => unknown;
};

export const SideNavItem = createWrapper<
    SideNavItemType,
    RS2SideNavItemCompatProps
>({
    displayName: 'SideNavItem',
    fallback: RS2SideNav.SideNavItem,
    swcLoader,
    swcProps: (props) => {
        const { children, className, disabled, icon, ...rest } = props;

        return {
            ...rest,
            ...filterBooleanProps({ disabled }),
            children: (
                <>
                    {children}
                    {icon && React.cloneElement(icon, { slot: 'icon' })}
                </>
            ),
            class: className,
        };
    },
    tagName: 'sp-sidenav-item',
});
