import { Environment } from "@dunamis-public/types";
import { endpoint_dunamis_prod, endpoint_dunamis_stage, header_content_type, header_x_api_key, json_mime_type, path_ingest, protocol_https, } from "@dunamis-common/constants";
import { Request } from "@dunamis-core/http/request";
import { Method } from "@dunamis-core/http/types";
import { appendPathToURL } from "@dunamis-core/utils/url";
export class IngestApi {
    constructor(endpoint) {
        this.endpoint_ = endpoint;
    }
    static getEndpoint(env) {
        let endpoint = endpoint_dunamis_prod;
        switch (env) {
            case Environment.STAGE:
                endpoint = endpoint_dunamis_stage;
                break;
            case Environment.PROD:
                endpoint = endpoint_dunamis_prod;
                break;
            default:
                endpoint = endpoint_dunamis_prod;
                break;
        }
        return protocol_https + endpoint;
    }
    request(apiKey, body) {
        const fetchUrl = appendPathToURL(this.endpoint_, path_ingest);
        return new Request(fetchUrl, Method.Post)
            .addHeader(header_x_api_key, apiKey)
            .addHeader(header_content_type, json_mime_type)
            .setBody(body);
    }
}
