import type {
    ProviderConfig,
    ProviderPreloadProps,
} from './utils/ThemeContext';
import { getProviderConfig } from './utils/ThemeContext';

type Loader = (config: ProviderConfig) => Promise<unknown>;

const _loaders: Loader[] = [];

export function _register(loader: Loader) {
    _loaders.push(loader);
}

export default function preload(props: ProviderPreloadProps = {}) {
    const config = getProviderConfig(props);
    const loaders = [..._loaders.map((loader) => loader(config))];
    return Promise.all(loaders);
}
