import { LogLevel } from "@dunamis-public/types";
import { logLevelToString } from "@dunamis-core/types/core_types";
import { Logger } from "./logger";
function LOG(level, tag, message) {
    const logger = Logger.getLogger();
    if (level <= logger.getLogLevel()) {
        logger.log(logLevelToString(level), tag, message);
    }
}
export function LOG_ALWAYS(tag, message) {
    LOG(LogLevel.ALWAYS, tag, message);
}
export function LOG_ERROR(tag, message) {
    LOG(LogLevel.ERROR, tag, message);
}
export function LOG_WARN(tag, message) {
    LOG(LogLevel.WARN, tag, message);
}
export function LOG_INFO(tag, message) {
    LOG(LogLevel.INFO, tag, message);
}
export function LOG_DEBUG(tag, message) {
    LOG(LogLevel.DEBUG, tag, message);
}
export function LOG_TRACE(tag, message) {
    LOG(LogLevel.TRACE, tag, message);
}
