export class Request {
    constructor(url, method) {
        this.headers_ = {};
        this.body_ = {};
        this.url_ = url;
        this.method_ = method;
    }
    url() {
        return this.url_;
    }
    setBody(body) {
        this.body_ = body;
        return this;
    }
    addHeader(key, value) {
        this.headers_[key] = value;
        return this;
    }
    method() {
        return this.method_;
    }
    header() {
        return this.headers_;
    }
    body() {
        return this.body_;
    }
}
