import type { ActionButton as ActionButtonType } from '@ccx-public/spectrum-web-component-fallbacks/dist/action-button';
import type {
    Button as ButtonType,
    ButtonVariants,
} from '@ccx-public/spectrum-web-component-fallbacks/dist/button';
import type { SyntheticEvent } from 'react';
import React, { forwardRef } from 'react';
import type { ReactProps, SpectrumElementProps } from './utils';
import { filterBooleanProps } from './utils';
import createWrapper from './utils/createWrapper';
import { SWCLoader } from './utils/SWCLoader';
import interopRequireDefault from './utils/interopRequireDefault';

// eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
const RS2Button: React.ComponentType<unknown> = process.env.INCLUDE_RS2
    ? // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-var-requires
      interopRequireDefault(require('react-spectrum/Button')).default
    : undefined;

let swcActionButtonLoader;
let swcButtonLoader;
if (!process.env.EXCLUDE_SWC) {
    swcActionButtonLoader = new SWCLoader(['sp-action-button'], async () => {
        const { ActionButton } = await import(
            /* webpackChunkName: "SpActionButton" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/action-button'
        );
        return [ActionButton];
    });

    swcButtonLoader = new SWCLoader(['sp-button'], async () => {
        const { Button } = await import(
            /* webpackChunkName: "SpButton" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/button'
        );
        return [Button];
    });
}

type RS2ButtonCompatProps = {
    // RS2: autoFocus, SWC: autofocus
    autoFocus?: boolean;
    // RS2-only prop that Dropdown looks for in its children.
    dropdownTrigger?: boolean;
    // RS2-only prop to switch the html element
    element?: string;
    // RS2: holdAffordance, SWC: hold-affordance. React seems to handle this
    holdAffordance?: boolean;
    // SWC will automatically slot content into an anchor tag if passed
    href?: string;
    // RS2 icon prop will get transformed into an icon slot for SWC.
    icon?: JSX.Element;
    // RS2-only to be used for variants 'and' and 'or'
    logic?: boolean;
    onBlur?: (event: SyntheticEvent) => unknown;
    /**
     * RS2: onClick, SWC: onclick. React seems to handle this
     * automatically, but we need this here for typescript.
     */
    onClick?: (event: SyntheticEvent) => unknown;
    onFocus?: (event: SyntheticEvent) => unknown;
    // Fixing a typescript incompatibility. No runtime fixes needed.
    role?: string;
    /**
     * Selected is relevant for:
     *  - SWC sp-action-button
     *  - RS2 with variant="action"
     * It is _not_ relevant for SWC sp-button
     */
    selected?: ActionButtonType['selected'];
    variant?: ButtonVariants | 'warning' | 'action' | 'tool' | 'and' | 'or';
    value?: string;
    // RS2-UXP-only prop
    uxpUseNative?: boolean;
};

type ButtonProps = ReactProps<ButtonType, RS2ButtonCompatProps>;

// SWC > 1.0 changed 'staticColor' to 'static-color'
type ButtonTypeKebabCase<T> = {
    [K in keyof T as K extends 'staticColor' ? 'static-color' : K]: T[K];
};
type SWCButtonType = ButtonTypeKebabCase<ButtonType>;

function getButtonIcon(icon?: ButtonProps['icon']): React.ReactNode {
    if (!icon) {
        return;
    }

    return React.cloneElement(icon, {
        key:
            icon.key ||
            // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access,@typescript-eslint/restrict-template-expressions
            `key-${icon.type?.render?.displayName || icon.type?.displayName}`,
        slot: 'icon',
    });
}

function spButtonVariantProps(
    variant?: ButtonProps['variant'],
    treatment?: ButtonProps['treatment']
): Partial<SpectrumElementProps<SWCButtonType>> {
    switch (variant) {
        case 'accent':
        case 'cta':
            return {
                variant: 'accent',
                treatment: treatment || 'fill',
            };
        case 'primary':
        case 'secondary':
            return {
                variant,
                treatment: treatment || 'outline',
            };
        case 'warning':
            return {
                variant: 'negative',
                treatment: treatment || 'outline',
            };
        case 'overBackground':
            return {
                'static-color': 'white',
                treatment: treatment || 'outline',
            };
        case 'action':
        case 'tool':
        case 'and':
        case 'or':
            return {};
        case undefined:
            return {
                variant: 'primary',
                treatment: 'outline',
            };
        default:
            return { variant };
    }
}

const NormalButton = createWrapper<ButtonType, RS2ButtonCompatProps>({
    displayName: 'Button',
    fallback: RS2Button,
    swcLoader: swcButtonLoader,
    swcProps: (props) => {
        const buttonIcon = getButtonIcon(props.icon);
        const {
            autoFocus,
            className,
            children,
            disabled,
            holdAffordance,
            pending,
            quiet,
            variant,
            /* eslint-disable @typescript-eslint/no-unused-vars */
            // RS2-only props
            dropdownTrigger,
            icon,
            label,
            staticColor,
            uxpUseNative,
            // SWC-only props
            treatment,
            // Non-relevant props
            selected,
            /* eslint-enable @typescript-eslint/no-unused-vars */
            ...rest
        } = props;
        const booleanProps = filterBooleanProps({
            autofocus: autoFocus,
            disabled,
            'hold-affordance': holdAffordance,
            pending,
            quiet,
        });
        const variantProps = spButtonVariantProps(variant, treatment);
        const labelContents =
            label || (typeof children === 'string' ? children : null);

        return {
            ...rest,
            ...(staticColor && { 'static-color': staticColor }),
            ...booleanProps,
            ...variantProps,
            children: [
                buttonIcon,
                labelContents,
                typeof children !== 'string' && children,
            ],
            class: className,
        };
    },
    tagName: 'sp-button',
});

function spActionButtonVariantProps(
    variant: ButtonProps['variant']
): Partial<SpectrumElementProps<ActionButtonType>> {
    if (variant === 'tool') {
        return { quiet: true };
    }

    return {};
}

const ActionButton = createWrapper<ActionButtonType, RS2ButtonCompatProps>({
    displayName: 'ActionButton',
    fallback: RS2Button,
    swcLoader: swcActionButtonLoader,
    swcProps: (props) => {
        const {
            autoFocus,
            children,
            className,
            disabled,
            holdAffordance,
            quiet,
            selected,
            variant,
            /* eslint-disable @typescript-eslint/no-unused-vars */
            // RS2-only props
            dropdownTrigger,
            icon,
            label,
            uxpUseNative,
            /* eslint-enable @typescript-eslint/no-unused-vars */
            ...rest
        } = props;
        const buttonIcon = getButtonIcon(icon);
        const variantProps = spActionButtonVariantProps(variant);
        const booleanProps = filterBooleanProps({
            autofocus: autoFocus,
            disabled,
            'hold-affordance': holdAffordance,
            quiet,
            selected,
        });
        const labelContents =
            label || (typeof children === 'string' ? children : null);

        return {
            ...rest,
            ...booleanProps,
            ...variantProps,
            children: [
                buttonIcon,
                labelContents,
                typeof children !== 'string' && children,
            ],
            class: className,
        };
    },
    tagName: 'sp-action-button',
});

export default forwardRef(function Button(props: ButtonProps, ref) {
    if (
        props.variant === 'action' ||
        props.variant === 'tool' ||
        props.variant === 'and' ||
        props.variant === 'or' ||
        (props.variant === 'secondary' && props.quiet) ||
        (props.variant === 'primary' && props.quiet)
    ) {
        return <ActionButton {...props} ref={ref} />;
    }

    return <NormalButton {...props} ref={ref} />;
});
