/* eslint-disable prettier/prettier */


    import React, { useContext } from "react";
    import { ThemeContext } from "../utils/ThemeContext";

import type { IconSelectBoxAll } from '@ccx-public/spectrum-web-component-fallbacks/dist/icons-workflow/src/elements/IconSelectBoxAll.js';
import { SWCLoader } from '../utils/SWCLoader';
import createWrapper from '../utils/createWrapper';
import { getSWCProps } from './utils';
import type { RS2IconProps } from './utils';
import interopRequireDefault from '../utils/interopRequireDefault';
import type { ProviderConfig } from '../utils/ThemeContext';

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2SelectBoxAll: React.ComponentType<unknown> = process.env.INCLUDE_RS2
    ? interopRequireDefault(require('react-spectrum/Icon/SelectBoxAll')).default
    : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

let swcLoader;
let s2swcLoader;

if (!process.env.EXCLUDE_SWC) {

    swcLoader = new SWCLoader(['sp-icon-select-box-all'], async (config: ProviderConfig) => {
        if (config.spectrumTheme === 'express') {
                // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
                const xIcon = await import(
                    /* webpackChunkName: "XIconSelectBoxAll" */
                    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                    // @ts-ignore
                    '@hz/x-icons/src/components/IconSelectBoxAll.js'
                );
                // eslint-disable-next-line @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unsafe-member-access
                return [xIcon.IconSelectBoxAll];
            }
        const { IconSelectBoxAll } = await import(
            /* webpackChunkName: "SpIconSelectBoxAll" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/icons-workflow/src/elements/IconSelectBoxAll'
        );
        return [IconSelectBoxAll];
    });

    s2swcLoader = new SWCLoader(['sp-icon-select-multi'], async () => {
        const { IconSelectMulti } = await import(
            /* webpackChunkName: "SpIconIconSelectMulti" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/icons-workflow/src/elements/IconSelectMulti'
        );
        return [IconSelectMulti];
    });
}


        
        const S1Icon = createWrapper<IconSelectBoxAll, RS2IconProps>({
            displayName: 'SelectBoxAll',
            fallback: RS2SelectBoxAll,
            swcLoader,
            swcProps: getSWCProps,
            tagName: 'sp-icon-select-box-all',
        });
    
        const S2Icon = createWrapper<IconSelectBoxAll, RS2IconProps>({
            displayName: 'SelectBoxAll',
            fallback: RS2SelectBoxAll,
            swcLoader: s2swcLoader,
            swcProps: getSWCProps,
            tagName: 'sp-icon-select-multi',
        });

        export default (props: React.ComponentProps<typeof S1Icon> & RS2IconProps) => {
            const { spectrumTheme } = useContext(ThemeContext);
            if (spectrumTheme === 'spectrum-two') {
                return <S2Icon {...props} />;
            }
            return <S1Icon {...props} />;
        };
    
/* eslint-enable prettier/prettier */
