// https://opensource.adobe.com/spectrum-web-components/components/divider/
// https://git.corp.adobe.com/torq/react-spectrum/tree/develop/src/Rule
import type { Divider as DividerType } from '@ccx-public/spectrum-web-component-fallbacks/dist/divider';
import type { ElementSize } from '@ccx-public/spectrum-web-component-fallbacks/dist/base';
import { SWCLoader } from './utils/SWCLoader';
import createWrapper from './utils/createWrapper';
import interopRequireDefault from './utils/interopRequireDefault';

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2Rule: React.ComponentType<unknown> = process.env.INCLUDE_RS2
    ? interopRequireDefault(require('react-spectrum/Rule')).default
    : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

let swcLoader;
if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(['sp-divider'], async () => {
        const { Divider } = await import(
            /* webpackChunkName: "SpDivider" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/divider'
        );
        return [Divider];
    });
}

type RS2CompatProps = { variant?: 'small' | 'medium' | 'large' };

const SIZE_MAP: Record<string, ElementSize> = {
    small: 's',
    medium: 'm',
    large: 'l',
};

export default createWrapper<DividerType, RS2CompatProps>({
    displayName: 'Rule',
    fallback: RS2Rule,
    swcLoader,
    swcProps: (props) => {
        const { className, variant = 'large', ...rest } = props;
        // ReactSpectrum2           | SpectrumWebComponent
        // ---------------------------------------------
        // variant:small,           |  size: s,m,l
        // medium,large(default)    |
        // vertical not supported   | vertical supported

        const size = SIZE_MAP[variant];
        return {
            ...rest,
            class: className,
            size,
        };
    },
    tagName: 'sp-divider',
});
