export function appendPathToURL(url, path) {
    if (!url || !path) {
        throw new URIError("URL or path is empty");
    }
    // Make sure the URL ends in a '/'
    if (!url.endsWith("/")) {
        url += "/";
    }
    // Append the path, minus the leading slash, if present
    const startIdx = path.startsWith("/") ? 1 : 0;
    url += path.substring(startIdx);
    return url;
}
