import { header_access_token, path_fetch_user_tracking_flag } from "@dunamis-common/constants";
import { Request } from "@dunamis-core/http/request";
import { Method } from "@dunamis-core/http/types";
import { appendPathToURL } from "@dunamis-core/utils/url";
export class PiipAPI {
    constructor(endpoint) {
        this.endpoint_ = endpoint;
    }
    fetchUserTrackingFlag(accessToken) {
        const fetchUrl = appendPathToURL(this.endpoint_, path_fetch_user_tracking_flag);
        return new Request(fetchUrl, Method.Get).addHeader(header_access_token, accessToken);
    }
}
