import { Themes } from "@csc/common";
const themeToCVTheme = (theme)=>{
    switch(theme){
        case 'light':
        case 'light-express':
            return Themes.light;
        case 'lightest':
        case 'lightest-express':
            return Themes.lightest;
        case 'dark':
        case 'dark-express':
            return Themes.dark;
        case 'darkest':
        case 'darkest-express':
            return Themes.darkest;
        default:
            return;
    }
};
export { themeToCVTheme };
