// https://opensource.adobe.com/spectrum-web-components/components/link/
// https://git.corp.adobe.com/torq/react-spectrum/tree/develop/src/Link
import type { Link as LinkType } from '@ccx-public/spectrum-web-component-fallbacks/dist/link';
import type { SyntheticEvent } from 'react';
import { filterBooleanProps } from './utils';
import createWrapper from './utils/createWrapper';
import { SWCLoader } from './utils/SWCLoader';
import interopRequireDefault from './utils/interopRequireDefault';

/* eslint-disable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */
const RS2Link: React.ComponentType<unknown> = process.env.INCLUDE_RS2
    ? interopRequireDefault(require('react-spectrum/Link')).default
    : undefined;
/* eslint-enable @typescript-eslint/no-unsafe-assignment,@typescript-eslint/no-var-requires,@typescript-eslint/no-unsafe-member-access */

let swcLoader;
if (!process.env.EXCLUDE_SWC) {
    swcLoader = new SWCLoader(['sp-link'], async () => {
        const { Link } = await import(
            /* webpackChunkName: "SpLink" */
            '@ccx-public/spectrum-web-component-fallbacks/dist/link'
        );
        return [Link];
    });
}

type RS2CompatProps = {
    /**
     * Link address
     */
    href?: string;
    /**
     * Whether the link represents a quiet state
     */
    quiet?: boolean;
    /* Called whenever a link is clicked
     */
    onClick?: (event?: SyntheticEvent) => unknown;
    variant?: string;
};

export default createWrapper<LinkType, RS2CompatProps>({
    displayName: 'Link',
    fallback: RS2Link,
    swcLoader,
    swcProps: (props) => {
        const { className, variant, ...rest } = props;
        // ReactSpectrum2           | SpectrumWebComponent
        // ---------------------------------------------
        // variant:quiet            | variant: secondary
        // variant:overBackground   | staticColor
        //        N/A               | quiet

        return {
            ...rest,
            ...filterBooleanProps({
                quiet: variant === 'quiet' ? false : true,
            }),
            class: className,
            'static-color': variant === 'overBackground' ? 'white' : undefined,
            variant: variant === 'quiet' ? 'secondary' : undefined,
        };
    },
    tagName: 'sp-link',
});
